class Report(http.Controller):
    @http.route('/report/dashboard', type='http', auth='user')
    @route()
    def get_dashboard(self, **kw):
        # date ='' + (tools.datetime.now() - tools.timedelta(days=1)).strftime('%Y-%m-%d')
        date = '2018-09-30'
        overview = request.env['sale.overview.template'].search([('company_id', '=', request.env.company.id)], limit=1)
        payer = overview.payer_vs_private
        total_patient = overview.total_patient
        total_payer = overview.total_payer
        total_revenue = "{:,}".format(overview.total_revenue_odoo)
        total_revenue_wipro = "{:,}".format(overview.total_revenue_wipro)
        status_generate = overview.status_generate
        revenue_today = "{:,}".format(overview.revenue_today)
        revenue_percent = "{:,}".format(overview.revenue_yesterday_percent)
        total_bpjs = "{:,}".format(overview.total_bpjs)
        total_patient_bpjs = "{:,}".format(overview.total_patient_bpjs)
        total_pasien_accrual = "{:,}".format(overview.total_pasien_accrual)
        total_ipd = "{:,}".format(overview.total_ipd)
        total_opd = "{:,}".format(overview.total_opd)
        total_farmasi = "{:,}".format(overview.total_farmasi)
        total_emergency = "{:,}".format(overview.total_emergency)
        dashboard = template.dashboard
        script = """
        document.querySelector('h3[data-bind=text]').innerHTML = '{}'
        $('.payer-private').val('{}').trigger('change')
        $('.total-payer').val('{}').trigger('change')
        $('.total-private').val('{}').trigger('change')
        document.querySelector('h2.value').innerHTML = 'Rp {}'
        document.querySelector('span[data-bind=difference]').innerHTML = '{}&#37;'
        """.format('Berhasil' if status_generate == 'Berhasil' else 'Gagal', payer, total_payer, total_patient, revenue_today, revenue_percent)
        #open('/opt/odoo16/logs/dashboard.log', 'a+').write(str({'dor': status_generate}))
        dashboard_object = loads(template.object)
        body = loads(dashboard_object['datasources'][0]['settings']['body'])
        #del body['login']
        #del body['password']
        body['database'] = request.env.cr.dbname
        dashboard_object['datasources'][0]['settings']['body'] = dumps(body)
        return dashboard.replace('var mydashboard = {}', 'var mydashboard = %s' % (dumps(dashboard_object)))  #.replace('//script', script)


    @http.route('/report/sales_report', type='http', auth="user")
    @route()
    def SalesReport(self, id, **kw):
        url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        uname = request.env.company.uname_jasper.encode('utf-8')
        password = request.env.company.pass_jasper.encode('utf-8')
        jasper = JasperClient()
        jasper.login(url, uname, password)

        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['revenue.compiled.report.wizard'].browse(id)
        data = record.read()[0]
        ext = record.format_print
        date_start = record.date_start
        date_end = record.date_end

        if record.date_type == '2' and record.year and record.month:
            date_start = '{}-{}-01'.format(record.year, record.month)
            date_end = '{}-{}-{}'.format(record.year, record.month, str(calendar.monthrange(int(record.year), int(record.month))[1]))
            yyyy = record.year
        else:
            yyyy = date_start[:4]
        data['start_date'] = date_start
        data['end_date'] = date_end

        # get patient type name
        patient_types = dict(sudo.env['sale.order']._fields['patient_type'].selection)
        data['patient_type_name'] = patient_types[record.patient_type] if record.patient_type != '10' else 'ALL'
        data['hospital_name'] = record.company_id.name
        data['specialist'] = (record.specialization_id.name if record.specialization_id else "All")
        data['contributor'] = record.analytic_id.name or ""
        data['payer_name'] = record.payer_id.name or ""
        data['patient_type'] = record.patient_type
        data['data_ids'] = []
        #MTD
        data['total_actual'] = 0.00
        data['total_budget'] = 0.00
        data['total_last_year'] = 0.00
        data['total_var_A_B'] = 0.00
        data['total_persen_A_B'] = 0.00
        data['total_var_A_LY'] = 0.00
        data['total_persen_A_LY'] = 0.00
        #YTD
        data['total_actual_ytd'] = 0.00
        data['total_budget_ytd'] = 0.00
        data['total_last_year_ytd'] = 0.00
        data['total_var_A_B_ytd'] = 0.00
        data['total_persen_A_B_ytd'] = 0.00
        data['total_var_A_LY_ytd'] = 0.00
        data['total_persen_A_LY_ytd'] = 0.00

