    @http.route('/inventory/stock_status_report', type='http', auth="user")
    @route()
    def StockStatusReport(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()

        record = sudo.env['stock.status.report.wizard'].browse(id)
        data = record.read()[0]

        data['company_id'] = record.company_id.name
        data['location_id'] = record.location_id.name
        data['category_id'] = record.category_id.name
        data['product_id'] = record.product_id.name
        data['status_id'] = record.status_id
        data['start_date'] = record.start_date
        data['end_date'] = record.end_date
        data['line_ids'] = []

        stock_move = sudo.env['stock.move'].search([
            ('company_id', '=', record.company_id.id),
            ('location_id', '=', record.location_id.id),
            ('create_date', '>=', record.start_date),
            ('create_date', '<=', record.end_date),
            ('product_id.categ_id.name', '=', record.category_id.name),
            ('product_id.name', '=', record.product_id.name)
        ])
        for s in stock_move:
            obj = {}
            obj['sub_store'] = s.location_id.display_name
            obj['item_id'] = s.product_id.default_code
            obj['item_name'] = s.product_id.name
            obj['category'] = s.product_id.categ_id.name
            obj['rak'] = 0
            obj['shelf'] = s.product_id.shelf
            obj['beg'] = 0
            obj['in'] = 0
            obj['out'] = 0
            obj['end'] = obj['beg'] + s.product_uom_qty
            obj['uom_lowest'] = s.product_id.uom_id.name
            obj['avr_rate'] = s.product_id.standard_price
            obj['value'] = s.product_uom_qty
            obj['closing_value'] = obj['avr_rate'] * obj['value']
            if obj['value'] >= 0:
                obj['in'] = obj['value']
            elif obj['value'] < 0:
                obj['out'] = -obj['value']
            data['line_ids'] += [obj]

        # data = datas.convert(data)
        data = datas.json(data)
        url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        uname = request.env.company.uname_jasper.encode('utf-8')
        password = request.env.company.pass_jasper.encode('utf-8')
        jasper = JasperClient()
        jasper.login(url, uname, password)
        report = jasper.run('/Mayapada/Inventory/report_inventory_wise_stock_status', 'XLS', {'data': data})
        filename = "Stock Status Report.xls"
        return request.make_response(report[1]["data"], [('Content-Type', report[1]["content-type"]), ('Content-Disposition', content_disposition(filename))])


    # Stock Movement Summary
    @http.route('/inventory/stock_movement_summary_report', type='http', auth="user")
    @route()
    def StockMovementSummary(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        # get data filter wizard
        record = sudo.env['stock.movement.compiled.wizard'].browse(id)
        data = record.read()[0]
        ext = record.format_print_id
        location_id = record.location_id.id
        categ_id = record.category_id.id

        data['location_name'] = (str(record.location_id.name) if record.location_id.name else "ALL")
        data['categ_name'] = (str(record.category_id.name) if record.category_id.name else "ALL")
        data['company_name'] = record.company_id.name
        data['start_date'] = (record.date_start).strftime('%Y-%m-%d')
        data['end_date'] = (record.date_end).strftime('%Y-%m-%d')
        data['total_begin'] = 0
        data['total_in'] = 0
        data['total_out'] = 0
        data['total_ending'] = 0
        data['data_ids'] = []

        query = """SELECT 
                a.location_id,
                CONCAT((CASE WHEN cp.company_code IS NULL THEN '' ELSE concat(cp.company_code,'/') END), sl."name") location_name,
                CONCAT((CASE WHEN ppc."name" IS NULL THEN '' ELSE concat(ppc."name",'/') END), pc."name") category_name, 
                coalesce(pt.default_code,'[NONE]') item_code,
                pt."name" item_name,
                pu."name" small_uom,
                SUM((CASE WHEN date(a."date") < '{start_date}' THEN (a.qty_in+a.qty_out) ELSE 0 END)) qty_begin, --dr wizard date_start
                SUM((CASE WHEN date(a."date") >= '{start_date}' THEN (a.qty_in) ELSE 0 END)) qty_in, --dr wizard date_start,
                SUM((CASE WHEN date(a."date") >= '{start_date}' THEN (a.qty_out) ELSE 0 END)) qty_out, --dr wizard date_start
                SUM(a.qty_in+a.qty_out) qty_ending 
            FROM (
                SELECT MIN(id) as id,
                    move_id,
                    location_id,
                    company_id,
                    product_id,
                    product_categ_id,
                    product_template_id,
                    SUM(qty_in) as qty_in,
                    SUM(qty_out) as qty_out,
                    date,
                    source,
                    string_agg(DISTINCT serial_number, ', ' ORDER BY serial_number) AS serial_number
                FROM (
                    (SELECT
                        stock_move.id AS id,
                        stock_move.id AS move_id,
                        dest_location.id AS location_id,
                        dest_location.company_id AS company_id,
                        stock_move.product_id AS product_id,
                        product_template.id AS product_template_id,
                        product_template.categ_id AS product_categ_id,
                        quant.qty AS qty_in,
                        0 qty_out,
                        stock_move.date AS date,
                        quant.cost as price_unit_on_quant,
                        stock_move.origin AS source,
                        stock_production_lot.name AS serial_number
                    FROM stock_quant as quant
                    JOIN stock_quant_move_rel ON stock_quant_move_rel.quant_id = quant.id
                    JOIN stock_move ON stock_move.id = stock_quant_move_rel.move_id
                    LEFT JOIN stock_production_lot ON stock_production_lot.id = quant.lot_id
                    JOIN stock_location dest_location ON stock_move.location_dest_id = dest_location.id
                    JOIN stock_location source_location ON stock_move.location_id = source_location.id
                    JOIN product_product ON product_product.id = stock_move.product_id
                    JOIN product_template ON product_template.id = product_product.product_tmpl_id
                    WHERE quant.qty>0 
                        AND stock_move.state = 'done' 
                        AND dest_location.usage in ('internal', 'transit')
                        AND (
                            not (source_location.company_id is null and dest_location.company_id is null) or
                            source_location.company_id != dest_location.company_id or
                            source_location.usage not in ('internal', 'transit'))
                    ) 
                    
                    --select usage from stock_location where name ilike '%Scrap%'
                    UNION ALL
                                                
                    (SELECT
                        (-1) * stock_move.id AS id,
                        stock_move.id AS move_id,
                        source_location.id AS location_id,
                        source_location.company_id AS company_id,
                        stock_move.product_id AS product_id,
                        product_template.id AS product_template_id,
                        product_template.categ_id AS product_categ_id,
                        0 qty_in,
                        - quant.qty AS qty_out,
                        stock_move.date AS date,
                        quant.cost as price_unit_on_quant,
                        stock_move.origin AS source,
                        stock_production_lot.name AS serial_number
                    FROM stock_quant as quant
                    JOIN stock_quant_move_rel ON stock_quant_move_rel.quant_id = quant.id
                    JOIN stock_move ON stock_move.id = stock_quant_move_rel.move_id
                    LEFT JOIN stock_production_lot ON stock_production_lot.id = quant.lot_id
                    JOIN stock_location source_location ON stock_move.location_id = source_location.id
                    JOIN stock_location dest_location ON stock_move.location_dest_id = dest_location.id
                    JOIN product_product ON product_product.id = stock_move.product_id
                    JOIN product_template ON product_template.id = product_product.product_tmpl_id
                    WHERE quant.qty>0 
                        AND stock_move.state = 'done' 
                        AND source_location.usage in ('internal', 'transit')
                        AND (
                            not (dest_location.company_id is null and source_location.company_id is null) or
                            dest_location.company_id != source_location.company_id or
                            dest_location.usage not in ('internal', 'transit'))
                    )
                ) AS foo
                GROUP BY move_id, location_id, company_id, 
                    product_id, product_categ_id, date, source, 
                    product_template_id
            ) AS a 
            LEFT JOIN product_category pc ON pc.id = a.product_categ_id
            LEFT JOIN product_category ppc ON ppc.id = pc.parent_id
            LEFT JOIN stock_location sl ON sl.id = a.location_id 
            LEFT JOIN res_company cp ON cp.id = sl.company_id 
            LEFT JOIN product_template pt ON pt.id = a.product_template_id
            LEFT JOIN product_uom pu ON pu.id = pt.uom_id 
            WHERE a.company_id = {company_id} --dr wizard company_id 
                AND date(a."date") <= '{end_date}' --dr wizard date_end  
                AND a.location_id = COALESCE({location_id}, a.location_id) --wizard location_id  
                AND a.product_categ_id = COALESCE({categ_id}, a.product_categ_id) --wizard product_categ_id  
            GROUP BY pc."name", ppc."name", cp.company_code, sl."name", 
                a.location_id, pu."name", coalesce(pt.default_code,'[NONE]'), pt."name"
            ORDER BY location_name, category_name, item_code, item_name
            """.format(location_id=(str(location_id) if location_id else "null"),
                    categ_id=(str(categ_id) if categ_id else "null"),
                    company_id=record.company_id.id,
                    start_date=record.date_start,
                    end_date=record.date_end)

        query = sudo.env.cr.execute(query)
        stock_valuation = sudo.env.cr.dictfetchall()
        
        for s in stock_valuation:
            obj = {}
            obj['location_id'] = s['location_id']
            obj['location_name'] = s['location_name']
            obj['category_name'] = s['category_name']
            obj['item_code'] = s['item_code']
            obj['item_name'] = s['item_name']
            obj['small_uom'] = s['small_uom']
            obj['qty_begin'] = s['qty_begin']
            obj['qty_in'] = s['qty_in']
            obj['qty_out'] = s['qty_out']
            obj['qty_ending'] = s['qty_ending']
            data['total_begin'] += obj['qty_begin']
            data['total_in'] += obj['qty_in']
            data['total_out'] += obj['qty_out']
            data['total_ending'] += obj['qty_ending']
            data['data_ids'] += [obj]

        data = datas.convert(data)
        data = datas.json(data, cdata=False)

        import requests
        url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        
        execution = requests.post('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions',
            auth=(uname, password),
            json={
                'reportUnitUri':
                '/Mayapada16/Inventory/report_inventory_movement_summary',
                'outputFormat': str(ext),
                'parameters': {
                    'reportParameter': [{
                        'name': 'data',
                        'value': [data]
                    }]
                }
            })

        from lxml import etree
        xml = etree.XML(execution.content)
        request_id = xml.find('.//requestId').text
        export_id = xml.find('.//export//id').text
        result = requests.get('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions/' +request_id + '/exports/' + export_id + '/outputResource',cookies=execution.cookies)
        #url = "http://10.2.1.120:8080/jasperserver/services/repository?wsdl"

        if str(ext) == 'xls':
            filename = "Report Inventory Movement Summary.xls"
            return request.make_response(result.content,[('Content-Type', result.headers['content-type']),('Content-Disposition', content_disposition(filename))])
        elif str(ext) == 'pdf':
            filename = "Report Inventory Movement Summary.pdf"
            return request.make_response(result.content,[('Content-Type', result.headers['content-type']),('Content-Disposition', content_disposition(filename))])

        # data = datas.convert(data)
