    # 2021.08.26 - Purchase Receipt Report  (Stock)
    @http.route('/purchase/purchase_receipt_report', type='http', auth="user")
    @route()
    def PurchaseReceiptReport(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['purchase.receipt.report.wizard'].browse(id)
        ext = record.format_print_id
        data = {}
        partner_id = record.partner_id.id
        start_date = (record.start_date).strftime('%Y-%m-%d')
        end_date = (record.end_date).strftime('%Y-%m-%d')

        data['company_name'] = record.company_id.name
        data['start_date'] = start_date
        data['end_date'] = end_date
        data['item_type_id'] = ""
        data['total_qty'] = 0
        data['total_unit'] = 0
        data['total_ded'] = 0
        data['total_tax'] = 0
        data['total_nett'] = 0
        data['total_price'] = 0
        data['data_ids'] = []

        query = """SELECT 
                (case when po."name" like '%PRT%' or po.is_return is True then 'PURCHASE RETURN' else 'PURCHASE RECEIPT' end) receipt_type,
                (case when po.is_consignment is True or pol.is_consignment is True then 'CONSIGNMENT' else 'NON CONSIGNMENT' end) consignment_type,
                sp.vendor_code supplier_code, 
                sp."name" supplier_name, 
                upper(concat(sp.street, ' ', sp.city)) supplier_address,
                date(coalesce(po.wipro_date, po.date_order)) grn_date,
                po."name" grn_no,
                pt.manufacturer manufacture,
                pt.brand brand_name,
                pt.default_code product_code,
                pt."name" product_name,
                concat(coalesce(concat(ppc."name",'/'),''), pc."name") product_category,
                    ((case when po."name" like '%PRT%' or po.is_return is True then -1 else 1 end)* pol.product_qty) product_qty,
                pu."name" product_uom,
                pol.price_unit unit_price,
                pol.discount_value unit_ded_amount,
                round(pol.discount_persen::numeric, 2) unit_ded_percent,
                pol.has_tax/pol.product_qty unit_tax_amount,
                round((case when (pol.price_unit-pol.discount_value) > 0 
                    then ((pol.has_tax/pol.product_qty/(pol.price_unit-pol.discount_value)) * 100) 
                    else 0 end)::numeric,2) unit_tax_percent,
                (pol.price_unit-pol.discount_value+(pol.has_tax/pol.product_qty)) unit_nett,
                ((pol.price_unit-pol.discount_value+(pol.has_tax/pol.product_qty))*
                ((case when po."name" like '%PRT%' or po.is_return is True then -1 else 1 end)* pol.product_qty)) price_total,
                pol.batch_no,
                pol.expiry_date,
                '-' po_number,
                '-' pr_number
                    from purchase_order po
                    inner join purchase_order_line pol on pol.order_id = po.id 
                    inner join product_product pp on pp.id = pol.product_id 
                    inner join product_template pt on pt.id = pp.product_tmpl_id
                    inner join res_partner sp on sp.id = po.partner_id
                    left join product_category pc on pc.id = pol.product_categ_id
                    left join product_category ppc on ppc.id = pc.parent_id
                    left join uom_uom pu on pu.id = pol.product_uom
                    where (coalesce(po.sync_id,0) > 0 or po.sync_id_api is not null) --dari HIS  
                    and po.company_id = {company_id} --ambil dari wizard 
                    and date(po.date_order) >= '{start_date}' --ambil dari wizard
                    and date(po.date_order) <= '{end_date}' --ambil dari wizard
                    and po.partner_id = coalesce({partner_id}, po.partner_id) --ambil dari wizard
                    and pol.price_unit <> 1
                    and pol.price_unit <> 0 
            """.format(partner_id=(str(partner_id) if partner_id else "null"),
                company_id=record.company_id.id,
                start_date=record.start_date,
                end_date=record.end_date)

        stock_query = sudo.env.cr.execute(query)
        stock_result = sudo.env.cr.dictfetchall()
        
        for s in stock_result:
            obj = {}
            obj['receipt_type'] = s['receipt_type']
            obj['consignment_type'] = s['consignment_type']
            obj['supplier_code'] = s['supplier_code']
            obj['supplier_name'] = s['supplier_name']
            obj['supplier_address'] = s['supplier_address']
            obj['grn_date'] = (s['grn_date']).strftime('%Y-%m-%d') or "-"
            obj['grn_no'] = s['grn_no']
            obj['manufacture'] = s['manufacture'] or '-'
            obj['brand_name'] = s['brand_name'] or '-'
            obj['product_code'] = s['product_code']
            obj['product_name'] = s['product_name']
            obj['product_category'] = s['product_category']
            obj['product_qty'] = s['product_qty'] or 0
            obj['product_uom'] = s['product_uom'] or 0
            obj['unit_price'] = s['unit_price'] or 0
            obj['unit_ded_amount'] = s['unit_ded_amount'] or 0
            obj['unit_ded_percent'] = s['unit_ded_percent'] or 0
            obj['unit_tax_amount'] = s['unit_tax_amount'] or 0
            obj['unit_tax_percent'] = s['unit_tax_percent'] or 0
            obj['unit_nett'] = s['unit_nett'] or 0
            obj['price_total'] = s['price_total'] or 0
            obj['batch_no'] = s['batch_no'] or '-'
            if s['expiry_date']:
            
                obj['expiry_date'] = (s['expiry_date']).strftime('%Y-%m-%d') or "-"

            obj['po_number'] = s['po_number'] or '-'
            obj['pr_number'] = s['pr_number'] or '-'
            data['total_qty'] += obj['product_qty']
            data['total_unit'] += obj['unit_price']
            data['total_ded'] += obj['unit_ded_amount']
            data['total_tax'] += obj['unit_tax_amount']
            data['total_nett'] += obj['unit_nett']
            data['total_price'] +=  obj['price_total']
            # import datetime
            
            # obj = {key: str(datetime.datetime.strftime(value, "%Y-%m-%d")) if type(value) == datetime.date  else value for key, value in obj.items()}
            data['data_ids'] += [obj]
        
        # data = datas.convert(data)
        data = datas.json(data, cdata=False)
        

        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
