    @http.route('/inventory/stock_scrap_report', type='http', auth="user")
    @route()
    def StoreConsumptionReport(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        # get data filter wizard
        record = sudo.env['stock.scrap.compiled.wizard'].browse(id)
        data = {}
        ext = record.format_print_id
        
        # Get Title 
        if record.report_type == 'SC':
            report_type = "Store Consumption Report"
        elif record.report_type == 'AI':
            report_type = "Adjustment Issue Report"
        elif record.report_type == 'PI':
            report_type = "Prepared Item Report"
        elif record.report_type == 'AR':
            report_type = "Adjustment Receipt Report"
        elif record.report_type == 'BR':
            report_type = "Breakage Report"
        elif record.report_type == 'SE':
            report_type = "Prepared Receipt Report"
        elif record.report_type == 'LB':
            report_type = "Loss Breakage Report"

        location_id = record.location_id.id
        category_id = record.category_id.id

        data['title'] = report_type
        data['company_name'] = record.company_id.name
        data['start_date'] = (record.date_start).strftime('%Y-%m-%d')
        data['end_date'] = (record.date_end).strftime('%Y-%m-%d')
        data['total_cost_unit'] = 0
        data['total_cost'] = 0
        data['data_ids'] = []

        query = """select 
                date(a.transaction_date) trans_date,
                a.origin trans_no,
                sc."name" service_name,
                concat(coalesce(concat(pcp."name",'/'),''), pc."name") category_name,
                pt.default_code item_code,
                pt."name" item_name,
                pu."name" item_uom,
                coalesce(a.batch_no,'[NONE]') batch_no,
                a.expiry_date batch_expired,
                a.scrap_qty item_qty,
                a."cost" cost_unit,
                a.cost_total cost_total, 
                coalesce(so."name",'[NONE]') admission_no,
                coalesce(sls."name",'[NONE]') location_source,
                coalesce(sld."name",'[NONE]') location_destionation
            from stock_scrap a 
            inner join product_product pp on pp.id = a.product_id 
            inner join product_template pt on pt.id = pp.product_tmpl_id 
            inner join product_category pc on pc.id = a.categ_id
            inner join product_category sc on sc.id = a.service_categ_id
            inner join uom_uom pu on pu.id = a.product_uom_id
            left join product_category pcp on pcp.id = pc.parent_id
            left join sale_order so on so.id = a.admission_id
            left join stock_location sls on sls.id = a.location_id
            left join stock_location sld on sld.id = a.scrap_location_id
            where a.company_id = {company_id} --ambil dr wizard 
                and date(a.transaction_date) >= '{start_date}' --ambil dr wizard 
                and date(a.transaction_date) <= '{end_date}' --ambil dr wizard 
                and a.trans_type = '{report_type}' --ambil dr wizard 
                and a.categ_id = coalesce({category_id}, a.categ_id) --ambil dr wizard 
                and (case when a.trans_type='AR' then a.scrap_location_id else a.location_id end) = coalesce({location_id}, (case when a.trans_type='AR' then a.scrap_location_id else a.location_id end)) --ambil dr wizard 
            order by a.transaction_date asc""".format(location_id=(str(location_id) if location_id else "null"),
                category_id=(str(category_id) if category_id else "null"),
                report_type=record.report_type,
                company_id=record.company_id.id, 
                start_date=record.date_start, 
                end_date=record.date_end)

        query = sudo.env.cr.execute(query)
        stock_scrap = sudo.env.cr.dictfetchall()

        for ss in stock_scrap:
            obj = {}
            obj['trans_date'] = (ss['trans_date']).strftime('%Y-%m-%d') or "-"
            obj['trans_no'] = ss['trans_no'] or "-"
            obj['service_name'] = ss['service_name'] or "-"
            obj['category_name'] = ss['category_name'] or "-"
            obj['item_code'] = ss['item_code'] or "-"
            obj['item_name'] = ss['item_name'] or "-"
            obj['item_uom'] = ss['item_uom'] or "-"
            obj['batch_no'] = ss['batch_no'] or "-"
            obj['batch_expired'] = ss['batch_expired'] or "-"
            obj['item_qty'] = ss['item_qty'] or 0
            obj['cost_unit'] = ss['cost_unit'] or 0
            obj['cost_total'] = ss['cost_total'] or 0
            obj['admission_no'] = ss['admission_no'] or "-"
            obj['location_source'] = ss['location_source'] or "-"
            obj['location_destionation'] = ss['location_destionation'] or "-"
            data['total_cost_unit'] += obj['cost_unit']
            data['total_cost'] += obj['cost_total']
            data['data_ids'] += [obj]

        data = datas.convert(data)
        data = datas.json(data, cdata=False)

        url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper

        import requests
        uname = request.env.company.uname_jasper
