    @http.route('/inventory/expired_report', type='http', auth="user")
    @route()
    def ExpiredReport(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        # get data filter wizard
        record = sudo.env['expired.report.wizard'].browse(id)
        data = record.read()[0]

        data['company_id'] = record.company_id.name
        data['location_id'] = record.location_id.name
        data['product_id'] = record.product_id.name
        data['status_id'] = record.status_id
        data['start_date'] = record.start_date
        data['end_date'] = record.end_date
        data['line_ids'] = []
        data['total'] = 0
        stock_production = sudo.env['stock.production.lot'].search([
            ('life_date', '>=', record.start_date),
            ('life_date', '<=', record.end_date),
            ('quant_ids.history_ids.company_id', '=', record.company_id.id),
            ('quant_ids.location_id', '=', record.location_id.id)
        ])  #('product_id.name', '=', record.product_id.id)])
        for s in stock_production:
            obj = {}
            obj['item_id'] = s.product_id.default_code
            obj['item_name'] = s.product_id.name
            obj['category'] = s.product_id.categ_id.name
            obj['batch_no'] = s.name
            obj['expired_date'] = s.life_date
            obj['rak'] = 0
            obj['shelf'] = s.product_id.shelf
            obj['qty'] = s.product_qty
            obj['uepr'] = s.product_id.standard_price
            obj['total_uepr'] = 0
            data['total'] += obj['total_uepr']
            for q in s.quant_ids:
                obj['location'] = q.location_id.display_name
                obj['received_date'] = q.in_date
                obj['uom_lowest'] = q.product_uom_id.name
                for h in q.history_ids:
                    obj['grn_no'] = h.picking_id.name
                    obj['supplier'] = h.picking_partner_id.name
            data['line_ids'] += [obj]

        # data = datas.convert(data)
        data = datas.json(data)
        url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        
        jasper = JasperClient()
        jasper.login(url, uname, password)
        report = jasper.run('/Mayapada/Inventory/Expired_Report_Main', 'XLS', {'data': data})
        filename = "Expired Report.xls"

        return request.make_response(report[1]["data"],[('Content-Type', report[1]["content-type"]), ('Content-Disposition', content_disposition(filename))])
        # return json.dumps(data)


