        data['no'] = record.name
        data['po'] = record.purchase_id.title
        data['vr'] = record.purchase_id.partner_ref
        data['receipt_no'] = record.receiving_id.name
        data['receipt_date'] = (record.receiving_id.date).strftime('%Y-%m-%d')
        data['receipt_by'] = record.receiving_id.user_id.name
        data['internal_no'] = record.origin
        data['company'] = record.company_id.name
        data['street'] = record.company_id.street
        data['street2'] = record.company_id.street2
        data['city'] = record.company_id.city
        data['zip'] = record.company_id.zip
        data['country'] = record.company_id.country_id.name
        data['phone'] = record.company_id.phone or "-"
        # data['fax'] = record.company_id.fax  or "-"
        data['print_date'] = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        data['printed_by'] = request.env.user.name
        data['total'] = 0
        data['total_amount'] = 0
        data['total_ded'] = 0
        data['total_add'] = 0
        data['total_net'] = 0
        data['line_ids'] = []

        for m in record.move_lines:
            obj = {}
            obj['item_number'] = m.product_id.default_code
            obj['product'] = m.product_id.name
            obj['desc'] = m.name
            obj['unit'] = m.product_uom.name
            if m.purchase_line_id:
                obj['ordered'] = m.purchase_line_id.product_qty
            else:
                obj['ordered'] = 0
            obj['received'] = m.product_uom_qty
            obj['remaining_order'] = obj['ordered'] - obj['received']
            obj['qty'] = m.ordered_qty or m.product_uom_qty
            obj['add'] = m.price_tax #/ m.product_uom_qty
            obj['disc_rate'] = m.discount_persen
            obj['ded'] = m.discount_value * m.product_uom_qty
            obj['price'] = m.price_unit
            obj['amount'] = m.price_total
            # obj['total_price'] = m.price_unit * m.ordered_qty
            obj['total_price'] = m.price_unit * (m.ordered_qty or m.product_uom_qty)
            data['total_amount'] += obj['total_price']
            data['total_ded'] += obj['ded']
            data['total_add']  += obj['add']
            data['total'] += obj['total_price'] - obj['ded']
            data['total_net'] += ((obj['total_price'] - obj['ded']) + obj['add'])
            data['line_ids'] += [obj]

        data = datas.convert(data)
        data = datas.json(data, cdata=False)
        # open('/opt/odoo16/logs/dump.log', 'w+').write(data)
        
        # url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        # uname = request.env.company.uname_jasper
        # password = request.env.company.pass_jasper

        # jasper = JasperClient()
        # jasper.login(url, uname, password)
        # report = jasper.run('/Mayapada/Inventory/Print_Out_Receiving_Notes','PDF', {'data': data})
        # filename = "Delivery Order.pdf"
        # return request.make_response(report[1]["data"], [('Content-Type', report[1]["content-type"]), ('Content-Disposition', content_disposition(filename))])
        
        import requests
        url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        
        execution = requests.post('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions',
            auth=(uname, password),
            json={
                'reportUnitUri':
                '/Mayapada16/Inventory/Print_Out_Receiving_Notes',
                'outputFormat': 'pdf',
                'parameters': {
                    'reportParameter': [{
                        'name': 'data',
                        'value': [data]
                    }]
                }
            })

        from lxml import etree
        xml = etree.XML(execution.content)
        request_id = xml.find('.//requestId').text
        export_id = xml.find('.//export//id').text
        result = requests.get('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions/' +request_id + '/exports/' + export_id + '/outputResource',cookies=execution.cookies)
        
        filename = "Delivery Order.pdf"
        return request.make_response(result.content,[('Content-Type', result.headers['content-type']),('Content-Disposition', content_disposition(filename))])


