    # Module: Purchase/Report/Purchase Requisition
    @http.route('/purchase/report_purchase_requisition', type='http', auth="user")
    @route()
    def PrintOutReportPR(self, id, **kw):
        
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['report.purchase.requisition.wizard'].browse(id)
        data = {}
        ext = record.format_print_id
        partner_id = record.vendor_id.id
        if not record.state:
            ex_param = "and pr.state = coalesce(null, pr.state)"
        else:
            ex_param = """and pr.state = coalesce('{state}', po.state)""".format(state=record.state)
        
        data['data_ids'] = []
        data['start_date'] = (record.start_date).strftime('%Y-%m-%d')
        data['end_date'] = (record.end_date).strftime('%Y-%m-%d')
        data['company_name'] = record.company_id.name
        query = """SELECT DISTINCT        
            pr.name "PR Number" ,      
            pr.ordering_date "PR Date",       
            coalesce(sp.name,'[NONE]') "PR Vendor",      
            coalesce(pt.default_code,'[NONE]') "Item Code",       
            pt.name "Item Name",       
            prl.description "Item Description",       
            prl.product_qty "PR Qty",        
            pu.name "PR UoM",        
            (case pr.state          
                when 'draft' then 'Draft'
                when 'waiting' then 'Waiting for Approval'
                when 'approved' then 'Approved'           
                when 'in_progress' then 'Confirmed'         
                when 'open' then 'RFQ Created'  
                when 'done' then 'PO Completed' 
                when 'cancel' then 'Cancel'
            end)  "PR Status",          
            po.po_number "PO Number",
            vn.vendor_code "PO Supplier Code",      
            vn."name" "PO Supplier Name",
            po.po_state "PO Status",        
            po.po_item_qty "PO Qty",     
            po.po_item_uom "PO UoM",
            TO_CHAR(pr.write_date, 'YYYY-MM-DD') "Last Update",
            sp2.name "PR User"      
        from purchase_requisition pr            
        left join purchase_requisition_line prl on prl.requisition_id=pr.id     
        left join (         
            select po.company_id,       
                po.requisition_id, pol.product_id,  
                po.partner_id vendor_id, 
                date(po.date_order) po_date,
                sum(pol.product_qty) po_item_qty,   
                string_agg(po.name, ', ') po_number,  
                pu.name po_item_uom,    
                (case po.state      
                    when 'draft' then 'RFQ'
                    when 'sent' then 'RFQ Sent'
                    when 'to approve' then 'To Approve'           
                    when 'purchase' then 'Purchase Order'         
                    when 'done' then 'Close Bill'         
                end) po_state, po."state"  
            from purchase_order po      
            left join purchase_order_line pol on pol.order_id=po.id   
            left join uom_uom pu on pu.id=pol.product_uom    
            where po.state <> 'cancel'      
                and coalesce(po.requisition_id,0) <> 0  
            group by po.company_id, pu.name,        
                po.requisition_id, pol.product_id,  
                po.partner_id, date(po.date_order), po."state",
                (case po.state  
                when 'draft' then 'RFQ'
                when 'sent' then 'RFQ Sent'
                when 'to approve' then 'To Approve'           
                when 'purchase' then 'Purchase Order'         
                when 'done' then 'Close Bill'         
                end) 
        ) po on po.requisition_id = pr.id           
            and po.product_id=prl.product_id        
            and po.company_id=pr.company_id     
        left join res_partner sp on sp.id=pr.vendor_id and sp.supplier=true 
        left join res_partner vn on vn.id=po.vendor_id and vn.supplier=true 
        left join res_users rs on rs.id=pr.user_id
        left join res_partner sp2 on sp2.id=rs.partner_id       
        left join product_product pp on pp.id=prl.product_id     
        left join product_template pt on pt.id=pp.product_tmpl_id     
        left join uom_uom pu on pu.id=prl.product_uom_id     
        where pr.company_id = {company_id} 
            and coalesce(pr.vendor_id,0) = coalesce({partner_id}, pr.vendor_id,0)   
            and coalesce(po.state, '') <> 'cancel'        
            {ex_param}
            and date(pr.ordering_date) >= '{start_date}'    
            and date(pr.ordering_date) <= '{end_date}'
            """.format(partner_id=(str(partner_id) if partner_id else "null"),
                ex_param=ex_param,
                company_id=record.company_id.id, 
                start_date=record.start_date, 
                end_date=record.end_date)
        query = sudo.env.cr.execute(query)
        pr_report = sudo.env.cr.dictfetchall()
        
        for r in pr_report:
            obj = {}
            obj['pr_number'] = r['PR Number'] or ' '
            # CHAELVIN
            #obj['pr_date'] = r['PR Date'] or ' '
            if r['PR Date']: 
                obj['pr_date'] = (r['PR Date']).strftime('%Y-%m-%d') or "-"
            obj['pr_vendor'] = r['PR Vendor'] or ' '
            obj['item_code'] = r['Item Code'] or ' '
            obj['item_name'] = r['Item Name'] or ' '
            obj['item_description'] = r['Item Description'] or ' '
            obj['pr_qty'] = r['PR Qty'] or ' '
            obj['pr_uom'] = r['PR UoM'] or ' '
            obj['pr_status'] = r['PR Status'] or ' '
            obj['po_number'] = r['PO Number'] or ' '
            obj['po_supp_code'] = r['PO Supplier Code'] or ' '
            obj['po_supp_name'] = r['PO Supplier Name'] or ' '
            obj['po_status'] = r['PO Status'] or ' '
            obj['po_qty'] = r['PO Qty'] or ' '
            obj['po_uom'] = r['PO UoM'] or ' '
            obj['last_update'] = r['Last Update'] or ' '
            obj['pr_user'] = r['PR User'] or ' '
            data['data_ids'] += [obj]

        # data = datas.convert(data)
        data = datas.json(data, cdata=False)
        
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        filepath = '/Mayapada/Purchase/Print_Out_PR_PO'

        import requests
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        execution = requests.post('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions',
            auth=(uname, password),
            json={
                'reportUnitUri': str(filepath),
                'outputFormat': str(ext),
                'parameters': {
                    'reportParameter': [{
                        'name': 'data',
                        'value': [data]
                    }]
                }
            })
        from lxml import etree
        xml = etree.XML(execution.content)
        request_id = xml.find('.//requestId').text
        export_id = xml.find('.//export//id').text
        result = requests.get('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions/' +request_id + '/exports/' + export_id + '/outputResource',cookies=execution.cookies)
        url = "http://10.2.1.120:8080/jasperserver/services/repository?wsdl"
        if str(ext) == 'xls':
            filename = "Report Purchase Requisition.xls"
            return request.make_response(result.content,[('Content-Type', result.headers['content-type']),('Content-Disposition', content_disposition(filename))])
        elif str(ext) == 'pdf':
            filename = "Report Purchase Requisition.pdf"
            return request.make_response(result.content,[('Content-Type', result.headers['content-type']),('Content-Disposition', content_disposition(filename))])



    # Print Troughput IP Visit
    @http.route('/account/troughput_ip_visit', type='http', auth="user")
    @route()
    def PrintTroughputIpVisit(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        # get data filter wizard
        record = sudo.env['wizard.troughput.ip.visit'].browse(id)
        data = record.read()[0]
        ext = record.format_print_id

        data['line_ids'] = []
        data['company_name'] = record.company_id.name
        data['start_date'] = record.start_date
        data['end_date'] = record.end_date

        query = sudo.env.cr.execute("""
            SELECT  
                a.tglproses,
                sum(case when a.type='PASIEN DATANG' then 1 else 0 end) AS pasien_datang_total,
                sum(case when a.type='PASIEN DATANG' and a.patient_status='BARU' then 1 else 0 end) AS pasien_datang_baru,
                sum(case when a.type='PASIEN DATANG' and a.patient_status='LAMA' then 1 else 0 end) AS pasien_datang_lama,
                sum(case when a.type='PINDAH MASUK' then 1 else 0 end) AS pasien_pindah_masuk,
                sum(case when a.type='PINDAH KELUAR' then 1 else 0 end) AS pasien_pindah_keluar,
                sum(case when a.type='PASIEN PULANG' then 1 else 0 end) AS pasien_pulang_total,
                sum(case when a.type='PASIEN PULANG' and (a.discharge_status like '%MENINGGAL%' or a.discharge_status like '%DIED%') then 1 else 0 end) AS pasien_pulang_meninggal,
                sum(case when a.type='PASIEN PULANG' and (a.discharge_status not like '%MENINGGAL%' or a.discharge_status not like '%DIED%') then 1 else 0 end) AS pasien_pulang_normal
            FROM troughput_patient_visit_ip a   
            WHERE a.tglproses >= '{start_date}'   
                AND a.tglproses <= '{end_date}'
                AND a.company_id='{company_id}'
            GROUP BY a.tglproses    
            ORDER BY a.tglproses    
                """.format(company_id=record.company_id.id,
                           start_date=record.start_date,
                           end_date=record.end_date))
        troughput_ip_visit_report = sudo.env.cr.dictfetchall()

        for r in troughput_ip_visit_report:
            obj = {}
            obj['tglproses'] = r['tglproses'] or ' '
            obj['pasien_datang_total'] = r['pasien_datang_total'] or ' '
            obj['pasien_datang_baru'] = r['pasien_datang_baru'] or ' '
            obj['pasien_datang_lama'] = r['pasien_datang_lama'] or ' '
            obj['pasien_pindah_masuk'] = r['pasien_pindah_masuk'] or ' '
            obj['pasien_pindah_keluar'] = r['pasien_pindah_keluar'] or ' '
            obj['pasien_pulang_total'] = r['pasien_pulang_total'] or ' '
            obj['pasien_pulang_meninggal'] = r['pasien_pulang_meninggal'] or ' '
            obj['pasien_pulang_normal'] = r['pasien_pulang_normal'] or ' '
            data['line_ids'] += [obj]

        #data = datas.convert(data)
        data = datas.json(data)
        
        url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        
        jasper = JasperClient()
        jasper.login(url, uname, password)

        if str(ext) == 'xls':
            report = jasper.run('/Mayapada/Throughput/troughput_ip_visit','XLS', {'data': data})
            filename = "Report Troughput IP Visit.xls"
            return request.make_response(report[1]["data"],[('Content-Type', report[1]["content-type"]), ('Content-Disposition', content_disposition(filename))])
        elif str(ext) == 'pdf':
            report = jasper.run('/Mayapada/Throughput/troughput_ip_visit','PDF', {'data': data})
            filename = "Report Troughput IP Visit.pdf"
            return request.make_response(report[1]["data"], [('Content-Type', report[1]["content-type"]), ('Content-Disposition', content_disposition(filename))])
        # return json.dumps(data)


