    # Print Troughput Bor Daily
    @http.route('/account/troughput_bor_daily', type='http', auth="user")
    @route()
    def PrintTroughputBorDaily(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        # get data filter wizard
        record = sudo.env['wizard.troughput.bor.daily'].browse(id)
        data = record.read()[0]

        bulan = dict(sudo.env['wizard.troughput.bor.daily']._fields['bulan'].selection)
        ext = record.format_print_id

        data['line_ids'] = []
        data['company_name'] = record.company_id.name
        data['tahun'] = record.tahun
        data['bulan'] = bulan[record.bulan]

        query = sudo.env.cr.execute("""
           SELECT a.*           
                FROM (          
                    SELECT      
                        (case a.bor_type    
                            when 'BY TOTAL' then 10
                            when 'BY BEDTYPE' then 21
                            when 'BY TOWER' then 31
                            when 'BY PAYER' then 41
                            when 'BY CRITICAL' then 51
                            when 'BY WARD' then 61
                        end) sno,   
                        (case a.bor_type    
                            when 'BY TOTAL' then 'TOTAL BOR'
                            when 'BY BEDTYPE' then  COALESCE( NULLIF(a.bed_type,'') , '' )
                            when 'BY TOWER' then  COALESCE( NULLIF(a.tower,'') , '' )
                            when 'BY PAYER' then  COALESCE( NULLIF(a.payer_type,'') , '' )
                            when 'BY CRITICAL' then  COALESCE( NULLIF(a.is_critial,'') , '' )
                            when 'BY WARD' then  COALESCE( NULLIF(a.ward_name,'') , '' )
                        end) bor_name,  
                        max(case when EXTRACT(DAY FROM a.tglproses)=1 then a.bor_value else null end) day1, 
                        max(case when EXTRACT(DAY FROM a.tglproses)=2 then a.bor_value else null end) day2, 
                        max(case when EXTRACT(DAY FROM a.tglproses)=3 then a.bor_value else null end) day3, 
                        max(case when EXTRACT(DAY FROM a.tglproses)=4 then a.bor_value else null end) day4, 
                        max(case when EXTRACT(DAY FROM a.tglproses)=5 then a.bor_value else null end) day5, 
                        max(case when EXTRACT(DAY FROM a.tglproses)=6 then a.bor_value else null end) day6, 
                        max(case when EXTRACT(DAY FROM a.tglproses)=7 then a.bor_value else null end) day7, 
                        max(case when EXTRACT(DAY FROM a.tglproses)=8 then a.bor_value else null end) day8, 
                        max(case when EXTRACT(DAY FROM a.tglproses)=9 then a.bor_value else null end) day9, 
                        max(case when EXTRACT(DAY FROM a.tglproses)=10 then a.bor_value else null end) day10,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=11 then a.bor_value else null end) day11,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=12 then a.bor_value else null end) day12,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=13 then a.bor_value else null end) day13,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=14 then a.bor_value else null end) day14,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=15 then a.bor_value else null end) day15,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=16 then a.bor_value else null end) day16,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=17 then a.bor_value else null end) day17,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=18 then a.bor_value else null end) day18,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=19 then a.bor_value else null end) day19,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=20 then a.bor_value else null end) day20,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=21 then a.bor_value else null end) day21,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=22 then a.bor_value else null end) day22,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=23 then a.bor_value else null end) day23,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=24 then a.bor_value else null end) day24,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=25 then a.bor_value else null end) day25,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=26 then a.bor_value else null end) day26,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=27 then a.bor_value else null end) day27,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=28 then a.bor_value else null end) day28,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=29 then a.bor_value else null end) day29,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=30 then a.bor_value else null end) day30,   
                        max(case when EXTRACT(DAY FROM a.tglproses)=31 then a.bor_value else null end) day31        
                    FROM  troughput_bor_daily a         
                    WHERE a.tahun='{tahun}'        
                        AND a.bulan='{bulan}' 
                        AND a.company_id='{company_id}'    
                    GROUP BY (case a.bor_type       
                            when 'BY TOTAL' then 'TOTAL BOR'
                            when 'BY BEDTYPE' then COALESCE( NULLIF(a.bed_type,'') , '' )
                            when 'BY TOWER' then COALESCE( NULLIF(a.tower,'') , '' )
                            when 'BY PAYER' then COALESCE( NULLIF(a.payer_type,'') , '' )
                            when 'BY CRITICAL' then COALESCE( NULLIF(a.is_critial,'') , '' )
                            when 'BY WARD' then COALESCE( NULLIF(a.ward_name,'') , '' )
                        end), (case a.bor_type  
                            when 'BY TOTAL' then 10
                            when 'BY BEDTYPE' then 21
                            when 'BY TOWER' then 31
                            when 'BY PAYER' then 41
                            when 'BY CRITICAL' then 51
                            when 'BY WARD' then 61
                        end)    
                            
                    UNION ALL       
                            
                    SELECT (case a.bor_type     
                            when 'BY BEDTYPE' then 20
                            when 'BY TOWER' then 30
                            when 'BY PAYER' then 40
                            when 'BY CRITICAL' then 50
                            when 'BY WARD' then 60
                        end) sno,   
                        a.bor_type bor_name,    
                        null day1, null day2, null day3, null day4, null day5, null day6, null day7, null day8, null day9, null day10,  
                        null day11, null day12, null day13, null day14, null day15, null day16, null day17, null day18, null day19, null day20,     
                        null day21, null day22, null day23, null day24, null day25, null day26, null day27, null day28, null day29, null day30, null day31  
                    FROM troughput_bor_daily a      
                    WHERE a.bor_type <> 'BY TOTAL'      
                        AND a.tahun='{tahun}'  
                        AND a.bulan='{bulan}' 
                        AND a.company_id='{company_id}'    
                    GROUP BY a.bor_type,        
                        (case a.bor_type    
                            when 'BY BEDTYPE' then 20
                            when 'BY TOWER' then 30
                            when 'BY PAYER' then 40
                            when 'BY CRITICAL' then 50
                            when 'BY WARD' then 60
                        end)    
                ) AS a          
                order by a.sno asc, a.bor_name  
                """.format(company_id=record.company_id.id,
                           tahun=record.tahun,
                           bulan=record.bulan))
