    # Print Troughput Pharmacy Sheet
    @http.route('/account/troughput_pharmacy_sheet', type='http', auth="user")
    @route()
    def PrintTroughputPharmacySheet(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        # get data filter wizard
        record = sudo.env['wizard.troughput.pharmacy.order'].browse(id)
        data = record.read()[0]
        ext = record.format_print_id

        data['line_ids'] = []
        data['company_name'] = record.company_id.name
        data['start_date'] = record.start_date
        data['end_date'] = record.end_date

        query = sudo.env.cr.execute("""
            SELECT  
                a.tglproses,
                sum(a.troughput) total, 
                sum(case when a.patient_type='IPD' and a.type='SALES' then a.troughput else 0 end) total_ipd_order,
                sum(case when a.patient_type='IPD' and a.type='RETURN' then a.troughput else 0 end) total_ipd_return,
                sum(case when a.patient_type='IPD' then a.troughput else 0 end) total_ipd,
                sum(case when a.patient_type='OPD' and a.type='SALES' then a.troughput else 0 end) total_opd_order,
                sum(case when a.patient_type='OPD' and a.type='RETURN' then a.troughput else 0 end) total_opd_return,
                sum(case when a.patient_type='OPD' then a.troughput else 0 end) total_opd,
                sum(case when a.patient_type='MCU' and a.type='SALES' then a.troughput else 0 end) total_mcu_order,
                sum(case when a.patient_type='MCU' and a.type='RETURN' then a.troughput else 0 end) total_mcu_return,
                sum(case when a.patient_type='MCU' then a.troughput else 0 end) total_mcu
            FROM  troughput_pharmacy_order  a   
            WHERE a.tglproses >= '{start_date}'   
                and a.tglproses <= '{end_date}'
                and a.company_id = '{company_id}'
            group by a.tglproses    
            order by a.tglproses    

                """.format(company_id=record.company_id.id,
                           start_date=record.start_date,
                           end_date=record.end_date))
        troughput_pharmacy_sheet = sudo.env.cr.dictfetchall()

        for r in troughput_pharmacy_sheet:
            obj = {}
            obj['tglproses'] = r['tglproses'] or ' '
            obj['total'] = r['total'] or ' '
            obj['total_ipd_order'] = r['total_ipd_order'] or ' '
            obj['total_ipd_return'] = r['total_ipd_return'] or ' '
            obj['total_ipd'] = r['total_ipd'] or ' '
            obj['total_opd_order'] = r['total_opd_order'] or ' '
            obj['total_opd_return'] = r['total_opd_return'] or ' '
            obj['total_opd'] = r['total_opd'] or ' '
            obj['total_mcu_order'] = r['total_mcu_order'] or ' '
            obj['total_mcu_return'] = r['total_mcu_return'] or ' '
            obj['total_mcu'] = r['total_mcu'] or ' '
            data['line_ids'] += [obj]

        #data = datas.convert(data)
        data = datas.json(data)
        
        url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        
        jasper = JasperClient()
        jasper.login(url, uname, password)

        if str(ext) == 'xls':
            report = jasper.run('/Mayapada/Throughput/troughput_pharmacy_sheet', 'XLS',{'data': data})
            filename = "Report Troughput Pharmacy Sheet.xls"
            return request.make_response(report[1]["data"], [('Content-Type', report[1]["content-type"]), ('Content-Disposition', content_disposition(filename))])
        elif str(ext) == 'pdf':
            report = jasper.run('/Mayapada/Throughput/troughput_pharmacy_sheet', 'PDF',{'data': data})
            filename = "Report Troughput Pharmacy Sheet.pdf"
            return request.make_response(report[1]["data"], [('Content-Type', report[1]["content-type"]), ('Content-Disposition', content_disposition(filename))])
