    # Updated by firgi koreksi 
    @http.route('/accounting/console_financial_report', type='http', auth='user')
    @route()
    def console_financial_report(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['account.console.financial.report.wizard'].browse(id)
        data = {}
        read = record.read()
        # open('/opt/odoo16/logs/console.log', 'a+').write('\n' + str(read))
        # open('/opt/odoo16/logs/console.log', 'a+').write('\n' + str(record.month))
        month_dict = dict(sudo.env['account.console.financial.report.wizard']._fields['month'].selection)
        month = month_dict[record.month]

        # stored data account_report
        data['account_report_id'] = record.financial_report_id.name + " Report " + ("(Debug Mode)" if record.debug_mode == True else "")
        data['date_start'] = 'Jan ' + str(record.year)
        data['date_end'] = str(month) + ' ' + str(record.year)
        data['data_ids'] = []
        data['company_list_ids'] = []
        data['debug_mode'] = record.debug_mode or False
        debug_mode = record.debug_mode

        company_ids = []
        company_child_ids = []

        # stored data company_ids dari company_list_ids dan turunannya
        for company_generate in record.company_list_ids:
            company_child = sudo.env['res.company'].search([('parent_id', '=', company_generate.id)])
            if company_child:
                company_ids += company_child.ids
                company_child_ids += company_child.ids
            else:
                company_ids += [company_generate.id]
            company_obj = {}
            company_obj['company_name'] = company_generate.name
            company_obj['company_id'] = company_generate.id
            company_obj['company_child_ids'] = company_child.ids
            # company_list_ids isi dengan object company_name, id, child_ids
            data['company_list_ids'].append(company_obj)

        date_int = 0
        year_int = 0

        # jika YTD maka ambil dari awal tahun 01-Jan s/d akhir bulan terpilih.
        if record.type_date == 'ytd':
            if int(record.month) != 12:
                date_int = record.month
                year_int = record.year
            else:
                date_int = 0
                year_int = int(record.year) + 1

            start_date = str(record.year) + '-01-01'
            end_date = datetime.strptime(str(year_int) + '-' + str(int(date_int) + 1) + '-01', '%Y-%m-%d') - timedelta(days=1)

