        # ambil list account report yg tidak menampilkan detail COA dlu
        query = """ 
            SELECT DISTINCT
                CASE 
                    WHEN subquery3.parent_sequence_1 = {report_seq} THEN subquery2.parent_sequence_1
                    WHEN subquery3.parent_sequence_1 is null THEN subquery1.parent_sequence
                    ELSE subquery3.parent_sequence_1
                END as top_parent_sequence,
                CASE 
                    WHEN subquery2.parent_sequence_1 = {report_seq} THEN subquery1.parent_sequence
                    ELSE subquery2.parent_sequence_1 
                END as parent_sequence,
                subquery1.parent_sequence as sub_parent_sequence,
                subquery1.sequence as report_sequence,
                CASE 
                    WHEN subquery3.parent_name = '{report_name}' THEN subquery2.parent_name
                    WHEN subquery3.parent_name is null THEN subquery1.parent_name
                    ELSE subquery3.parent_name 
                    END as top_parent,
                CASE 
                    WHEN subquery2.parent_name = '{report_name}' THEN subquery1.parent_name
                    ELSE subquery2.parent_name 
                END as parent,
                subquery1.parent_name as sub_parent,
                subquery1.report_name as report_name,
                subquery1.account_code,
                subquery1.account_name,
                CASE 
                    WHEN subquery1.company_id in {company_ids} THEN subquery1.company_id
                    ELSE subquery1.parent_company_id
                END as company_id,
                subquery1.account_company_id,
                CP.name account_company_name,
                subquery1.balance
            FROM(
                SELECT 
                    account.company_id as account_company_id,
                    financial_report.company_id as company_id,
                    company.parent_id as parent_company_id,
                    financial_report.sequence as sequence,
                    parent.sequence as parent_sequence,
                    parent.name as parent_name,
                    financial_report.name as report_name, 
                    account.code as account_code,
                    COALESCE(account."name"->>'en_US','') as account_name, 
                    ROUND(SUM(coalesce(move_line.debit,0) - coalesce(move_line.credit,0))) as balance             
                FROM account_financial_report as financial_report
                LEFT JOIN account_financial_report as parent on financial_report.parent_id = parent.id
                LEFT JOIN account_account_financial_report as rel on rel.report_line_id = financial_report.id
                LEFT JOIN account_account as account on account.id = rel.account_id
                LEFT JOIN (
                    SELECT 
                        SUM(move_line.debit) debit, 
                        SUM(move_line.credit) credit, 
                        move_line.account_id,
                        '{debug_mode}' debug_mode 
                    FROM account_move as move 
                    INNER JOIN account_move_line as move_line 
                        ON move.id = move_line.move_id
                    WHERE move.state = 'posted'
                        AND move_line.date >= '{date_start}'
                        AND move_line.date <= '{date_end}'
                    GROUP BY move_line.account_id
                ) AS move_line ON move_line.account_id = account.id
                LEFT JOIN res_company as company on company.id = financial_report.company_id
                WHERE financial_report.company_id IN {company_ids}
                    AND parent.name like '{prefix}'
                    AND financial_report.type = 'accounts'
                    AND financial_report.display_detail <> 'no_detail'
                    AND COALESCE(move_line.debug_mode,'True') = '{debug_mode}'
                GROUP BY parent.id, financial_report.id, account.id, company.id
                ORDER BY financial_report.sequence asc
                                
            ) as subquery1
            LEFT JOIN (
                SELECT 
                    financial_report.sequence as sequence_1,
                    parent.sequence as parent_sequence_1,
                    parent.name as parent_name,
                    financial_report.name as report_name
                FROM account_financial_report as financial_report
                LEFT JOIN account_financial_report as parent on financial_report.parent_id = parent.id
                WHERE financial_report.company_id IN {company_ids}
                    AND parent.name like '{prefix}'
                    AND financial_report.type = 'sum'
                GROUP BY parent.id, financial_report.id
                ORDER BY financial_report.sequence asc 
            ) as subquery2 on subquery2.report_name = subquery1.parent_name
            LEFT JOIN (
                SELECT 
                    financial_report.sequence as sequence_1,
                    parent.sequence as parent_sequence_1,
                    parent.name as parent_name,
                    financial_report.name as report_name    
                FROM account_financial_report as financial_report
                LEFT JOIN account_financial_report as parent on financial_report.parent_id = parent.id
                    WHERE financial_report.company_id IN {company_ids}
                    AND parent.name like '{prefix}'
                    AND financial_report.type = 'sum'
                GROUP BY parent.id, financial_report.id
                ORDER BY financial_report.sequence asc 
            ) as subquery3 on subquery3.report_name = subquery2.parent_name     
            LEFT JOIN res_company CP ON CP.id = subquery1.account_company_id
            ORDER BY company_id asc, report_sequence asc
        """.format(
            company_ids=company_ids,
            date_start=start_date, 
            date_end=end_date, 
            prefix=prefix, 
            report_seq=record.financial_report_id.sequence, 
            report_name=record.financial_report_id.name,
            company_child_ids=company_child_ids,
            debug_mode=str(debug_mode)
        )

