    # 2021.09.09 - Cashflow report 
    @http.route('/accounting/cashflow_report', type='http', auth="user")
    @route()
    def cashflow_report(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['account.cashflow.wizard'].browse(id)
        data = {}
        read = record.read()
        # open('/opt/odoo16/logs/cashflow.log', 'a+').write(str(read))

        month = dict(sudo.env['account.cashflow.wizard']._fields['month'].selection)
        month = month[record.month]
        # open('/opt/odoo16/logs/cashflow.log', 'a+').write(str(month))

        data['company_id'] = record.company_id.name
        data['date_start'] = 'Jan ' + str(record.year)
        data['date_end'] = str(month) + ' ' + str(record.year)
        data['sum_total'] = 0
        data['starting_balance'] = 0
        data['ending_balance'] = 0
        data['data_ids'] = []
        date_int = 0
        year_int = 0

        if record.type_date == 'ytd':
            if int(record.month) != 12:
                date_int = record.month
                year_int = record.year

            else:
                date_int = 0
                year_int = int(record.year) + 1

            start_date = datetime.strptime(str(record.year) + '-01-01', '%Y-%m-%d')
            end_date = datetime.strptime(str(year_int) + '-' + str(int(date_int) + 1) + '-01', '%Y-%m-%d') - timedelta(days=1)


        if record.type_date == 'mtd':
            data['date_start'] = False
            data['date_start'] = str(month) + ' ' + str(record.year)
            if int(record.month) != 12:
                date_int = record.month
                year_int = record.year
            else:
                date_int = 0
                year_int = int(record.year) + 1

            start_date = datetime.strptime(str(record.year) + '-' + str(int(record.month)) + '-01', '%Y-%m-%d')
            end_date = datetime.strptime(str(year_int) + '-' + str(int(date_int) + 1) + '-01', '%Y-%m-%d') - timedelta(days=1)

        company_id = "(" + str(record.company_id.id) + ")"
        company_child = sudo.env['res.company'].search([('parent_id', '=', record.company_id.id)]).ids
        if company_child:
            company_id = tuple(company_child)

        query_cf = sudo.env.cr.execute("""
            select  
                cc.name as parent_name, 
                cc.detail as parent_detail, 
                c.name as child_name, 
                c.detail as child_detail,
                case when c.credit_id is null 
                    then coalesce(round(sum(a.debit-a.credit) * -1), 0) 
                    else coalesce(round(sum(a.credit)), 0) 
                end as amount
            from account_move_line a 
            left join account_account b on b.id = a.account_id 
            left join account_account_type t on t.id = b.user_type_id
            left join account_cashflow_type c on c.id = b.type_cashflow_id
            left join account_move d on d.id = a.move_id
            left join account_cashflow_type cc on c.parent_id = cc.id
            where 
            -- cari COA yang bukan termasuk Bank & Cash
            a.account_id not in (
                select id from account_account 
                where user_type_id = ( select id from account_account_type where name = 'Bank and Cash' )
            )
            -- cari COA lawan dari Bank & Cash yg masih dalam satu journal entries 
            and a.move_id in (
                select move_id from account_move_line 
                where account_id in (
                    select id from account_account 
                    where user_type_id = ( select id from account_account_type where name = 'Bank and Cash' )
                )
            ) 
            -- Exclude COA tertentu, kasus TB yg diimport dari MHKN/MHBG seluruh COA di campur dalam satu Journal Entries
            and a.account_id not in(
                select t.account_id 
                from account_cashflow_exclude t 
                where t.company_id in {companyid}
            )
            -- and t.name = 'Bank and Cash'
            and a.company_id in {companyid}
            and a.date >= '{date_start}' and a.date <= '{date_end}'
            and a.year_close is not True
            and d.state = 'posted'
            -- and c.credit_id is null
            GROUP BY cc.name, cc.detail, c.name, c.detail, c.credit_id
            ORDER BY c.name
            """.format(
                companyid=company_id, 
                date_start=start_date, 
                date_end=end_date
            ))

        data_ids = sudo.env.cr.dictfetchall()
        # open('/opt/odoo16/logs/cashflow.log', 'a+').write('\n' + str(data_ids).encode('utf-8'))
        parent_cf = ""

        for d in data_ids:
            sub_obj = {}
            if d['parent_name'] != parent_cf:
                obj = {}
                obj['cf_code'] = d['parent_name'] or 'null'
                obj['cf_name'] = d['parent_detail']
                obj['cf_sum'] = 0
                obj['sub_data_ids'] = []
                data['data_ids'].append(obj)
                parent_cf = d['parent_name']
                # open('/opt/odoo16/logs/cashflow.log', 'a+').write(str(obj).encode('utf-8'))

            sub_obj['sub_cf_code'] = d['child_name'] or 'null'
            sub_obj['sub_cf_name'] = d['child_detail']
            sub_obj['sub_cf_sum'] = d['amount']

            # open('/opt/odoo16/logs/cashflow.log', 'a+').write('\n' + str(sub_obj).encode('utf-8'))
            obj['sub_data_ids'] += [sub_obj]
            # open('/opt/odoo16/logs/cashflow.log', 'a+').write('\n' + 'NON CREDIT ' + '\n' + str(obj['sub_data_ids']).encode('utf-8'))
            obj['cf_sum'] += sub_obj['sub_cf_sum']
            data['sum_total'] += d['amount']


        query_credit = sudo.env.cr.execute("""
            select 
                cc.name as parent_name, 
                cc.detail as parent_detail, 
                ccr.name as child_name, 
                ccr.detail as child_detail, 
                coalesce(round(sum(a.debit) * -1), 0) as amount
            from account_move_line a 
            left join account_account b on b.id = a.account_id 
            left join account_account_type t on t.id = b.user_type_id
            left join account_cashflow_type c on c.id = b.type_cashflow_id
            left join account_move d on d.id = a.move_id
            left join account_cashflow_type cc on c.parent_id = cc.id
            left join account_cashflow_type ccr on c.credit_id = ccr.id
            where a.account_id not in (
                    select id from account_account
                    where user_type_id = ( 
                        select id from account_account_type 
                        where name = 'Bank and Cash' 
                    )
                ) 
                -- and t.name = 'Bank and Cash'
                and a.move_id in (
                    SELECT move_id FROM account_move_line 
                    WHERE account_id IN (
                        SELECT ID FROM account_account 
                        WHERE user_type_id = ( 
                            SELECT ID FROM account_account_type 
                            WHERE NAME = 'Bank and Cash' 
                        )
                    )
                )
                -- Exclude COA tertentu, kasus TB yg diimport dari MHKN/MHBG seluruh COA di campur dalam satu Journal Entries
                and a.account_id not in(
                    select t.account_id 
                    from account_cashflow_exclude t 
                    where t.company_id in {companyid}
                )
                and a.company_id in {companyid}
                and a.date >= '{date_start}' and a.date <= '{date_end}'
                and a.year_close is not True
                and d.state = 'posted'
                and c.credit_id is not null
            GROUP BY cc.name, cc.detail, ccr.name, ccr.detail
            ORDER BY ccr.name
            """.format(
                companyid=company_id,
                date_start=start_date,
                date_end=end_date
            ))

        data_credit = sudo.env.cr.dictfetchall()
        exists = ""
        parent_cf = ""
        # open('/opt/odoo16/logs/cashflow.log', 'a+').write('\n' + str(data_credit).encode('utf-8'))

        for d in data_credit:

            for current in data['data_ids']:
                for current_sub in current['sub_data_ids']:
                    if current_sub['sub_cf_name'] == d['child_detail']:
                        current_sub['sub_cf_sum'] += d['amount']
                        exists = d['child_detail']

                if current['cf_name'] == d['parent_detail']:
                    current['cf_sum'] += d['amount']
                    parent_cf = d['parent_detail']

            if exists != d['child_detail']:
                sub_obj_cr = {}
                if d['parent_detail'] != parent_cf:
                    obj_cr = {}
                    obj_cr['cf_code'] = d['parent_name'] or 'null'
                    obj_cr['cf_name'] = d['parent_detail']
                    obj_cr['cf_sum'] = 0
                    obj_cr['sub_data_ids'] = []
                    data['data_ids'].append(obj_cr)
                    parent_cf = d['parent_detail']
                    # open('/opt/odoo16/logs/cashflow.log', 'a+').write(str(obj).encode('utf-8'))

                sub_obj_cr['sub_cf_code'] = d['child_name'] or 'null'
                sub_obj_cr['sub_cf_name'] = d['child_detail']
                sub_obj_cr['sub_cf_sum'] = d['amount']

                # open('/opt/odoo16/logs/cashflow.log', 'a+').write('\n' + 'BEFORE ' + '\n' + str(obj['sub_data_ids']).encode('utf-8'))
                # obj['sub_data_ids'] += [sub_obj_cr]
                for exist_data in data['data_ids']:
                    if exist_data['cf_name'] == d['parent_detail']:
                        exist_data['sub_data_ids'] += [sub_obj_cr]
                # open('/opt/odoo16/logs/cashflow.log', 'a+').write('\n' + 'AFTER ' + '\n' + str(obj['sub_data_ids']).encode('utf-8'))
                # if 'cf_sum' in obj_cr:
                #     obj_cr['cf_sum'] += sub_obj_cr['sub_cf_sum']

            data['sum_total'] += d['amount']

        query_beginning = sudo.env.cr.execute("""
            select 
                coalesce(round(sum(a.debit-a.credit)), 0) as beginning 
            from account_move_line a
            left join account_move b on a.move_id = b.id
            where a.account_id in (
                select id from account_account 
                where user_type_id = ( 
                    select id from account_account_type 
                    where name = 'Bank and Cash' 
                ))
                and a.year_close is not True
                and a.company_id in {companyid}
                and a.date < '{date_start}'
                and b.state = 'posted'
            """.format(
                companyid=company_id,
                date_start=start_date
            ))

        beginning = sudo.env.cr.dictfetchall()
        for beg in beginning:
            data['starting_balance'] = beg['beginning']
            data['ending_balance'] = beg['beginning'] + data['sum_total']

        data['data_ids'] = sorted(data['data_ids'], key=itemgetter('cf_code'))
        for sort_current in data['data_ids']:
            sort_current['sub_data_ids'] = sorted(sort_current['sub_data_ids'], key=itemgetter('sub_cf_code'))

        # open('/opt/odoo16/logs/cashflow.log', 'a+').write('\n' + str(data['data_ids']).encode('utf-8'))
        # for sort_current in data['data_ids']:
        #     sort = sorted(data, key=itemgetter('cf_code'))
        #     open('/opt/odoo16/logs/cashflow.log', 'a+').write('\n' + str(sort).encode('utf-8'))
        # data['data_ids'] = sorted(sort_current, key=itemgetter('cf_code'))
        # for sort_current_sub in sort_current['sub_data_ids']:
        #     sort_current_sub['sub_data_ids'] = sorted(sort_current_sub, key=itemgetter('sub_cf_code'))
        # data = datas.convert(data)
        # open('/opt/odoo16/logs/cashflow.log', 'a+').write('\n' + str(data).encode('utf-8'))

        data = datas.convert(data)
        data = datas.json(data, cdata=False)
        url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        # open('/opt/odoo16/logs/cashflow.log', 'a+').write(str(data).encode('utf-8'))

        import requests
        from lxml import etree

        execution = requests.post('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions',
            auth=(uname, password),
            json={
                'reportUnitUri': '/Mayapada16/Accounting/Cashflow_Report',
                'outputFormat': 'xls',
                'parameters': {
                    'reportParameter': [{
                        'name': 'data',
                        'value': [data]
                    }]
                }
            })
        # report = jasper.run('/Mayapada/DoctorFee/Doctor_Fee_Excel', 'XLS', {'data': data})
        xml = etree.XML(execution.content)
        request_id = xml.find('.//requestId').text
        export_id = xml.find('.//export//id').text
        result = requests.get('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions/' + request_id + '/exports/' + export_id + '/outputResource',cookies=execution.cookies)
        filename = "Cashflow Report.xls"
        return request.make_response(result.content,[('Content-Type', result.headers['content-type']),('Content-Disposition', content_disposition(filename))])



