        data['starting_balance'] = 0
        data['ending_balance'] = 0
        data['data_ids'] = []
        data['total_list_ids'] = []
        data['company_list_ids'] = []
        date_int = 0
        year_int = 0

        if record.type_date == 'ytd':
            if int(record.month) != 12:
                date_int = record.month
                year_int = record.year

            else:
                date_int = 0
                year_int = int(record.year) + 1

            date_start = str(record.year) + '-01-01'
            date_end = datetime.strptime(str(year_int) + '-' + str(int(date_int) + 1) + '-01', '%Y-%m-%d') - timedelta(days=1)

        if record.type_date == 'mtd':
            data['date_start'] = False
            data['date_start'] = str(month) + ' ' + str(record.year)
            if int(record.month) != 12:
                date_int = record.month
                year_int = record.year
            else:
                date_int = 0
                year_int = int(record.year) + 1
            date_start = datetime.strptime(str(record.year) + '-' + str(int(record.month)) + '-01', '%Y-%m-%d')
            date_end = datetime.strptime(str(year_int) + '-' + str(int(date_int) + 1) + '-01', '%Y-%m-%d') - timedelta(days=1)

        company_ids = []
        company_child_ids = []

        # stored data company_ids dari company_list_ids dan turunannya
        for company_generate in record.company_list_ids:
            company_child = sudo.env['res.company'].search([('parent_id', '=', company_generate.id)])
            if company_child:
                company_ids += company_child.ids
                company_child_ids += company_child.ids
            else:
                company_ids += [company_generate.id, 0]
            company_obj = {}
            company_obj['company_name'] = company_generate.name
            company_obj['company_id'] = company_generate.id
            company_obj['company_child_ids'] = company_child.ids
            company_obj['sum_amount'] = 0
            company_obj['starting_balance'] = 0
            company_obj['ending_balance'] = 0
            data['company_list_ids'].append(company_obj)

        # open('/opt/odoo16/logs/console_cashflow.log', 'a+').write('\n' + str(company_ids))
        if len(company_ids) < 1:
            company_ids.extend([0, 0])

        company_ids = tuple(company_ids)

        # query CF
        query = """
            select 
                cp.id company_id, 
                cp.name company_name,
                cc.name as parent_name, 
                cc.detail as parent_detail, 
                c.name as child_name, 
                c.detail as child_detail, 
                b.id as coa_id,
                b.code as coa_code, 
                COALESCE(b."name"->>'en_US','') as coa_name,
                CASE WHEN c.credit_id is null 
                    THEN COALESCE(ROUND(sum(a.debit-a.credit) * -1), 0) 
                    ELSE COALESCE(ROUND(sum(a.credit)), 0) 
                END as amount
            from account_move_line a 
            left join account_account b on b.id = a.account_id 
            left join account_cashflow_type c on c.id = b.type_cashflow_id
            left join account_move d on d.id = a.move_id
            left join account_cashflow_type cc on c.parent_id = cc.id
            left join res_company cp on cp.id = a.company_id
            where a.account_id not in (
                select id from account_account 
                where user_type_id = ( 
                    SELECT ID FROM account_account_type 
                    WHERE NAME = 'Bank and Cash' 
                )) 
                and a.move_id in (
                    SELECT move_id FROM account_move_line 
                    WHERE account_id IN (
                        SELECT ID FROM account_account 
                        WHERE user_type_id = ( 
                            SELECT ID FROM account_account_type 
                            WHERE NAME = 'Bank and Cash' 
                        )
                    )
                ) 
                -- Exclude COA tertentu, kasus TB yg diimport dari MHKN/MHBG seluruh COA di campur dalam satu Journal Entries
                and a.account_id not in(
                    select t.account_id 
                    from account_cashflow_exclude t 
                    where t.company_id in {company_ids}
                )
                and a.company_id in {company_ids}
                and a.date >= '{date_start}' and a.date <= '{date_end}'
                and a.year_close is not True
                and d.state = 'posted'
                -- and c.credit_id is null
            group by cc.name, cc.detail, c.name, b.id, 
                c.detail, c.credit_id, b.code, COALESCE(b."name"->>'en_US',''), cp.id, cp.name
            order by parent_name, child_name, coa_code
            """.format(
                company_ids=company_ids,
                date_start=date_start,
                date_end=date_end)
        open('/opt/odoo16/logs/console_cashflow.log', 'a+').write('\n' + str(query))
        query_cf = sudo.env.cr.execute(query)
        data_ids = sudo.env.cr.dictfetchall()

        parent_cf = ""
        sub_cf = ""

        for d in data_ids:
            # create parent CF
            if d['parent_name'] != parent_cf:
                obj = {}
                obj['cf_code'] = d['parent_name'] or 'null'
                obj['cf_name'] = d['parent_detail']
                obj['cf_sum'] = 0
                obj['company_sum_ids'] = []
                
                for company_list in data['company_list_ids']:
                    cp_ids = {}
                    cp_ids['company_name'] = company_list['company_name']
                    cp_ids['company_id'] = company_list['company_id']
                    cp_ids['company_child_ids'] = company_list['company_child_ids']
                    cp_ids['sum_amount'] = 0
                    obj['company_sum_ids'].append(cp_ids)

                obj['sub_data_ids'] = []
                data['data_ids'].append(obj)
                parent_cf = d['parent_name']
                

            # create child CF
            if d['child_name'] != sub_cf:
                sub_obj = {}
                sub_obj['sub_cf_code'] = d['child_name'] or 'null'
                sub_obj['sub_cf_name'] = d['child_detail']
                sub_obj['sub_cf_sum'] = 0
                sub_obj['company_sum_ids'] = []

                for company_list in data['company_list_ids']:
                    cp_ids = {}
                    cp_ids['company_name'] = company_list['company_name']
                    cp_ids['company_id'] = company_list['company_id']
                    cp_ids['company_child_ids'] = company_list['company_child_ids']
                    cp_ids['sum_amount'] = 0
                    sub_obj['company_sum_ids'].append(cp_ids)

                sub_obj['sub_sub_data_ids'] = []
                obj['sub_data_ids'].append(sub_obj)
                sub_cf = d['child_name']

            # create COA
            sub_sub_obj = {}
            sub_sub_obj['sub_sub_cf_id'] = d['coa_id']
            sub_sub_obj['sub_sub_cf_code'] = d['coa_code'] or 'null'
            sub_sub_obj['sub_sub_cf_name'] = d['coa_name']
            sub_sub_obj['sub_sub_cf_sum'] = d['amount']
            sub_sub_obj['company_sum_ids'] = []
            
            for company_list in data['company_list_ids']:
                cp_ids = {}
                cp_ids['company_name'] = company_list['company_name']
                cp_ids['company_id'] = company_list['company_id']
                cp_ids['company_child_ids'] = company_list['company_child_ids']
                cp_ids['sum_amount'] = (d['amount'] if d['company_id'] == company_list['company_id'] else 0)
                sub_sub_obj['company_sum_ids'].append(cp_ids)


            sub_obj['sub_sub_data_ids'] += [sub_sub_obj]
            # sum total per detail CF
            sub_obj['sub_cf_sum'] += d['amount']
            for cp in sub_obj['company_sum_ids']:
                if cp['company_id'] == d['company_id']:
                    cp['sum_amount'] += d['amount']

            # sum total per CF
            obj['cf_sum'] += d['amount']
            for cp in obj['company_sum_ids']:
                if cp['company_id'] == d['company_id']:
                    cp['sum_amount'] += d['amount']

            # sum total per company
            data['sum_total'] += d['amount']
            for cp in data['company_list_ids']:
                if cp['company_id'] == d['company_id']:
                    cp['sum_amount'] += d['amount']


        # query credit 
        query = """
            SELECT 
                cp.id company_id, 
                cp.name company_name,
                cc.name as parent_name, 
                cc.detail as parent_detail, 
                ccr.name as child_name, 
                ccr.detail as child_detail, 
                b.id as coa_id,
                b.code as coa_code, 
                COALESCE(b."name"->>'en_US','') as coa_name,
                COALESCE(ROUND(sum(a.debit) * -1), 0) as amount
            from account_move_line a 
            left join account_account b on b.id = a.account_id 
            left join account_cashflow_type c on c.id = b.type_cashflow_id
            left join account_move d on d.id = a.move_id
            left join account_cashflow_type cc on c.parent_id = cc.id
            left join account_cashflow_type ccr on c.credit_id = ccr.id
            left join res_company cp on cp.id = a.company_id
            WHERE a.account_id not in (
                SELECT ID FROM account_account 
                WHERE user_type_id = ( 
                    SELECT ID FROM account_account_type 
                    WHERE NAME = 'Bank and Cash' 
                )) 
                and a.move_id in (
                    SELECT move_id FROM account_move_line 
                    WHERE account_id IN (
                        SELECT ID FROM account_account 
                        WHERE user_type_id = ( 
                            SELECT ID FROM account_account_type 
                            where name = 'Bank and Cash' 
                        )
                    )
                ) 
                -- Exclude COA tertentu, kasus TB yg diimport dari MHKN/MHBG seluruh COA di campur dalam satu Journal Entries
                and a.account_id not in(
                    select t.account_id 
                    from account_cashflow_exclude t 
                    where t.company_id in {company_ids}
                )
                and a.company_id in {company_ids}
                and a.date >= '{date_start}' and a.date <= '{date_end}'
                and a.year_close is not True
                and d.state = 'posted'
                and c.credit_id is not null
            GROUP BY cc.name, cc.detail, ccr.name, b.id, 
                ccr.detail, b.code, COALESCE(b."name"->>'en_US',''), cp.id, cp.name
            ORDER BY parent_name, child_name, coa_code
        """.format(
                company_ids=company_ids,
                date_start=date_start,
                date_end=date_end)
        open('/opt/odoo16/logs/console_cashflow.log', 'a+').write('\n' + str(query))
        query_credit = sudo.env.cr.execute(query)
        data_credit = sudo.env.cr.dictfetchall()
        sub_cf_cr = ""
        parent_cf_cr = ""
        sub_sub_cf_cr = ""
        

        for d in data_credit:
            for current in data['data_ids']:
                for current_sub in current['sub_data_ids']:
                    for current_sub_sub in current_sub['sub_sub_data_ids']:

                        # update total per COA
                        if current_sub_sub['sub_sub_cf_id'] == d['coa_id'] and current_sub['sub_cf_name'] == d['child_detail']:
                            current_sub_sub['sub_sub_cf_sum'] += d['amount']
                            for cp in current_sub_sub['company_sum_ids']:
                                if cp['company_id'] == d['company_id']:
                                    cp['sum_amount'] += d['amount']

                            sub_sub_cf_cr = d['coa_id']
                            sub_cf_cr = d['child_detail']

                    # update total per detail CF
                    if current_sub['sub_cf_name'] == d['child_detail']:
                        current_sub['sub_cf_sum'] += d['amount']
                        for cp in current_sub['company_sum_ids']:
                            if cp['company_id'] == d['company_id']:
                                cp['sum_amount'] += d['amount']
                        sub_cf_cr = d['child_detail']

                # update total per CF
                if current['cf_name'] == d['parent_detail']:
                    current['cf_sum'] += d['amount']
                    for cp in current['company_sum_ids']:
                        if cp['company_id'] == d['company_id']:
                            cp['sum_amount'] += d['amount']
                    parent_cf_cr = d['parent_detail']



            if sub_sub_cf_cr != d['coa_id']:
                # create new if not exists parent CF
                if d['parent_detail'] != parent_cf_cr:
                    obj = {}
                    obj['cf_code'] = d['parent_name'] or 'null'
                    obj['cf_name'] = d['parent_detail']
                    obj['cf_sum'] = d['amount']
                    obj['company_sum_ids'] = []

                    for company_list in data['company_list_ids']:
                        cp_ids = {}
                        cp_ids['company_name'] = company_list['company_name']
                        cp_ids['company_id'] = company_list['company_id']
                        cp_ids['company_child_ids'] = company_list['company_child_ids']
                        cp_ids['sum_amount'] = (d['amount'] if d['company_id'] == company_list['company_id'] else 0)
                        obj['company_sum_ids'].append(cp_ids)

                    obj['sub_data_ids'] = []
                    data['data_ids'].append(obj)
                    parent_cf_cr = d['parent_name']

                # create new if not exists detail CF
                if d['child_detail'] != sub_cf_cr:
                    sub_obj = {}
                    sub_obj['sub_cf_code'] = d['child_name'] or 'null'
                    sub_obj['sub_cf_name'] = d['child_detail']
                    sub_obj['sub_cf_sum'] = d['amount']
                    sub_obj['company_sum_ids'] = []

                    for company_list in data['company_list_ids']:
                        cp_ids = {}
                        cp_ids['company_name'] = company_list['company_name']
                        cp_ids['company_id'] = company_list['company_id']
                        cp_ids['company_child_ids'] = company_list['company_child_ids']
                        cp_ids['sum_amount'] = (d['amount'] if d['company_id'] == company_list['company_id'] else 0)
                        sub_obj['company_sum_ids'].append(cp_ids)

                    sub_obj['sub_sub_data_ids'] = []

                    # append detail CF to parent CF
                    for exist_data in data['data_ids']:
                        if exist_data['cf_name'] == d['parent_detail']:
                            exist_data['sub_data_ids'] += [sub_obj]

                    sub_cf_cr = d['child_detail']

                # create new COA
                sub_sub_obj_cr = {}
                sub_sub_obj_cr['sub_sub_cf_id'] = d['coa_id']
                sub_sub_obj_cr['sub_sub_cf_code'] = d['coa_code'] or 'null'
                sub_sub_obj_cr['sub_sub_cf_name'] = d['coa_name']
                sub_sub_obj_cr['sub_sub_cf_sum'] = d['amount']
                sub_sub_obj_cr['company_sum_ids'] = []

                for company_list in data['company_list_ids']:
                    cp_ids = {}
                    cp_ids['company_name'] = company_list['company_name']
                    cp_ids['company_id'] = company_list['company_id']
                    cp_ids['company_child_ids'] = company_list['company_child_ids']
                    cp_ids['sum_amount'] = (d['amount'] if d['company_id'] == company_list['company_id'] else 0)
                    sub_sub_obj_cr['company_sum_ids'].append(cp_ids)

                # append detail COA to detail
                for exist_data in data['data_ids']:
                    for exist_sub_data in exist_data['sub_data_ids']:
                        if exist_sub_data['sub_cf_name'] == d['child_detail']:
                            exist_sub_data['sub_sub_data_ids'] += [sub_sub_obj_cr]

            data['sum_total'] += d['amount']
            # tambahkan total sum per company
            for cp in data['company_list_ids']:
                if cp['company_id'] == d['company_id']:
                    cp['sum_amount'] += d['amount']



        # ending balance
        query = """
            select 
                cp.id company_id, cp.name company_name,
                COALESCE(ROUND(sum(a.debit-a.credit)), 0) as beginning 
            from account_move_line a
            left join account_move b on a.move_id = b.id
            left join res_company cp on cp.id = a.company_id
            where a.account_id in (
                SELECT ID FROM account_account 
                WHERE user_type_id = ( 
                    SELECT ID FROM account_account_type 
                    WHERE NAME = 'Bank and Cash' 
                ))
                and a.year_close is not True
                and a.company_id in {company_ids}
                and a.date < '{date_start}'
                and b.state = 'posted'
            group by cp.id, cp.name
            """.format(
                company_ids=company_ids,
                date_start=date_start
            )
        query_beginning = sudo.env.cr.execute(query)
        beginning = sudo.env.cr.dictfetchall()
        for beg in beginning:
            data['starting_balance'] += beg['beginning']
            data['ending_balance'] += beg['beginning'] 
            data['ending_balance'] += data['sum_total']

            # tambahkan total sum per company
            for cp in data['company_list_ids']:
                if cp['company_id'] == beg['company_id']:
                    cp['starting_balance'] += beg['beginning']
                    cp['ending_balance'] += beg['beginning'] 
                    cp['ending_balance'] += cp['sum_amount']

        # Ubah sorting file based on code CF
        data['data_ids'] = sorted(data['data_ids'], key=itemgetter('cf_code'))
        for sort_current in data['data_ids']:
            sort_current['sub_data_ids'] = sorted(sort_current['sub_data_ids'], key=itemgetter('sub_cf_code'))
            for sor_sub_current in sort_current['sub_data_ids']:
                sor_sub_current['sub_sub_data_ids'] = sorted(sor_sub_current['sub_sub_data_ids'],key=itemgetter('sub_sub_cf_code'))

        # Copy Dataset
        data['total_list_ids'] = data['company_list_ids']

        data = datas.convert(data)
        data = datas.json(data, cdata=False)
        # open('/opt/odoo16/logs/console_cashflow.log', 'a+').write(str(data).encode('utf-8'))

        url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        
        import requests
        from lxml import etree

        execution = requests.post(
            'http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions',
            auth=(uname, password),
            json={
                'reportUnitUri': '/Mayapada16/Accounting/Cashflow_Console_Report_Detail_New',
                'outputFormat': 'xls',
                'parameters': {
                    'reportParameter': [{
                        'name': 'data',
                        'value': [data]
                    }]
                }
            })
        
        xml = etree.XML(execution.content)
        request_id = xml.find('.//requestId').text
        export_id = xml.find('.//export//id').text
        result = requests.get('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions/' + request_id + '/exports/' + export_id + '/outputResource', cookies=execution.cookies)
        filename = "Console Cashflow Detail Report.xls"
        return request.make_response(result.content, [('Content-Type', result.headers['content-type']), ('Content-Disposition', content_disposition(filename))])

