    @http.route('/account/approval_pv_sheet', type='http', auth="user")
    @route()
    def ApprovalPVSheet(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        # get data filter wizard
        record = sudo.env['account.payment'].browse(id)
        data = record.read()[0]
        ttd = 1
        sign = 1

        data['ttd_auto1'] = ""
        data['ttd_auto2'] = ""
        data['sign1'] = ""
        data['sign2'] = ""
        for rule_id in record.approve_id.rule_ids.sorted(key=lambda data: data.sequence, reverse=True):
            data['ttd_auto' + str(ttd)] = sudo.env['res.users'].sudo().search([('company_ids', '=', record.company_id.id),('position_id', '=', rule_id.position_id.id)],limit=1).name
            # data['ttd' + str(ttd)] = sudo.env['res.users'].sudo().search([('position_id', '=', rule_id.position_id.id)], limit=1).name
            ttd += 1
        for rule_id in record.approve_id.rule_ids.sorted(key=lambda data: data.sequence, reverse=True):
            data['sign' + str(sign)] = sudo.env['res.users'].sudo().search([('company_ids', '=', record.company_id.id),('position_id', '=', rule_id.position_id.id)],limit=1).sign
            # data['sign' + str(sign)] = sudo.env['res.users'].sudo().search([('position_id', '=', rule_id.position_id.id)], limit=1).sign
            sign += 1

        data['company'] = record.journal_id.company_id.name
        data['address'] = record.journal_id.company_id.street
        data['city'] = record.journal_id.company_id.city
        data['zip'] = record.journal_id.company_id.zip
        data['date'] = tools.datetime.strptime(record.payment_date,'%Y-%m-%d').strftime('%d-%m-%Y')
        data['no'] = record.name
        data['no_cek'] = record.cheque
        mid = record.move_line_ids.mapped('move_id')
        payment_line = sudo.env['account.move.line'].search([('move_id', 'in', mid.ids), ('account_id.user_type_id', '=', 3), ('credit','>', 0)])
        sums = False
        for p in payment_line:
            sums += p.debit + p.credit
            data['terbilang'] = num2words(int(sums), lang='id',to='currency').title()

        data = datas.convert(data)
        data = datas.json(data)
        
        url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        # url = "http://10.2.1.120:8080/jasperserver/services/repository?wsdl"
        # uname = 'jasperadmin'
