    # Payment Grouping AP
    @http.route('/account/payment_grouping_ap', type='http', auth="user")
    @route()
    def PaymentGrouping(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        # get data filter wizard
        wizard = sudo.env['account.payment.grouping.wizard'].browse(id)
        data = wizard.read()[0]
        user = request.env.user

        data['summary'] = " pada tanggal " + tools.datetime.strptime(wizard.date, '%Y-%m-%d').strftime('%d %B %Y') + ""

        if wizard.x_hide_date:
            data['summary'] = ""

        data['address'] = user.company_id.street
        data['city'] = user.company_id.city
        data['zip'] = user.company_id.zip
        data['phone'] = user.company_id.phone
        data['fax'] = user.company_id.fax
        data['bank_asal'] = wizard.bank_id.name
        data['no_giro'] = wizard.cheque
        data['date'] = tools.datetime.strptime(wizard.date,'%Y-%m-%d').strftime('%d %B %Y')
        data['total_nominal'] = 0
        data['total_biaya'] = 0
        data['net_total'] = 0
        data['company'] = user.company_id.name
        data['line_ids'] = []
        payment = sudo.env['account.payment'].search([('journal_id.id', '=', wizard.bank_id.id),('cheque', '=', wizard.cheque),('company_id.id', '=', user.company_id.id)])
        if payment:
            for record in payment:
                obj = {}
                obj['nominal'] = 0
                obj['biaya'] = 0
                mid = record.move_line_ids.mapped('move_id')
                payment_line = sudo.env['account.move.line'].search([('move_id', 'in', mid.ids),('account_id.user_type_id', '=', 3)])
                sums = False
                for p in payment_line:
                    sums += p.debit + p.credit
                    obj['bank'] = record.bank_id.bank_name.name
                    obj['branch'] = record.bank_id.bank_branch
                    obj['journal'] = record.name
                    obj['vendor'] = record.partner_id.name
                    obj['no_rekening'] = record.bank_id.account_no
                    obj['untuk'] = record.bank_id.beneficiary_name
                    obj['nominal'] = sums
                    obj['biaya'] = record.bank_amount
                    obj['total'] = obj['nominal'] - obj['biaya']

                    data['total_nominal'] += obj['nominal']
                    data['total_biaya'] += obj['biaya']
