    # Print Out Doctor Fee
    @http.route('/account/print_out_doctor_fee', type='http', auth="user")
    @route()
    def PrintOutDoctorFee(self, id, ext='pdf', **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        # get data filter wizard
        # patient_types = dict(sudo.env['sale.order.line']._fields['patient_type'].selection)
        record = sudo.env['doctor.fee'].browse(id)
        data = {}
        month = dict(sudo.env['doctor.fee']._fields['month'].selection)

        # data['sign_1'] = "Ferdy Mareta"
        # data['sign_2'] = "FX. Burniadi"
        data['sign_1'] = record.company_id.df_ttd1 
        data['sign_2'] = record.company_id.df_ttd2
        data['title_1'] = record.company_id.df_title1 
        data['title_2'] = record.company_id.df_title2
        data['df_sign_1'] = record.company_id.df_sign_1 
        data['df_sign_2'] = record.company_id.df_sign_2
        data['city'] = record.company_id.df_city or ''

        data['company'] = record.company_id.name
        data['company_code'] = record.company_id.company_code
        data['doctor_code'] = record.doctor_id.code
        data['doctor_name'] = record.doctor_id.name
        # data['start_date'] = tools.datetime.strptime(record.start_date,'%Y-%m-%d').strftime('%d-%m-%Y')
        # data['end_date'] = tools.datetime.strptime(record.end_date,'%Y-%m-%d').strftime('%d-%m-%Y')
        data['start_date'] = month[record.month]
        data['end_date'] = record.year
        data['fee_transaction'] = (record.total - record.other - record.pot_share - record.p12_share - record.igd_share - record.tnc_share - record.pengirim_share - record.hd_share)
        data['taxes'] = (record.dpp - record.other - record.pot_share - record.p12_share - record.igd_share - record.tnc_share - record.pengirim_share - record.hd_share)
        data['add_transaction'] = record.other
        data['add_pot_share'] = record.pot_share

        # 2023.03.15 khusus MHTG
        data['add_p12_share'] = record.p12_share
        data['add_igd_share'] = record.igd_share
        data['add_tnc_share'] = record.tnc_share
        data['add_pengirim_share'] = record.pengirim_share
        data['add_hd_share'] = record.hd_share

        data['is_pot'] = '1' if record.is_pot_gp is True else '0'
        data['is_p12'] = '1' if record.is_p12 is True else '0'
        data['is_igd'] = '1' if record.is_igd is True else '0'
        data['is_tnc'] = '1' if record.is_tnc is True else '0'
        data['is_pengirim'] = '1' if record.is_pengirim is True else '0'
        data['is_hd'] = '1' if record.is_hd is True else '0'

        data['add_allowance'] = record.allowance
        data['ded_taxes'] = float(record.pph_21)
