    # Package
    # Print Out Costing Customer
    @http.route('/package/print_out_costing_customer', type='http', auth="user")
    @route()
    def PrintOutCostingCustomer(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['mrp.bom'].browse(id)
        data = record.read()[0]

        data['company_name'] = record.company_id.name
        data['adress'] = record.company_id.street
        data['package_type'] = record.package_type.upper()
        data['package'] = record.origin
        data['cost_code'] = record.code
        data['total_price'] = 0
        data['total_proposed'] = 0
        data['data_ids'] = []

        query1 = """SELECT DISTINCT mbl.cost_type material_type,
                CASE WHEN mbl.cost_type = 'material_cost' THEN 'MATERIAL COST'
                WHEN mbl.cost_type = 'service_cost' THEN 'SERVICE COST'
                WHEN mbl.cost_type = 'direct_cost' THEN 'DIRECT COST'
                WHEN mbl.cost_type = 'foh' THEN 'OVERHEAD COST'
                ELSE '' END material_name, 
            pt.id product_id, pt.name product_name, 
            mbl.normal_price unit_price, mbl.product_qty qty,
            (mbl.normal_price * mbl.product_qty) cost_total from mrp_bom_line mbl
            LEFT JOIN mrp_bom mb ON mbl.bom_id=mb.id 
            LEFT JOIN product_product pp ON mbl.product_id=pp.id 
            LEFT JOIN product_template pt ON pp.product_tmpl_id=pt.id
            LEFT JOIN product_category pc ON pt.categ_id=pc.id 
            where mb.company_id={company_id} and mbl.bom_id={cost_id}
            order by mbl.cost_type, pt.name
            """.format(company_id=record.company_id.id,
                cost_id=id)
        
        query = sudo.env.cr.execute(query1)
        lines = sudo.env.cr.dictfetchall()

        sno = 0

        material_child = []
        item_child = []
        
        
        # group categ, product
        for cost in lines:
            sno += 1

            # group based on material
            if cost['material_type'] not in material_child:
                material = {}
                material['material_name'] = cost['material_name'] or '-'
                data['total_price'] += cost['cost_total']
                data['data_ids'] += [material]
                material['item_ids'] = []
                data['total_proposed'] = 0
                data['total_price'] = 0
                item_child = []
                material_child.append(cost['material_type'])

            # group based on item 
            if cost['product_id'] not in item_child:
                item = {}
                item['product_name'] = cost['product_name'] or '-'
                item['qty'] = int(cost['qty']) or 0
                item['unit_price'] = int(cost['unit_price']) or 0
                item['cost_total'] = int(cost['cost_total']) or 0
                data['total_price'] += int(cost['cost_total'])
                data['total_proposed'] = int(record.price_final)
                material['item_ids'] += [item]
                item_child.append(cost['product_id'])

        data = datas.convert(data)
        data = datas.json(data)
        
        url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        
        jasper = JasperClient()
        jasper.login(url, uname, password)
        report = jasper.run('/Mayapada/Package/Print_Out_Costing_Customer','PDF', {'data': data})
        filename = "Print Out Costing Customer.pdf"

        return request.make_response(report[1]["data"],[('Content-Type', report[1]["content-type"]),('Content-Disposition', content_disposition(filename))])
        # return json.dumps(data)


