    @http.route('/package/print_out_costing_internal',type='http',auth="user")
    @route()
    def PrintOutCostingInternal(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        # get data filter wizard
        record = sudo.env['mrp.bom'].browse(id)
        data = record.read()[0]

        data['company_name'] = record.company_id.name
        data['adress'] = record.company_id.street
        data['package_type'] = record.package_type.upper()
        data['package'] = record.origin
        data['cost_code'] = record.code
        data['mcu'] = record.product_tmpl_id.name
        data['total_A'] = 0
        data['total_I'] = 0
        data['total_II'] = 0
        data['total_III'] = 0
        data['total_other'] = 0
        data['total_B'] = 0
        data['total_C'] = 0
        data['total_D'] = 0
        data['costing_margin'] = int(record.margin)
        data['costing_total'] = int(record.cost_total)
        data['costing_price'] = int(record.cost_overhead)
        data['proposed_final'] = int(record.price_final)
        data['pph_23_total'] = int(record.pph_23_total)
        data['price_normal'] = int(record.price_normal)
        data['data_ids'] = []

        query1 = """SELECT DISTINCT mbl.cost_type material_type, 
            CASE WHEN mbl.cost_type = 'material_cost' THEN 'MATERIAL COST'
            WHEN mbl.cost_type = 'service_cost' THEN 'SERVICE COST'
            WHEN mbl.cost_type = 'direct_cost' THEN 'DIRECT COST'
            WHEN mbl.cost_type = 'foh' THEN 'OVERHEAD COST'
            ELSE '' END material_name, 
                pt.id product_id, pt.name product_name, 
                COALESCE(mbl.normal_price, 0) normal_price,
                COALESCE(mbl.cost_product, 0) cost_product,
                COALESCE(mbl.cost_service, 0) cost_service,
                COALESCE(mbl.cost_foh, 0) foh, 
                COALESCE(mbl.product_qty, 0) qty from mrp_bom_line mbl
            LEFT JOIN mrp_bom mb ON mbl.bom_id=mb.id 
            LEFT JOIN product_product pp ON mbl.product_id=pp.id 
            LEFT JOIN product_template pt ON pp.product_tmpl_id=pt.id
            LEFT JOIN product_category pc ON pt.categ_id=pc.id 
                where mb.company_id={company_id} and mbl.bom_id={cost_id}
                order by mbl.cost_type, pt.name""".format(
                company_id=record.company_id.id,
                cost_id=id)

        open('/opt/odoo16/logs/belajar.log','a+').write('\n' + str(query1).encode('utf-8'))
        
        query = sudo.env.cr.execute(query1)
        lines = sudo.env.cr.dictfetchall()

        sno = 0

        material_child = []
        item_child = []
        
        
        # group categ, product
        for cost in lines:
            sno += 1

            # group based on material
            if cost['material_type'] not in material_child:
                material = {}
                material['material_name'] = cost['material_name'] or '-'
                data['data_ids'] += [material]
                material['item_ids'] = []
                material['total_price'] = 0
                item_child = []
                material_child.append(cost['material_type'])

            # group based on item 
            if cost['product_id'] not in item_child:
                item = {}
                item['product_name'] = cost['product_name'] or 0
                item['A'] = int(cost['normal_price']) or 0
                item['I'] = int(cost['cost_product']) or 0
                item['II'] = int(cost['cost_service']) or 0
                item['III'] = int(cost['foh']) or 0
                item['other'] = int(0)
                item['B'] = int(item['I']) + int(item['II']) + int(item['III'])
                item['C'] = int(cost['qty']) or 0
                item['D'] = int(item['B']) * int(item['C'])
                data['total_A'] += int(item['A'])
                data['total_I'] += int(item['I'])
                data['total_II'] += int(item['II'])
                data['total_III'] += int(item['III'])
                data['total_other'] += int(item['other'])
                data['total_B'] += int(item['B'])
                data['total_C'] += int(item['C'])
                data['total_D'] += int(item['D'])
                material['item_ids'] += [item]
                item_child.append(cost['product_id'])

