    # Aging report invoice
    @http.route('/accounting/aging_report_summary', type='http', auth="user")
    @route()
    def aging_report_summary(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['account.receivable.report.compiled.wizard'].browse(id)
        data = {}
        ext = record.format_print_id
        date_end = (record.date_end).strftime('%Y-%m-%d')
        date_min = (record.company_id.cutoff_ar_aging).strftime('%Y-%m-%d')
        partner_id = record.partner_id.id
        
        # Validate To One Payer Select
        partner_ids = record.partner_ids.ids
        if partner_ids:
            partner_ids.append(0)

        data['company_id'] = record.company_id.name
        data['end_date'] = date_end
        data['cutoff_ar'] = date_min
        data['total_unbilled'] = 0
        data['total_invoice'] = 0
        data['total_not_overdue'] = 0
        data['total_30_days'] = 0
        data['total_60_days'] = 0
        data['total_90_days'] = 0
        data['total_older'] = 0
        data['total_outstanding'] = 0
        data['total_unreconcile'] = 0
        data['total_discount'] = 0
        data['total_receipt'] = 0
        data['total_ar_outstanding'] = 0
        data['total_avg_ar'] = 0
        data['total_avg_revenue'] = 0
        data['total_ratio_turnover'] = 0
        data['total_ratio_days'] = 0
        data['allowance_da'] = 0

        data['data_ids'] = []
        open('/opt/odoo16/logs/aging.log', 'a+').write('\n' + "start query1")

        query1="""
                SELECT ai.sno, ai.payer_type, 
                    SUM(ai.total_unbilled) total_unbilled,
                    SUM(ai.total_invoice) total_invoice,
                    --CATATAN: Aging tidak boleh MINUS, kalau minus masukin sebagai uncreconciled payment 
                    SUM(CASE WHEN ai.aging_not_overdue >= 0 THEN ai.aging_not_overdue ELSE 0 END) aging_not_overdue,
                    SUM(CASE WHEN ai.aging_30_days >= 0 THEN ai.aging_30_days ELSE 0 END) aging_30_days,
                    SUM(CASE WHEN ai.aging_60_days >= 0 THEN ai.aging_60_days ELSE 0 END) aging_60_days,
                    SUM(CASE WHEN ai.aging_90_days >= 0 THEN ai.aging_90_days ELSE 0 END) aging_90_days,
                    SUM(CASE WHEN ai.aging_older >= 0 THEN ai.aging_older ELSE 0 END) aging_older,
                    (SUM(CASE WHEN ai.aging_not_overdue >= 0 THEN ai.aging_not_overdue ELSE 0 END) + 
                        SUM(CASE WHEN ai.aging_30_days >= 0 THEN ai.aging_30_days ELSE 0 END) + 
                        SUM(CASE WHEN ai.aging_60_days >= 0 THEN ai.aging_60_days ELSE 0 END) + 
                        SUM(CASE WHEN ai.aging_90_days >= 0 THEN ai.aging_90_days ELSE 0 END) + 
                        SUM(CASE WHEN ai.aging_older >= 0 THEN ai.aging_older ELSE 0 END))  aging_outstanding,
                    SUM(ai.total_discount) total_discount,
                    SUM(ai.total_receipt) total_receipt,
                    --CATATAN: Aging yang MINUS akui sebagai unreconcile payment 
                    (ABS(SUM(CASE WHEN ai.aging_not_overdue < 0 THEN ai.aging_not_overdue ELSE 0 END) + 
                        SUM(CASE WHEN ai.aging_30_days < 0 THEN ai.aging_30_days ELSE 0 END) + 
                        SUM(CASE WHEN ai.aging_60_days < 0 THEN ai.aging_60_days ELSE 0 END) + 
                        SUM(CASE WHEN ai.aging_90_days < 0 THEN ai.aging_90_days ELSE 0 END) + 
                        SUM(CASE WHEN ai.aging_older < 0 THEN ai.aging_older ELSE 0 END)) ) total_unreconcile,
                    SUM(ai.total_outstanding) total_outstanding,
                    COALESCE(round(cast(max(ai.average_ar) as numeric),2), 0) average_ar,
                    COALESCE(round(cast(max(ai.average_revenue) as numeric),2), 0) average_revenue,
                    COALESCE(round(cast(max(ai.average_days) as numeric),2), 0) average_days,
                    COALESCE(round(cast(max(ai.average_revenue)/NULLif(max(ai.average_ar),0) as numeric),2), 0) ratio_turnover,
                    COALESCE(round(cast(max(ai.average_days)/NULLif(max(ai.average_revenue),0)/NULLif(max(ai.average_ar),0) as numeric),2), 0) ratio_days
                FROM (
                    SELECT (CASE WHEN pr.customer_type_wipro IS NULL THEN 2 ELSE 1 END) sno,
                        COALESCE(pr.customer_type_wipro,'[NONE]') payer_type,
                        SUM(aging.total_unbilled) total_unbilled,
                        SUM(aging.total_invoice) total_invoice,
                        SUM(CASE WHEN aging.due_day <= 0 THEN aging.total_outstanding ELSE 0 END) aging_not_overdue,
                        SUM(CASE WHEN aging.due_day > 0 AND aging.due_day <= 30 THEN aging.total_outstanding ELSE 0 END) aging_30_days,
                        SUM(CASE WHEN aging.due_day > 30 AND aging.due_day <= 60 THEN aging.total_outstanding ELSE 0 END) aging_60_days,
                        SUM(CASE WHEN aging.due_day > 60 AND aging.due_day <= 90 THEN aging.total_outstanding ELSE 0 END) aging_90_days,
                        SUM(CASE WHEN aging.due_day > 90 THEN aging.total_outstanding ELSE 0 END) aging_older,
                        SUM(aging.total_discount) total_discount,
                        SUM(aging.total_receipt) total_receipt,
                        SUM(aging.total_unreconcile) total_unreconcile,
                        SUM(aging.total_outstanding) total_outstanding,
                        SUM(aging.total_outstanding)/4 average_ar,
                        SUM(aging.total_revenue)/4 average_revenue,
                        (EXTRACT(day FROM TO_TIMESTAMP('{end_date}','YYYY-MM-DD')-(DATE('{end_date}') - interval '4 month'))/4) average_days
                    FROM (
                        --QUERY GL--
                        SELECT DISTINCT
                            'GL' tbl_name,
                            a.partner_id payer_id,
                            EXTRACT(day FROM TO_TIMESTAMP('{end_date}','YYYY-MM-DD')-a.date_maturity) AS due_day,
                            0 total_revenue,
                            0 total_unbilled,
                            SUM(a.debit) total_invoice,
                            SUM(CASE WHEN a.creditnote_id IS NOT NULL THEN a.credit ELSE 0 END) total_discount,
                            SUM(CASE WHEN a.payment_id IS NOT NULL or a.realization_id is not null THEN a.credit ELSE 0 END) total_receipt,
                            SUM(CASE WHEN a.payment_id is null and a.realization_id is null and a.creditnote_id is null THEN a.credit ELSE 0 END) total_unreconcile,
                            SUM(a.debit-a.credit) total_outstanding     
                            FROM account_move_line a
                        INNER JOIN account_move b ON b.id = a.move_id
                        WHERE b.state IN ('posted')
                            AND a.year_close IS NOT TRUE 
                            AND a.account_id IN (SELECT id FROM account_account WHERE code LIKE '11040102%')
                            AND a."date" <= '{end_date}'
                            AND a.company_id = {company_id}
                            AND a.partner_id = COALESCE({partner_id}, a.partner_id)
                            {partner_ids}
                        GROUP BY a.partner_id, a.date_maturity  

                        UNION ALL 
                        
                        SELECT 
                             'UNBILL' tbl_name,
                             a.partner_id as payer_id,
                             0 total_revenue,
                             0 due_day,
                             sum(a.debit-a.credit) total_unbilled,
                             0 total_invoice,
                             0 total_discount,
                             0 total_receipt,
                             0 total_unreconcile,
                             0 total_outstanding  
                        FROM account_move_line a
                        INNER JOIN account_move b on b.id = a.move_id
                        WHERE b.state in('posted')
                             and a.year_close is not True 
                             and a.account_id in(select id from account_account where code = '1104060100')
                             and a."date" <= '{end_date}'
                             and a.company_id = {company_id}
                             and coalesce(a.partner_id, b.partner_id) =  coalesce({partner_id}, a.partner_id, b.partner_id)
                             {partner_ids}
                        GROUP BY a.partner_id                          
                        
                        UNION ALL
                                                                    
                        --GET REVENUE
                        SELECT 
                            'SL' tbl_name,
                            coalesce(c.payer_id, b.payer_id, a.payer) payer_id,
                            0 AS due_day,
                            sum(a.price_total) total_revenue,
                            0 total_unbilled,
                            0 total_invoice,
                            0 total_discount,
                            0 total_receipt,
                            0 total_unreconcile,
                            0 total_outstanding
                        FROM sale_order_line a 
                        INNER JOIN sale_order b ON b.id = a.order_id 
                        LEFT JOIN sale_order_bill c ON c.id = a.billing_id
                        WHERE a.tglproses >= (DATE('{end_date}') - interval '4 month')
                            AND a.tglproses <= '{end_date}'
                            AND a.company_id = {company_id}
                            AND coalesce(c.payer_id, b.payer_id, a.payer) = coalesce({partner_id}, c.payer_id, b.payer_id, a.payer)
                            AND a.is_takeout IS NOT True --for integrasi Odoo X Dhealth
                            {payer_ids}
                        GROUP BY coalesce(c.payer_id, b.payer_id, a.payer)
                                            
                    ) aging
                    LEFT JOIN res_partner pr ON pr.id = aging.payer_id
                    GROUP BY COALESCE(pr.customer_type_wipro,'[NONE]'), sno 
                ) ai
                GROUP BY sno, payer_type
                HAVING SUM(ai.total_outstanding) <> 0
                ORDER BY sno ASC, payer_type ASC
        """.format(end_date=date_end, date_min=date_min, 
            partner_id=(str(partner_id) if partner_id else "null"),
            partner_ids=("and a.partner_id in " + str(tuple(partner_ids)) if partner_ids else "" ),
            payer_ids=("and a.payer in " + str(tuple(partner_ids)) if partner_ids else "" ),
            company_id=record.company_id.id)

        open('/opt/odoo16/logs/aging.log','a+').write('\n' + str(query1))
        query = sudo.env.cr.execute(query1)
        # open('/opt/odoo16/logs/aging.log', 'a+').write('\n' + "done query1")
        lines = sudo.env.cr.dictfetchall()

        query2 = """
            SELECT sum(a.balance*-1) ar_allowance_da            
            FROM account_move_line a
            INNER JOIN account_move b on b.id = a.move_id
            WHERE b.state in('posted')
                and a.year_close is not True 
                and a.payment_id is null 
                and b.covering_id is null 
                and b.advance_id is null 
                and b.creditnote_id is null 
                and a.account_id in(select id from account_account where code = '1105990000')
                and a."date" <= '{end_date}'
                and a.company_id = {company_id}
                {partner_ids}
            """.format(
                end_date=date_end, 
                partner_ids=("and a.partner_id in " + str(tuple(partner_ids)) if partner_ids else "" ),
                company_id=record.company_id.id)

        query = sudo.env.cr.execute(query2)
        allowance_da = sudo.env.cr.dictfetchall()
        for d in allowance_da:
            data['allowance_da'] += d['ar_allowance_da'] or 0

        for payer in lines:
            obj = {}
            obj['payer_type'] = payer['payer_type']
            obj['unbilled'] = payer['total_unbilled'] or 0
            obj['invoice'] = payer['total_invoice'] or 0
            obj['not_overdue'] = payer['aging_not_overdue'] or 0
            obj['aging_30_days'] = payer['aging_30_days'] or 0
            obj['aging_60_days'] = payer['aging_60_days'] or 0
            obj['aging_90_days'] = payer['aging_90_days'] or 0
            obj['older'] = payer['aging_older'] or 0
            obj['outstanding'] = payer['aging_outstanding'] or 0
            obj['discount'] = payer['total_discount'] or 0
            obj['receipt'] = payer['total_receipt'] or 0
            obj['reconcil'] = payer['total_receipt'] or 0
            obj['unreconcile'] = payer['total_unreconcile'] or 0
            obj['ar_outstanding'] = payer['total_outstanding'] or 0
            obj['avg_ar'] = payer['average_ar'] or 0
            obj['avg_revenue'] = payer['average_revenue'] or 0
            obj['avg_days'] = payer['average_days'] or 0
            obj['ratio_turnover'] = payer['ratio_turnover'] or 0
            obj['ratio_days'] = payer['ratio_days'] or 0

            data['total_unbilled'] += obj['unbilled']
            data['total_invoice'] += obj['invoice']
            data['total_not_overdue'] += obj['not_overdue']
            data['total_30_days'] += obj['aging_30_days']
            data['total_60_days'] += obj['aging_60_days']
            data['total_90_days'] += obj['aging_90_days']
            data['total_older'] += obj['older']
            data['total_outstanding'] += obj['outstanding']
            data['total_unreconcile'] += obj['unreconcile']
            data['total_discount'] += obj['discount']
            data['total_receipt'] += obj['receipt']
            data['total_ar_outstanding'] = obj['ar_outstanding']
            data['total_avg_ar'] = obj['avg_ar']
            data['total_avg_revenue'] = obj['avg_revenue']
            data['total_ratio_turnover'] = obj['ratio_turnover']
            data['total_ratio_days'] = obj['ratio_days']

            data['data_ids'] += [obj]
        
        data = datas.convert(data)
        data = datas.json(data, cdata=False)

        open('/opt/odoo16/logs/belajar.log','a+').write('\n' + str(data))

        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper

