    #Outstanding Admission (Accrual)
    @http.route('/accounting/report_accrual_revenue', type='http', auth="user")
    @route()
    def report_accrual_revenue(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['account.receivable.report.compiled.wizard'].browse(id)
        data = {}

        ext = record.format_print_id
        partner_id = record.partner_id.id

        # Validate To One Payer Select
        partner_ids = record.partner_ids.ids
        if partner_ids:
            partner_ids.append(0)

        date_min = (record.company_id.cutoff_ar_aging).strftime('%Y-%m-%d')
        date_end = (record.date_end).strftime('%Y-%m-%d')

        data['company_name'] = record.company_id.name
        data['customer'] = sudo.env['res.partner'].search([('id', '=', partner_id),('customer_wipro', '=', True)]).name
        data['cuttoff_date'] = date_min
        data['date_end'] = date_end
        data['total_accrual'] = 0
        data['data_ids'] = []

        query1 = """
        select distinct 
            so.id order_id, 
            so."name" admission_no,
            date(so.date_order) admit_date,
            so.admission_type,
            coalesce(so.ref_admission_no,'') ref_admission_no,
            coalesce(so.parent_admission_no,'') parent_admission_no,
            (CASE so.patient_type 
                WHEN '1' THEN 'OP'
                WHEN '2' THEN 'IP'
                WHEN '3' THEN 'Emergency'
                ELSE 'OP'
            END) patient_type,
            py.vendor_code payer_code,
            coalesce(py."name",'PRIVATE') payer_name,
            coalesce(py.customer_type_wipro,'PRIVATE') payer_type,
            coalesce(pr.registration_code,'') patient_mrid,
            pr."name" patient_name,
            date(pr.date_of_birth) patient_dob,
            sum(sol.price_subtotal) accrual_amount 
        from sale_order_line sol 
        inner join sale_order so ON so.id=sol.order_id
        left join res_partner py ON py.id=so.payer_id
        left join res_partner pr ON pr.id=so.partner_id
        where sol.company_id = {company_id}
            and sol.tglproses >= '{date_min}'
            and sol.tglproses <= '{end_date}' 
            and date(so.date_order) <= '{end_date}' --pasien admit sblm date_end 
            -- and date(coalesce(so.confirmation_date, sol.bill_date, CURRENT_DATE)) > '{end_date}' --date_end >> baru dibilling setelah end_dte
            and so.patient_type in('2','3') --rawat inap hardcode
            and sol.type_line in('ACCRUAL','ACCRUAL REVERSAL') --hardcode filter hanya accrual 
            and sol.is_takeout is not True 
            and so.payer_id = coalesce({partner_id}, so.payer_id)
            {partner_ids}
        group by 
            so.id, so."name",
            date(so.date_order),
            so.admission_type,
            so.ref_admission_no,
            so.parent_admission_no,
            (CASE so.patient_type 
                WHEN '1' THEN 'OP'
                WHEN '2' THEN 'IP'
                WHEN '3' THEN 'Emergency'
                ELSE 'OP'
            END), py.vendor_code,
            coalesce(py."name",'PRIVATE'),
            coalesce(py.customer_type_wipro,'PRIVATE'),
            pr.registration_code,
            pr."name", date(pr.date_of_birth) 
        having sum(sol.price_subtotal) <> 0
        """.format(date_min=date_min, end_date=date_end, 
        partner_id=(str(partner_id) if partner_id else "null"), 
        partner_ids=("and so.payer_id in " + str(tuple(partner_ids)) if partner_ids else "" ),
        company_id=record.company_id.id)
        
        open('/opt/odoo16/logs/belajar.log','a+').write('\n' + str(query1))

        query = sudo.env.cr.execute(query1)
        lines = sudo.env.cr.dictfetchall()

        for accrual in lines:
            obj = {}
            obj['order_id'] = accrual['order_id']
            obj['admission_no'] = accrual['admission_no']
            obj['admit_date'] = accrual['admit_date'].strftime('%Y-%m-%d')
            obj['admission_type'] = accrual['admission_type']
            obj['ref_admission_no'] = accrual['ref_admission_no']
            obj['parent_admission_no'] = accrual['parent_admission_no']
            obj['patient_type'] = accrual['patient_type']
            obj['payer_code'] = accrual['payer_code']
            obj['payer_name'] = accrual['payer_name']
            obj['payer_type'] = accrual['payer_type']
            obj['patient_mrid'] = accrual['patient_mrid']
            obj['patient_name'] = accrual['patient_name']
            obj['patient_dob'] = accrual['patient_dob'].strftime('%Y-%m-%d')
            obj['accrual_amount'] = accrual['accrual_amount'] or 0
            data['total_accrual'] += obj['accrual_amount']
            data['data_ids'] += [obj]
        
        open('/opt/odoo16/logs/belajar.log','a+').write('\n' + str(data))
        data = datas.convert(data)
        open('/opt/odoo16/logs/belajar.log','a+').write('\n' + str(data))
        data = datas.json(data, cdata=False)

        import requests
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        execution = requests.post('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions',
            auth=(uname, password),
            json={
                'reportUnitUri':
                '/Mayapada16/Accounting/AR_Outstanding_Accrual',
                'outputFormat': ext,
                'parameters': {
                    'reportParameter': [{
                        'name': 'data',
                        'value': [data]
                    }]
                }
            })
            
        from lxml import etree
        xml = etree.XML(execution.content)
        request_id = xml.find('.//requestId').text
        export_id = xml.find('.//export//id').text
        result = requests.get('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions/' +request_id + '/exports/' + export_id + '/outputResource',cookies=execution.cookies)
        url = "http://10.2.1.120:8080/jasperserver/services/repository?wsdl"
        
        if str(ext) == 'xls':
            filename = "AR Outstanding Admission (Accrual).xls"
            return request.make_response(result.content,[('Content-Type', result.headers['content-type']),('Content-Disposition', content_disposition(filename))])
        elif str(ext) == 'pdf':
            filename = "AR Outstanding Admission (Accrual).pdf"
            return request.make_response(result.content,[('Content-Type', result.headers['content-type']),('Content-Disposition', content_disposition(filename))])


