            obj['listrik'] = tenant['listrik'] or 0
            obj['charge'] = tenant['charge'] or 0
            obj['air'] = tenant['air'] or 0
            obj['sewa'] = tenant['sewa'] or 0
            obj['ppn'] = tenant['ppn'] or 0
            obj['pph'] = tenant['pph'] or 0
            obj['current'] = tenant['current'] or 0
            obj['age_30_days'] = tenant['age_30_days'] or 0
            obj['age_60_days'] = tenant['age_60_days'] or 0
            obj['age_90_days'] = tenant['age_90_days'] or 0
            obj['older'] = tenant['older'] or 0
            data['total_listrik'] += obj['listrik']
            data['total_charge'] += obj['charge']
            data['total_air'] += obj['air']
            data['total_sewa'] += obj['sewa']
            data['total_ppn'] += obj['ppn']
            data['total_pph'] += obj['pph']
            data['total_current'] += obj['current']
