    def _get_ar_compiled_wizard(self, wizard_id, report_type):
        try:
            wizard_id = int(wizard_id)
        except (TypeError, ValueError):
            raise UserError('Invalid AR Report Compiled request.')
        record = request.env['account.receivable.report.compiled.wizard'].browse(wizard_id).exists()
        if not record or record.type_report != report_type:
            raise UserError('The AR Report Compiled request is no longer available.')
        if record.format_print_id != 'xls':
            raise UserError('This report is available in Excel format only.')
        if not record.date_start or not record.date_end:
            raise UserError('Date Start and Date End are required.')
        if record.date_start > record.date_end:
            raise UserError('Date Start cannot be after Date End.')
        if record.company_id not in request.env.user.company_ids:
            raise UserError('You do not have access to the selected company.')
        return record


    def _build_invoice_tenant_new_xlsx(self, record):
        domain = [
            ('company_id', '=', record.company_id.id),
            ('invoice_type', '=', 'OUT_INVOICE'),
            ('state', '=', 'done'),
            ('invoice_date', '>=', record.date_start),
            ('invoice_date', '<=', record.date_end),
        ]
        if record.partner_id:
            domain.append(('customer_id', '=', record.partner_id.id))
        if record.partner_ids:
            domain.append(('customer_id', 'in', record.partner_ids.ids))
        invoices = record.env['receivable.invoice'].with_company(record.company_id).search(
            domain, order='invoice_date, invoice_no, id'
        )

        import io
        import xlsxwriter

        output = io.BytesIO()
        workbook = xlsxwriter.Workbook(output, {
            'constant_memory': True,
            'in_memory': True,
            'strings_to_numbers': False,
            'strings_to_formulas': True,
            'strings_to_urls': True,
            'default_date_format': 'yyyy-mm-dd',
        })
        workbook.set_properties({
            'title': 'Tenant Invoice Report (New)',
            'comments': 'Created with Odoo and XlsxWriter',
        })
        worksheet = workbook.add_worksheet('Invoice Tenant')
        format_title = workbook.add_format()
        format_title.set_font_size(20)
        format_title.set_bold()

        format_header = workbook.add_format()
        format_header.set_bold()
        format_header.set_bg_color('yellow')
        format_header.set_border(1)
        format_header.set_align('center')

        format_content = workbook.add_format()
        format_content.set_bottom(1)

        format_currency = workbook.add_format()
        format_currency.set_num_format('#,##0.00_);(#,##0.00);"-"')
        format_currency.set_align('right')
        format_currency.set_bottom(1)

        format_date = workbook.add_format()
        format_date.set_num_format('yyyy-mm-dd')
        format_date.set_align('left')
        format_date.set_bottom(1)

        format_footer = workbook.add_format()
        format_footer.set_bold()
        format_footer.set_bg_color('orange')
        format_footer.set_bottom(1)
        format_footer.set_align('right')
        format_footer.set_num_format('#,##0.00_);(#,##0.00);"-"')

        worksheet.write(0, 0, 'Tenant Invoice Report (New)', format_title)
        worksheet.write(1, 0, 'Company: ' + record.company_id.name)
        worksheet.write(2, 0, 'Period: %s until %s' % (record.date_start, record.date_end))
        headers = [
            'Customer Code', 'Customer Name', 'Invoice No', 'Invoice Ref',
            'Invoice Date', 'Invoice DueDate', 'Invoice Amt.', 'Tax Type',
            'Tax Amt.', 'Invoice Net Amt.', 'Total Refund', 'Total Receipt',
            'Invoice Balance',
        ]
        for column, header in enumerate(headers):
            worksheet.write(4, column, header, format_header)

        row = 5
        for invoice in invoices:
            customer = invoice.customer_id
            worksheet.write(row, 0, customer.vendor_code or '', format_content)
            worksheet.write(row, 1, customer.name or '', format_content)
            worksheet.write(row, 2, invoice.invoice_no or '', format_content)
            worksheet.write_string(row, 3, invoice.invoice_ref or '', format_content)
            worksheet.write(row, 4, invoice.invoice_date, format_date)
            worksheet.write(row, 5, invoice.invoice_duedate, format_date)
            worksheet.write_number(row, 6, invoice.invoice_amount or 0.0, format_currency)
            worksheet.write(row, 7, invoice.invoice_tax_type or '', format_content)
            worksheet.write_number(row, 8, invoice.invoice_tax_amount or 0.0, format_currency)
            worksheet.write_number(row, 9, invoice.invoice_amount_net or 0.0, format_currency)
            worksheet.write_number(row, 10, invoice.invoice_refund or 0.0, format_currency)
            worksheet.write_number(row, 11, invoice.invoice_receipt or 0.0, format_currency)
            worksheet.write_number(row, 12, invoice.invoice_balance or 0.0, format_currency)
            row += 1

        for column in range(0, 6):
            worksheet.write(row, column, 'TOTAL' if column == 5 else '', format_footer)
        total_columns = (6, 8, 9, 10, 11, 12)
        worksheet.write(row, 7, '', format_footer)
        for column in total_columns:
            if row > 5:
                excel_column = chr(ord('A') + column)
                worksheet.write_formula(
                    row, column, '=SUM(%s6:%s%s)' % (excel_column, excel_column, row),
                    format_footer,
                )
            else:
                worksheet.write_formula(row, column, '=0', format_footer, 0.0)

        worksheet.set_column(0, 0, 16)
        worksheet.set_column(1, 1, 40)
        worksheet.set_column(2, 3, 20)
        worksheet.set_column(4, 5, 15)
        worksheet.set_column(6, 6, 18)
        worksheet.set_column(7, 7, 15)
        worksheet.set_column(8, 12, 18)
        worksheet.set_zoom(80)
        workbook.close()
        output.seek(0)
        content = output.read()
        output.close()
        return content


    # tenant report - TC
    @http.route('/accounting/report_invoice_tenant_new', type='http', auth="user")
    @route()
    def report_invoice_tenant_new(self, id, **kw):
        record = self._get_ar_compiled_wizard(id, 'tenant_new')
        response = request.make_response(None, headers=[
            ('Content-Type', 'application/vnd.ms-excel'),
            ('Content-Disposition', content_disposition('Invoice Tenant New.xlsx')),
        ])
        response.stream.write(self._build_invoice_tenant_new_xlsx(record))
        return response


