    @http.route('/accounting/vendor_bill_report_noprc',type='http',auth="user")
    @route()
    def VendorbillnoPRCReport(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['account.payable.report.compiled.wizard'].browse(id)
        data = {}
        ext = record.format_print_id

        data['company_id'] = record.company_id.name
        data['date_start'] = (record.date_start).strftime('%Y-%m-%d')
        data['date_end'] = (record.date_end).strftime('%Y-%m-%d')
        data['total_vendorbill'] = 0
        data['data_ids'] = []

        quer2 = """
            SELECT 
                b.name->>'en_US' as account_id,
                C.vendor_code,
                C.NAME AS vendor_name,
                A.date_invoice,
                A.origin,
                A.NUMBER AS vendor_bill,
                CASE 
                    WHEN a.type = 'in_invoice' THEN 'Vendor Bill'
                    WHEN a.type = 'out_invoice' THEN 'Customer Invoice'
                    WHEN a.type = 'in_refund' THEN 'Vendor Refund'
                    WHEN a.type = 'out_refund' THEN 'Customer Refund'
                    ELSE 'Unknown'
                END AS invoice_type,
                SUM (A.amount_total_signed) AS vendor_bill_amount 
            FROM account_invoice A 
            LEFT JOIN res_partner C ON C.ID = A.PARTNER_ID 
            LEFT JOIN account_account b on b.id = a.account_id
            WHERE a.company_id = {company_id}
                AND a.date_invoice >= '{date_start}'
                AND a.date_invoice <= '{date_end}' 
                and a.state in ('open','paid')
                and a.amount_total >= 1 
                and C.id = coalesce({partner_id}, C.id)
            GROUP BY C.vendor_code, C.NAME,b.name,
                A.number, A.date_invoice,A.origin,A.NUMBER,
                a.type
            order by a.number, a.date_invoice, c.vendor_code        
        """.format(
            company_id=record.company_id.id, 
            partner_id =(str(record.partner_id.id) if record.partner_id else "null"),
            date_start=record.date_start, date_end=record.date_end)
        query = sudo.env.cr.execute(quer2)
        vb_line = sudo.env.cr.dictfetchall()

        for line in vb_line:
            obj = {}
            obj['vendor_code'] = line['vendor_code'] or ' '
            obj['date_vb'] = (line['date_invoice']).strftime('%Y-%m-%d') or ' '
            obj['origin'] = line['origin'] or ' '
            obj['vendor_name'] = line['vendor_name'] or ' '
            obj['account'] = line['account_id']
            obj['vendor_bill'] = line['vendor_bill'] or ' '

            obj['vendor_bill_amount'] = line['vendor_bill_amount'] or 0
            data['total_vendorbill'] += obj['vendor_bill_amount']
            data['data_ids'] += [obj]

        # data = datas.convert(data)
        data = datas.json(data, cdata=False)

        open('/opt/odoo16/logs/belajar.log','a+').write('\n' + str(data))

        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper

        import requests
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        filepath = '/Mayapada/Accounting/vendor_bill_noprc_report'

        execution = requests.post('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions',
            auth=(uname, password),
            json={
                'reportUnitUri': str(filepath),
                'outputFormat': str(ext),
                'parameters': {
                    'reportParameter': [{
                        'name': 'data',
                        'value': [data]
                    }]
                }
            })
    
        from lxml import etree
        xml = etree.XML(execution.content)
        request_id = xml.find('.//requestId').text
        export_id = xml.find('.//export//id').text
        result = requests.get('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions/' +request_id + '/exports/' + export_id + '/outputResource',cookies=execution.cookies)
        url = "http://10.2.1.120:8080/jasperserver/services/repository?wsdl"
        
        if str(ext) == 'xls':
            filename = "Vendor Bill report.xls"
            return request.make_response(result.content,[('Content-Type', result.headers['content-type']),('Content-Disposition', content_disposition(filename))])
        elif str(ext) == 'pdf':
            filename = "Vendor Bill report.pdf"
            return request.make_response(result.content,[('Content-Type', result.headers['content-type']),('Content-Disposition', content_disposition(filename))])



