        post = sudo.env['account.dimension.wizard'].browse(id)

        def enumerate_month_dates(start_date, end_date):
            current = start_date
            while current <= end_date:
                if current.month >= 12:
                    next = datetime.date(current.year + 1, 1, 1)
                else:
                    next = datetime.date(current.year, current.month + 1, 1)
                last = min(next - timedelta(1), end_date)
                yield current.strftime('%Y-%m-%d'), last.strftime('%Y-%m-%d')
                current = next

        # account_ids = sudo.env['account.financial.report'].browse(post.type_id.id)
        result = {'start': 'Januari ' + post.year,'end': 'Desember ' + post.year,'account_report_id': post.type_id.name}
