    # 2022.10.31 - M. Firgiawan Khafidli
    # Export List Billing of Covering Letter
    @http.route('/report/covering_letter_billing', type='http', auth="user")
    @route()
    def PrintCoveringLetterBilling(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        ext = str(format)
        record = sudo.env['account.coveringletter'].browse(id)

        import io
        import xlsxwriter

        output = io.BytesIO()
        response = request.make_response(None, headers=[
            ('Content-Type', 'application/vnd.ms-excel'),
            ('Content-Disposition', content_disposition('List Billing of ' + str(record.name) + '.xlsx'))
        ])

        workbook = xlsxwriter.Workbook(output, {
            'constant_memory': True, 
            'in_memory': True, 
            'strings_to_numbers':False, 
            'strings_to_formulas':True, 
            'strings_to_urls':True, 
            'default_date_format':'yyyy-mm-dd'})

        workbook.set_properties({
            'title': 'List Billing of ' + str(record.name),
            'comments': 'Created with Odoo and XlsxWriter'
        })
        worksheet = workbook.add_worksheet()

        format_title = workbook.add_format()
        format_title.set_font_size(20)
        # format_title.set_font_color('blue')
        format_title.set_bold()

        format_header = workbook.add_format()
        format_header.set_bold()
        format_header.set_bg_color('yellow')
        format_header.set_border(1)
        format_header.set_align('center')

        format_content = workbook.add_format()
        format_content.set_bottom(1)

        format_currency = workbook.add_format()
        format_currency.set_num_format('#,##0.00')
        format_currency.set_align('right')
        format_currency.set_bottom(1)

        format_date = workbook.add_format()
        format_date.set_num_format('yyyy-mm-dd')
        format_date.set_align('left')
        format_date.set_bottom(1)

        format_datetime = workbook.add_format()
        format_datetime.set_num_format('yyyy-mm-dd hh:mm')
        format_datetime.set_align('left')
        format_datetime.set_bottom(1)

        format_footer = workbook.add_format()
        format_footer.set_bold()
        format_footer.set_bg_color('orange')
        format_footer.set_bottom(1)
        format_footer.set_align('right')
        format_footer.set_num_format('#,##0.00')

        # worksheet.set_column(0, 40, 20)
        # worksheet.set_column(7, 7, 50) # patient_name
        # worksheet.set_column(10, 10, 50) # payer_name

        # create header
        worksheet.write(0, 0, 'List Billing of Covering Letter', format_title)
        worksheet.write(1, 0, 'Company: ' + str(record.company_id.name))
        worksheet.write(2, 0, 'Letter No: ' + str(record.name))

        # create header
        worksheet.write(4, 0, 'SL No.', format_header)
        worksheet.write(4, 1, 'Letter No.', format_header)
        worksheet.write(4, 2, 'Letter Date', format_header)
        worksheet.write(4, 3, 'Payer Code', format_header)
        worksheet.write(4, 4, 'Payer Name', format_header)
        worksheet.write(4, 5, 'Admission No.', format_header)
        worksheet.write(4, 6, 'Admit Date', format_header)
        worksheet.write(4, 7, 'Patient Type', format_header)
        worksheet.write(4, 8, 'Bill No.', format_header)
        worksheet.write(4, 9, 'Bill Date', format_header)
        worksheet.write(4, 10, 'Patient UHID', format_header)
        worksheet.write(4, 11, 'Patient Name', format_header)
        worksheet.write(4, 12, 'Bill Amount', format_header)
        worksheet.write(4, 13, 'Payer Amount', format_header)
        worksheet.write(4, 14, 'Payer Invoiced', format_header)
            
        query = """
            select 
                (case when a.state='draft' then a.draft_no else a.name end) letter_no,
                a.date letter_date, 
                rp.vendor_code payer_code,
                rp.name payer_name, 
                so.name admission_no,
                date(so.date_order) admission_date,
                (case bl.patient_type
                    when '1' then 'OP'
                    when '2' then 'IP'
                    when '3' then 'Emergency'
                    when '4' then 'DayCare'
                    when '5' then 'MCU/Pharmacy Issue (FO)'
                    when '6' then 'Pharmacy (Direct)'
                    else 'Both'
                end) patient_type,
                bl.billno bill_no,
                date(bl.bill_date) bill_date,
                pt.registration_code patient_mrid,
                pt.name patient_name,
                bl.total_amount,
                bl.payer_amount,
                bl.payer_credit
            from account_coveringletter a 
            inner join res_partner rp on rp.id = a.payer
            inner join account_coveringletter_bill_rel rel on rel.account_coveringletter_id = a.id 
            inner join sale_order_bill bl on bl.id = rel.sale_order_bill_id
            inner join sale_order so on so.id = bl.admission_id
            inner join res_partner pt on pt.id = bl.partner_id
            where a.id = {letter_id}
        """.format(letter_id=record.id)
        open('/opt/odoo16/logs/covering_letter.log','a+').write('\n' + str(query))
        sudo.env.cr.execute(query)
        results = sudo.env.cr.dictfetchall()

        # looping data 
        row = 5
        sno = 1
        if results:
            for line in results:
                worksheet.write(row, 0, sno, format_content)
                worksheet.write(row, 1, line['letter_no'], format_content)
                worksheet.write(row, 2, line['letter_date'], format_date)
                worksheet.write(row, 3, line['payer_code'], format_content)
                worksheet.write(row, 4, line['payer_name'], format_content)
                worksheet.write(row, 5, line['admission_no'], format_content)
                worksheet.write(row, 6, line['admission_date'], format_date)
                worksheet.write(row, 7, line['patient_type'], format_content)
                worksheet.write(row, 8, line['bill_no'], format_content)
                worksheet.write(row, 9, line['bill_date'], format_date)
                worksheet.write(row, 10, line['patient_mrid'], format_content)
                worksheet.write(row, 11, line['patient_name'], format_content)
                worksheet.write(row, 12, line['total_amount'], format_currency)
                worksheet.write(row, 13, line['payer_amount'], format_currency)
                worksheet.write(row, 14, line['payer_credit'], format_currency)
                   
                row += 1
                sno += 1

            worksheet.write(row, 0, '', format_footer)
            worksheet.write(row, 1, 'TOTAL', format_footer)
            worksheet.write(row, 2, '', format_footer)
            worksheet.write(row, 3, '', format_footer)
            worksheet.write(row, 4, '', format_footer)
            worksheet.write(row, 5, '', format_footer)
            worksheet.write(row, 6, '', format_footer)
            worksheet.write(row, 7, '', format_footer)
            worksheet.write(row, 8, '', format_footer)
            worksheet.write(row, 9, '', format_footer)
            worksheet.write(row, 10, '', format_footer)
            worksheet.write(row, 11, '', format_footer)
            worksheet.write(row, 12, '=SUM(M6:M'+str(row)+')', format_footer)
            worksheet.write(row, 13, '=SUM(N6:N'+str(row)+')', format_footer)
            worksheet.write(row, 14, '=SUM(O6:O'+str(row)+')', format_footer)


        # setup column
        worksheet.set_column(0, 0, 10) # sno
        worksheet.set_column(1, 3, 15) # group_name
        worksheet.set_column(4, 4, 40) # group_name
        worksheet.set_column(5, 10, 15) # group_name
        worksheet.set_column(11, 11, 40) # group_name
        worksheet.set_column(12, 14, 15) # group_name


        worksheet.set_zoom(80)
        workbook.close()
        output.seek(0)
        response.stream.write(output.read())
        output.close()
        del output # clear 
        return response

        
    # Print Out Covering Letter Kwitansi
    @http.route('/report/covering_letter_kwitansi', type='http', auth="user")
    @route()
    def PrintCoveringLetterKwitansi(self, id, format, **kw):
        id = int(id)
