        data['cl_name'] = record.letter_id.draft_no if record.letter_id.state == 'draft' else record.name 
        data['cl_payer'] = record.address_id.name if record.address_id else record.payer.name 
        data['cl_date'] = tools.datetime.now().strftime('%d %B %Y')
        data['cl_amount'] = ("{:,.0f}".format(int(record.total_covering_letter) or 0)).replace(",",".") + ",-"
        data['cl_terbilang'] = AmtWord.number_to_words(int(record.total_covering_letter)) + " rupiahs"
        data['cl_pic'] = record.company_id.cl_ttd
        data['cl_remark1'] = record.remark1 or '.'
        data['cl_remark2'] = record.remark2 or '.'
        data['cl_remark3'] = record.remark3 or '.'

        data = datas.convert(data)
        data = datas.json(data, cdata=False)
        

        open('/opt/odoo16/logs/belajar.log', 'a+').write('\n' + str(data))

        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper

        import requests
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        execution = requests.post('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions',
            auth=(uname, password),
            json={
                'reportUnitUri': '/Mayapada16/Accounting/Print_Covering_Letter_Kwitansi',
                'outputFormat': 'html',
                'parameters': {
                    'reportParameter': [{
                        'name': 'data',
                        'value': [data]
                    }]
                }
            })
    
        from lxml import etree
        xml = etree.XML(execution.content)
        request_id = xml.find('.//requestId').text
        export_id = xml.find('.//export//id').text
        result = requests.get('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions/' +request_id + '/exports/' + export_id + '/outputResource',cookies=execution.cookies)

