    @http.route('/report/covering_letter_tanda_terima', type='http', auth="user")
    @route()
    def PrintCoveringLetterTandaTerima(self, id, format, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        ext = str(format)
        # get data filter wizard
        record = sudo.env['account.coveringletter'].browse(id)
        ext = str(format)

        data = {}
        # due_date = dict(sudo.env['account.coveringletter']._fields['due_day'].selection)
        # for key,value in due_date.iteritems():
        data['due_date'] = (record.due_date).strftime('%Y-%m-%d')
        data['letter_no'] = record.draft_no if record.state == 'draft' else record.name
        data['payer_name'] = record.address_id.name if record.address_id else record.payer.name
        data['letter_amount'] = record.total_covering_letter
        data['company_address'] = record.company_id.street
        data['company_city'] = record.company_id.city
        data['currency'] = record.company_id.currency_id.symbol
        
        AmtWord = inflect.engine()
        terbilang = AmtWord.number_to_words(int(record.total_covering_letter)) + " rupiahs"
        letter_terbilang = terbilang.replace(',','')
        letter_terbilang = letter_terbilang.replace(' and', '')
        data['letter_terbilang'] = letter_terbilang

        # data['letter_terbilang'] = AmtWord.number_to_words(int(record.total_covering_letter)) + " rupiah"
        # filepath = '/Mayapada/Accounting/Covering_Letter_Cover_New1'
        filepath = '/Mayapada16/Accounting/Covering_Letter_Cover_Tanda_Terima'

        data = datas.convert(data)
        data = datas.json(data, cdata=False)
        open('/opt/odoo16/logs/belajar.log', 'a+').write('\n' + str(data))
        
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper

        import requests
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        format_ = 'pdf' if str(ext) == 'pdf' else 'html'
        execution = requests.post('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions',
            auth=(uname, password),
            json={
                'reportUnitUri': str(filepath),
                'outputFormat': str(format_),
                'parameters': {
                    'reportParameter': [{
                        'name': 'data',
                        'value': [data]
                    }]
                }
            })
    
        from lxml import etree
        xml = etree.XML(execution.content)
        request_id = xml.find('.//requestId').text
        export_id = xml.find('.//export//id').text
        result = requests.get('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions/' +request_id + '/exports/' + export_id + '/outputResource',cookies=execution.cookies)
        
        filename = record.name + ".pdf"
        return request.make_response(result.content,[('Content-Type', result.headers['content-type']),('Content-Disposition', content_disposition(filename))])


        


