    @http.route('/report/credit_note', type='http', auth="user")
    @route()
    def PrintCreditNote(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        # get data filter wizard
        record = sudo.env['account.creditnote'].browse(id)
        # user = request.env.user.name
        # data = record.read()[0]
        data = {}
        # due_date = dict(sudo.env['account.coveringletter']._fields['due_day'].selection)
        # for key,value in due_date.iteritems():
        data['customer_name'] = record.payer_id.name
        data['coveringletter'] = record.letter_id.name
        # data['invoice_month'] = record.date
        data['total_bill_amount'] = 0
        data['total_patient_amount'] = 0
        data['total_amount_discount'] = 0
        data['total_discount_amount'] = 0
        data['total_payer_amount'] = 0
        data['line_ids'] = []
        for ol in record.creditnote_line_ids:
            obj = {}
            if ol.billing_id:
                obj['patient_name'] = ol.billing_id.partner_id.name
                obj['bill_no'] = ol.billing_id.billno
                obj['category'] = ol.category_id.name
                obj['bill_amount'] = ol.total_billing
                obj['patient_amount'] = ol.takeout_amount
                obj['amount_discount'] = ol.total_billing - ol.takeout_amount
                obj['discount_amount'] = ol.amount_discount
                obj['payer_amount'] = ol.total_discount
                obj['discount_persen'] = ol.discount_percent
                obj['invoice_month'] = (record.date).strftime('%Y-%m-%d')
            elif ol.billing_sale_id:
                obj['patient_name'] = ol.billing_sale_id.partner_id.name
                obj['bill_no'] = ol.billing_sale_id.billno
                obj['category'] = ol.category_id.name
                obj['bill_amount'] = ol.billing_amount
                obj['patient_amount'] = ol.takeout_amount
                obj['amount_discount'] = ol.billing_amount - ol.takeout_amount
                obj['discount_amount'] = ol.amount_discount
                obj['payer_amount'] = ol.total_discount
                obj['discount_persen'] = ol.discount_percent
                obj['invoice_month'] = (record.date).strftime('%Y-%m-%d')

            # obj['remark'] = ol.remark
            obj['remark'] = ol.remark
            data['line_ids'] += [obj]
            data['total_bill_amount'] += obj['bill_amount']
            data['total_patient_amount'] += obj['patient_amount']
            data['total_amount_discount'] += obj['amount_discount']
            data['total_discount_amount'] += obj['discount_amount']
            data['total_payer_amount'] += obj['payer_amount']

        data = datas.convert(data)
