    #bikinan eca
    #export Efaktur
    @http.route('/report/export_efaktur', type='http', auth="user")
    @route()
    def export_efaktur(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['account.efaktur.export.wizard'].browse(id)
        data = record.read()[0]
        data['company_id'] = request.env.company.name
        # data['year'] = record.tahun_pajak
        # data['month'] = record.masa_pajak

        data['data_ids'] = []
        if len(record.efaktur_ids) > 1:
            efaktur_ids = tuple(record.efaktur_ids.ids)
            query = sudo.env.cr.execute("""
                SELECT
                    "kdJenisTransaksi",
                    "fgPengganti",
                    "nomorFaktur",
                    "tanggalFaktur",
                    "npwpPenjual",
                    "namaPenjual",
                    "alamatPenjual",
                    "jumlahDpp",
                    "jumlahPpn",
                    "jumlahPpnBm",
                    dikredit 
                FROM account_efaktur_scan
                WHERE id in {} 
                """.format(efaktur_ids))
            lines = sudo.env.cr.dictfetchall()
        else:
            efaktur_ids = record.efaktur_ids.id
            query = sudo.env.cr.execute("""
                SELECT
                    "kdJenisTransaksi",
                    "fgPengganti",
                    "nomorFaktur",
                    "tanggalFaktur",
                    "npwpPenjual",
                    "namaPenjual",
                    "alamatPenjual",
                    "jumlahDpp",
                    "jumlahPpn",
                    "jumlahPpnBm",
                    dikredit 
                FROM account_efaktur_scan
                WHERE id = {}
                """.format(efaktur_ids))
            lines = sudo.env.cr.dictfetchall()
        for line in lines:
            obj = {}
            obj['kdjenistransaksi'] = line['kdJenisTransaksi']
            obj['fgpengganti'] = line['fgPengganti']
            obj['nomorFaktur'] = line['nomorFaktur']
            obj['masa_pajak'] = record.masa_pajak
            obj['year'] = record.tahun_pajak
            obj['tanggalfaktur'] = tools.datetime.strptime(line['tanggalFaktur'], '%Y-%m-%d').strftime('%d/%m/%Y')
            obj['npwp'] = line['npwpPenjual']
            obj['nama'] = line['namaPenjual']
            obj['alamat'] = line['alamatPenjual']
            obj['jumlahdpp'] = line['jumlahDpp']
            obj['jumlahppn'] = line['jumlahPpn']
            obj['jumlahppnbm'] = line['jumlahPpnBm'] or 0
            if line['dikredit'] == False:
                obj['dikredit'] = 0
            else:
                obj['dikredit'] = 1

            data['data_ids'] += [obj]

        data = datas.convert(data)
        data = datas.json(data)

        url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper

        jasper = JasperClient()
        jasper.login(url, uname, password)
        report = jasper.run('/Mayapada/Accounting/efaktur_report', 'CSV',{'data': data})
        filename = "export_efaktur.csv"
        return request.make_response(report[1]["data"],[('Content-Type', report[1]["content-type"]),('Content-Disposition', content_disposition(filename))])

    # Print Referral Fee
    @http.route('/referral_fee/print_referral_fee', type='http', auth="user")
    @route()
    def PrintOutReferralFee(self, format, id, **kw):
        id = int(id)
        ext = str(format)
        sudo = request.env.user.sudo()
        
        records = sudo.env['referral.fee'].search([('id','=', str(id))], limit=1)

        kd_finance_pos = None
        if records.company_id.company_code == 'MHJS':
            kd_finance_pos = 156
        elif records.company_id.company_code == 'MHTG':
            kd_finance_pos = 445
        elif records.company_id.company_code == 'MHSB':
            kd_finance_pos = 1335
        elif records.company_id.company_code == 'MHKN':
            kd_finance_pos = 13
        elif records.company_id.company_code == 'MHBG':
            kd_finance_pos = 0
        
        staff_pos = None
        if records.company_id.company_code == 'MHJS':
            staff_pos = 444
        elif records.company_id.company_code == 'MHTG':
            staff_pos = 1047
        elif records.company_id.company_code == 'MHSB':
            staff_pos = 0
        elif records.company_id.company_code == 'MHKN':
            staff_pos = 27
        elif records.company_id.company_code == 'MHBG':
            staff_pos = 0

        city = sudo.env['res.company'].search([('id','=', records.company_id.id)], limit=1)
        staff = sudo.env['res.users'].search([('company_id','=', records.company_id.id), ('position_id', '=', staff_pos)], limit=1)
        kd_finance = sudo.env['res.users'].search([('company_id','=', records.company_id.id), ('position_id', '=', kd_finance_pos)], limit=1)

        data = {}
        ref_fee = sudo.env['referral.fee'].search([('id', '=', str(id))], limit=1)

        month_period = str(ref_fee.month)
        if month_period == '1':
            month_dt = "January"
        elif month_period == '2':
            month_dt = "February"
        elif month_period == '3':
            month_dt = "March"
        elif month_period == '4':
            month_dt = "April"
        elif month_period == '5':
            month_dt = "May"
        elif month_period == '6':
            month_dt = "June"
        elif month_period == '7':
            month_dt = "July"
        elif month_period == '8':
            month_dt = "August"
        elif month_period == '9':
            month_dt = "September"
        elif month_period == '10':
            month_dt = "October"
        elif month_period == '11':
            month_dt = "November"
