            #         AND fline.patient_type = '{patient_type}'
            # """.format(doctor_fee_id=record.id, patient_type=value))
            
            query = sudo.env.cr.execute("""
                SELECT SUM(a.total) AS patient_type_total, SUM(a.total_new) AS patient_type_total_new, SUM(a.rate) AS patient_type_total_fee 
                    FROM (
                        SELECT CASE WHEN COALESCE(fline.rate_percent, 0) < 50 THEN 
                            -- COALESCE(fline.rate, 0.00000) 
                            CASE WHEN fline.is_pot_gp = True THEN fline.rate_pot
                            WHEN fline.is_p12 = True THEN fline.rate_p12
                            WHEN fline.is_igd = True THEN fline.rate_igd
                            WHEN fline.is_pengirim = True THEN fline.rate_pengirim
                            WHEN fline.is_tnc = True THEN fline.rate_tnc
                            WHEN fline.is_hd = True THEN fline.rate_hd 
                            else COALESCE(fline.rate, 0.00000) END
                            WHEN COALESCE(fline.rate_percent, 0) >= 50 THEN COALESCE(fline.total, 0.00000) END total_new,
                            COALESCE(fline.total, 0.00000) as total,
                            -- COALESCE(fline.rate, 0.00000) as rate
                            CASE WHEN fline.is_pot_gp = True THEN fline.rate_pot
                                WHEN fline.is_p12 = True THEN fline.rate_p12
                                WHEN fline.is_igd = True THEN fline.rate_igd
                                WHEN fline.is_pengirim = True THEN fline.rate_pengirim
                                WHEN fline.is_tnc = True THEN fline.rate_tnc
                                WHEN fline.is_hd = True THEN fline.rate_hd 
                                else COALESCE(fline.rate, 0.00000) END rate
                        FROM doctor_fee_line as fline
                        WHERE fline.doctor_fee_id = '{doctor_fee_id}'
                            AND fline.patient_type = '{patient_type}'
                            AND fline.is_bpjs is not True
                    ) AS a
            """.format(doctor_fee_id=record.id, patient_type=value))
            sum_pt_query = sudo.env.cr.dictfetchall()

            for s in sum_pt_query:
                patient_type_total = s['patient_type_total'] or 0
                patient_type_total_new = s['patient_type_total_new'] or 0
                patient_type_total_fee = s['patient_type_total_fee'] or 0
                obj['patient_type'] = patient_types[value]
                obj['pt_total_net_amount'] = float(patient_type_total)
                obj['pt_total_net_amount_int'] = int(patient_type_total)
