    # 2022.02.18 - Profitability Report
    # Firgiawan Khafidli
    @http.route('/accounting/print_profitability', type='http', auth="user")
    @route()
    def print_profitability(self, id, **kw):
        from datetime import datetime
        
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['profitability.analysis.wizard'].browse(id)
        data = record.read()[0]

        report_name = "Profitability Analysis Report"
        company_id = record.company_id.id 
        company_name = record.company_id.name
        start_date = datetime.strptime(str(record.start_date), '%Y-%m-%d').strftime("%Y-%m-%d")
        end_date = datetime.strptime(str(record.end_date), '%Y-%m-%d').strftime("%Y-%m-%d")
        data_type = record.data_type 
        data_type_name = dict(sudo.env['profitability.analysis.wizard']._fields['data_type'].selection).get(record.data_type)

        data['revenue'] = 0
        data['service_cost'] = 0
        data['material_cost'] = 0
        data['scrap_direct'] = 0
        data['scrap_indirect'] = 0
        data['scrap_other'] = 0
        data['scrap_gl'] = 0
        data['other_cost'] = 0
        data['cost_total'] = 0
        data['margin_total'] = 0
        data['margin_percent'] = 0.0
        data['data_ids'] = []
        
        query_1 = """
            SELECT 
                coalesce(t2.code,'[NONE]') group_code,
                coalesce(t2.name->>'en_US','[NONE]') group_name,
                sum(coalesce(t.price_total,0)) revenue,
                sum(coalesce(t.service_cost,0)) service_cost,
                sum(coalesce(t.material_cost,0)) material_cost,
                sum(case when t.type_data='SCRAP-DIRECT' then coalesce(t.scrap_cost,0) else 0 end) scrap_direct,
                sum(case when t.type_data='SCRAP-INDIRECT' then coalesce(t.scrap_cost,0) else 0 end) scrap_indirect,
                sum(case when t.type_data='SCRAP-COST' then coalesce(t.scrap_cost,0) else 0 end) scrap_other,
                sum(case when t.type_data='GL' then coalesce(t.scrap_cost,0) else 0 end) scrap_gl,
                sum(coalesce(t.other_cost,0)) other_cost,
                sum(t.cost_total) cost_total,
                sum(t.margin_total) margin_total,
                (sum(t.margin_total) / (case when sum(t.price_total) <> 0 then sum(t.price_total) else null end) * 1.00) margin_percent,

                sum(coalesce(t.throughput,0)) throughput_total,
                sum(case when upper(t.patient_group) in ('INPATIENT','IPD') then coalesce(t.throughput,0) else 0 end) throughput_ipd,
                sum(case when upper(t.patient_group) in ('OUTPATIENT','OPD') then coalesce(t.throughput,0) else 0 end) throughput_opd,
                sum(case when upper(t.patient_group) in ('EMERGENCY','IGD') then coalesce(t.throughput,0) else 0 end) throughput_ema,
                sum(case when upper(t.patient_group) in ('MCU') then coalesce(t.throughput,0) else 0 end) throughput_mcu,
            
                (sum(coalesce(t.price_total,0)) / (case when sum(coalesce(t.throughput,0)) <> sum(coalesce(t.throughput,0)) then sum(coalesce(t.throughput,0)) else null end)) patient_spending_revenue,
                (sum(coalesce(t.cost_total,0))/(case when sum(coalesce(t.throughput,0)) <> sum(coalesce(t.throughput,0)) then sum(coalesce(t.throughput,0)) else null end)) patient_spending_cost,
                ((sum(coalesce(t.price_total,0))/(case when sum(coalesce(t.throughput,0)) <> sum(coalesce(t.throughput,0)) then sum(coalesce(t.throughput,0)) else null end)) 
                - (sum(coalesce(t.cost_total,0))/(case when sum(coalesce(t.throughput,0)) <> sum(coalesce(t.throughput,0)) then sum(coalesce(t.throughput,0)) else null end))
                ) patient_spending_margin
            FROM profitability_analysis t 
            LEFT JOIN account_analytic_account t2 ON t2.id = t.{data_type}
            WHERE t.company_id = {company_id}
                AND t.tglproses >= '{start_date}'
                AND t.tglproses <= '{end_date}' 
            GROUP BY coalesce(t2.name->>'en_US','[NONE]'), coalesce(t2.code,'[NONE]')
            ORDER BY coalesce(t2.code,'[NONE]')
            """.format(
                company_id = company_id,
                start_date = start_date, 
                end_date = end_date,
                data_type = data_type 
            )

        # open('/opt/odoo16/logs/log_profitability_print.log','a+').write('\n' + str(query_1).encode('utf-8'))
        sudo.env.cr.execute(query_1)
        results_1 = sudo.env.cr.dictfetchall()

