    @http.route('/accounting/print_patient_spending', type='http', auth="user")
    @route()
    def print_patient_spending(self, id, **kw):
        from datetime import datetime
        
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['profitability.patient.spending.wizard'].browse(id)
        data = record.read()[0]

        report_name = "Patient Spending Report"
        company_id = record.company_id.id 
        company_name = record.company_id.name
        start_date = str(datetime.strptime(record.start_date, '%Y-%m-%d').strftime("%Y-%m-%d"))
        end_date = str(datetime.strptime(record.end_date, '%Y-%m-%d').strftime("%Y-%m-%d"))
        data_type = record.data_type 
        data_type_name = dict(sudo.env['profitability.patient.spending.wizard']._fields['data_type'].selection).get(record.data_type)

        data['revenue_ipd'] = 0
        data['revenue_opd'] = 0
        data['revenue_ema'] = 0
        data['revenue_mcu'] = 0
        data['revenue_total'] = 0

        data['throughput_ipd'] = 0
        data['throughput_opd'] = 0
        data['throughput_ema'] = 0
        data['throughput_mcu'] = 0
        data['throughput_total'] = 0
        data['data_ids'] = []
        
        query_1 = """
            SELECT 
                (case when coalesce(t2.code,'[NONE]') = '[NONE]' then 2 else 1 end) sno, 
                coalesce(t2.code,'[NONE]') group_code,
                coalesce(t2.name,'[NONE]') group_name,
                
                sum(case when upper(t.patient_group) in ('INPATIENT','IPD') then coalesce(t.price_total,0) else 0 end) revenue_ipd,
                sum(case when upper(t.patient_group) in ('OUTPATIENT','OPD') then coalesce(t.price_total,0) else 0 end) revenue_opd,
                sum(case when upper(t.patient_group) in ('EMERGENCY','IGD') then coalesce(t.price_total,0) else 0 end) revenue_ema,
                sum(case when upper(t.patient_group) in ('MCU') then coalesce(t.price_total,0) else 0 end) revenue_mcu,
                sum(coalesce(t.price_total,0)) revenue_total,
                
                sum(case when upper(t.patient_group) in ('INPATIENT','IPD') then coalesce(t.throughput,0) else 0 end) throughput_ipd,
                sum(case when upper(t.patient_group) in ('OUTPATIENT','OPD') then coalesce(t.throughput,0) else 0 end) throughput_opd,
                sum(case when upper(t.patient_group) in ('EMERGENCY','IGD') then coalesce(t.throughput,0) else 0 end) throughput_ema,
                sum(case when upper(t.patient_group) in ('MCU') then coalesce(t.throughput,0) else 0 end) throughput_mcu,
                sum(coalesce(t.throughput,0)) throughput_total
                        
            FROM profitability_analysis t 
            LEFT JOIN account_analytic_account t2 ON t2.id = t.{data_type}
            WHERE t.company_id = {company_id}
                AND t.tglproses >= '{start_date}'
                AND t.tglproses <= '{end_date}' 
            GROUP BY coalesce(t2.name,'[NONE]'), coalesce(t2.code,'[NONE]')
            ORDER BY sno, group_code
            """.format(
                company_id = company_id,
                start_date = start_date, 
                end_date = end_date,
                data_type = data_type )

        open('/opt/odoo16/logs/log_profitability_spending_print.log','a+').write('\n' + str(query_1).encode('utf-8'))
        sudo.env.cr.execute(query_1)
        results_1 = sudo.env.cr.dictfetchall()

