    @http.route('/accounting/print_vat_difference', type='http', auth="user")
    @route()
    def print_vat_difference(self, id, **kw):
        from datetime import datetime
        
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['vat.difference.report.wizard'].browse(id)
        data = record.read()[0]

        report_name = "VAT Difference Report"
        company_id = record.company_id.id 
        company_name = record.company_id.name
        date_start = str(datetime.strptime(record.date_start, '%Y-%m-%d').strftime("%Y-%m-%d"))
        date_end = str(datetime.strptime(record.date_end, '%Y-%m-%d').strftime("%Y-%m-%d"))
        type_report = record.type_report 
        type_report_name = dict(sudo.env['vat.difference.report.wizard']._fields['type_report'].selection).get(record.type_report)

        data['receipt_vs_purchase_diff'] = 0
        data['invoice_vs_purchase_diff'] = 0
        data['data_ids'] = []
        
        query_1 = """
            select 
                date(po.date_order) purchase_date,
                po."name" purchase_no,
                rp.vendor_code supplier_code,
                rp."name" supplier_name, 
                pt.default_code item_code, 
                pt."name" item_name, 
                pol."name" item_description,
                pu."name" item_uom,
                pol.product_qty item_qty,
                pol.price_unit item_price,
                pol.discount_persen item_disc_percent,
                round((coalesce(pol.discount_persen,0) / 100 * pol.price_unit), 2) item_disc_amount,
                tx.item_tax, 
                coalesce(tx.item_tax_percent,0.0) item_tax_percent,
                round(((pol.price_unit - round((coalesce(pol.discount_persen,0) / 100 * pol.price_unit), 2)) * 
                    coalesce(tx.item_tax_percent,0.0) / 100.0),2) item_tax_amount, 
                round((pol.price_unit - round((coalesce(pol.discount_persen,0) / 100 * pol.price_unit), 2) + 
                 ((pol.price_unit - round((coalesce(pol.discount_persen,0) / 100 * pol.price_unit), 2)) * 
                    coalesce(tx.item_tax_percent,0.0) / 100.0)
                ), 2) item_price_nett,

                prc.picking_date receipt_date,
                prc.picking_no receipt_no,
                prc.picking_by receipt_by,
                prc.product_qty receipt_qty,
                prc.price_unit receipt_price_nett,
                ((prc.product_qty * prc.price_unit) - (prc.product_qty * 
                    round((pol.price_unit - round((coalesce(pol.discount_persen,0) / 100 * pol.price_unit), 2) + 
                     ((pol.price_unit - round((coalesce(pol.discount_persen,0) / 100 * pol.price_unit), 2)) * 
                        coalesce(tx.item_tax_percent,0.0) / 100.0)
                    ), 2)
                )) receipt_vs_purchase_diff,
                inv.*,
                ((inv.invoice_qty * inv.invoice_price_nett) - (inv.invoice_qty * 
                round((pol.price_unit - round((coalesce(pol.discount_persen,0) / 100 * pol.price_unit), 2) + 
                 ((pol.price_unit - round((coalesce(pol.discount_persen,0) / 100 * pol.price_unit), 2)) * 
                    coalesce(tx.item_tax_percent,0.0) / 100.0)
                ), 2))) invoice_vs_purchase_diff 
                            
            from purchase_order po 
            inner join purchase_order_line pol on pol.order_id = po.id 
            left join res_partner rp on rp.id = po.partner_id
            left join product_product pp on pp.id = pol.product_id 
            left join product_template pt on pt.id = pp.product_tmpl_id
            left join product_uom pu on pu.id = pol.product_uom
            left join lateral (
                select tx."name" item_tax, tx.amount item_tax_percent 
                from account_tax_purchase_order_line_rel rel
                inner join account_tax tx on tx.id = rel.account_tax_id 
                where rel.purchase_order_line_id = pol.id 
                    and tx.name ilike '%PPN%'
                limit 1
            ) tx on 1=1
            left join lateral (
                select sp."name" picking_no, 
                    sp.date_move picking_date, 
                    rpu."name" picking_by,
                    sm.* 
                from stock_move sm   
                inner join stock_picking sp on sp.id = sm.picking_id
                left join res_users ru on ru.id = sp.write_uid 
                left join res_partner rpu on rpu.id = ru.partner_id
                where sp."state" = 'done' 
                    and sm.purchase_line_id=pol."id"
            ) prc on 1=1
                
            left join lateral (
                select 
                    ai."date" invoice_date,
                    ai.name invoice_no, 
                    rpu."name" invoice_by, 
                    ail.quantity invoice_qty, 
                    ail.price_unit invoice_price,
                    ail.discount_persen invoice_disc_percent,
                    round((coalesce(ail.discount_persen,0) / 100 * ail.price_unit), 2) invoice_disc_amount,
                    txl.item_tax invoice_tax, 
                    coalesce(txl.item_tax_percent,0.0) invoice_tax_percent,
                    round(((ail.price_unit - round((coalesce(ail.discount_persen,0) / 100 * ail.price_unit), 2)) * 
                        coalesce(txl.item_tax_percent,0.0) / 100.0),2) invoice_tax_amount, 
                    round((ail.price_unit - round((coalesce(ail.discount_persen,0) / 100 * ail.price_unit), 2) + 
                     ((ail.price_unit - round((coalesce(ail.discount_persen,0) / 100 * ail.price_unit), 2)) * 
                        coalesce(txl.item_tax_percent,0.0) / 100.0)
                    ), 2) invoice_price_nett,
                    (case when ai.state = 'paid' then 'PAID' else 'OPEN' end) invoice_status
                from account_invoice_line ail 
                inner join account_invoice ai on ai.id = ail.invoice_id
                left join res_users ru on ru.id = ai.write_uid 
                left join res_partner rpu on rpu.id = ru.partner_id
                left join lateral (
                    select txl."name" item_tax, txl.amount item_tax_percent 
                    from account_invoice_line_tax rel
                    inner join account_tax txl on txl.id = rel.tax_id 
                    where rel.invoice_line_id = ail.id 
                        and txl.name ilike '%PPN%'
                    limit 1
                ) txl on 1=1
                where ail.purchase_line_id = pol.id 
                    and ai."state" in('open','paid')
            ) inv on 1=1

            where po.company_id = {company_id}
            and po."state" in('approved','purchase','done')
            and (
                (date(po.date_order) >= '{date_start}' and date(po.date_order) <= '{date_end}') or 
                (date(prc.picking_date) >= '{date_start}' and date(prc.picking_date) <= '{date_end}') or 
                (date(inv.invoice_date) >= '{date_start}' and date(inv.invoice_date) <= '{date_end}') 
            )
            and tx.item_tax <> inv.invoice_tax
            {filter_sync_id_api}
            -- and po.id = 293329
            -- order by pol.create_date desc limit 100 

            """.format(
                company_id = company_id,
                filter_sync_id_api = ("and (pol.sync_id_api is not null or pol.sync_id is not null)" if type_report == '2' else 'and (pol.sync_id_api is null and pol.sync_id is null)'),
                date_start = date_start, 
                date_end = date_end
            )

        open('/opt/odoo16/logs/log_vat_difference.log','a+').write('\n' + str(query_1).encode('utf-8'))
        sudo.env.cr.execute(query_1)
