try:
    import StringIO 
except ImportError:
    from io import StringIO 

import csv

# from odoo import http
# from odoo.http import request
from odoo.tools import ustr
from odoo.tools.misc import xlwt
import xlrd
from odoo.addons.web.controllers.pivot import TableExporter


class CsvExporter(TableExporter):
    @http.route('/web/pivot/check_xlwt', type='json', auth='none')
    def check_xlwt(self):
        return xlwt is not None

    @http.route('/web/pivot/export_xls', type='http', auth="user")
    def export_xls(self, data, token):
        company_check = request.env.company.name
        if company_check != 'Mayapada Hospital Bogor':
            jdata = loads(data)
            nbr_measures = jdata['nbr_measures']
            workbook = xlwt.Workbook()
            worksheet = workbook.add_sheet(jdata['title'])
            header_bold = xlwt.easyxf("font: bold on; pattern: pattern solid, fore_colour gray25;")
            header_plain = xlwt.easyxf("pattern: pattern solid, fore_colour gray25;")
            bold = xlwt.easyxf("font: bold on;")

            # Step 1: writing headers
            headers = jdata['headers']

            # x,y: current coordinates
            # carry: queue containing cell information when a cell has a >= 2 height
            #      and the drawing code needs to add empty cells below
            x, y, carry = 1, 0, deque()
            for i, header_row in enumerate(headers):
                worksheet.write(i, 0, '', header_plain)
                for header in header_row:
                    while (carry and carry[0]['x'] == x):
                        cell = carry.popleft()
                        for i in range(nbr_measures):
                            worksheet.write(y, x + i, '', header_plain)
                        if cell['height'] > 1:
                            carry.append({'x': x, 'height': cell['height'] - 1})
                        x = x + nbr_measures
                    style = header_plain if 'expanded' in header else header_bold
                    for i in range(header['width']):
                        worksheet.write(y, x + i, header['title'] if i == 0 else '', style)
                    if header['height'] > 1:
                        carry.append({'x': x, 'height': header['height'] - 1})
                    x = x + header['width']
                while (carry and carry[0]['x'] == x):
                    cell = carry.popleft()
                    for i in range(nbr_measures):
                        worksheet.write(y, x + i, '', header_plain)
                    if cell['height'] > 1:
                        carry.append({'x': x, 'height': cell['height'] - 1})
                    x = x + nbr_measures
                x, y = 1, y + 1

            # Step 2: measure row
            if nbr_measures > 1:
                worksheet.write(y, 0, '', header_plain)
                for measure in jdata['measure_row']:
                    style = header_bold if measure['is_bold'] else header_plain
                    worksheet.write(y, x, measure['measure'], style)
                    x = x + 1
                y = y + 1

            # Step 3: writing data
            x = 0
            for row in jdata['rows']:
                worksheet.write(y, x, row['indent'] * '     ' + ustr(row['title']),header_plain)
                for cell in row['values']:
                    x = x + 1
                    if cell.get('is_bold', False):
                        worksheet.write(y, x, cell['value'], bold)
                    else:
                        worksheet.write(y, x, cell['value'])
                x, y = 0, y + 1

            excel_file = StringIO.StringIO()
            workbook.save(excel_file)

            workbook = xlrd.open_workbook(file_contents=excel_file.getvalue())
            file = StringIO.StringIO()
            writer = csv.writer(file)
            sheet = workbook.sheet_by_index(0)
            header = []
            for index in range(sheet.nrows):
                #if not index: continue
                row = sheet.row_values(index)
                """if index < 3:
                   header += [row]#[','.join(map(str, row))]# + '\n'
                   continue"""
                row = map(lambda value: value.replace(',', '') if type(value) in [str, unicode] else value, row)
                writer.writerow([row[0].encode('utf-8')])

            file = file.getvalue().replace('     ', ',')
            max_comma = 0
            new_file = file.split('\n')
            value_count = -1
            """for line in new_file:
                start = False
                for index, value in enumerate(line.split(',')[::-1]):
                    if value and not start:
                       start = True
                    if start and not value:
                       value_count = index - 1
                       break
                break"""
            for line in new_file:
                comma_count = line.count(',')
                if comma_count > max_comma: max_comma = comma_count
            #new_file = header + new_file
            for index, line in enumerate(new_file):
                comma_count = line.count(',')
                #line = line.split(',')
                commas = ',' * (max_comma - comma_count)
                #line.insert(-value_count, commas)
                new_file[index] = line.replace('\r', '') + commas
                #new_file[index] = ','.join(line)#[1:])#max_comma - value_count] + line[-value_count:])
            """for index, line in enumerate(header):
                line.insert(1, ',' * (max_comma - value_count - 1))
                header[index] = ','.join(map(str, line))"""
            for index in range(sheet.nrows):
                #if not index: continue
                row = sheet.row_values(index)[1:]
                new_file[index] += ',' + ','.join(map(str, row))

            #response = request.make_response('\n'.join(header) + '\n' + '\n'.join(new_file),
            response = request.make_response('\n'.join(new_file),headers=[('Content-Type', 'text/csv'),('Content-Disposition', 'attachment; filename=table.csv;')],cookies={'fileToken': token})
            # response = request.make_response('\n'.join(new_file),headers=[('Content-Type', 'application/vnd.ms-excel'),('Content-Disposition', 'attachment; filename=table.xls;')],cookies={'fileToken': token})

            #workbook.save(response.stream)
            return response
        # else:
        #     jdata = loads(data)
        #     nbr_measures = jdata['nbr_measures']
        #     workbook = xlwt.Workbook()
        #     worksheet = workbook.add_sheet(jdata['title'])
        #     header_bold = xlwt.easyxf("font: bold on; pattern: pattern solid, fore_colour gray25;")
        #     header_plain = xlwt.easyxf("pattern: pattern solid, fore_colour gray25;")
        #     bold = xlwt.easyxf("font: bold on;")

        #     # Step 1: writing headers
        #     headers = jdata['headers']

