    @http.route('/accounting/receiving_bay_report', type='http', auth="user")
    @route()
    def receiving_bay_report(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['stock.receiving'].browse(id)
        
        data = {}
        data['company'] = record.company_id.name
        data['supplier'] = record.partner_id.name
        data['challan_no'] = record.picking_id.name
        data['po_no'] = record.purchase_id.name
        data['ref'] = record.ref
        data['purchase_date'] = (record.purchase_date).strftime('%Y-%m-%d')
        data['user'] = record.user_id.name
        data['receiving_no'] = record.name
        data['receiving_date'] = (record.date).strftime('%Y-%m-%d')
        data['notes_no'] = record.picking_id.name
        data['print_date'] = (datetime.now()).strftime('%Y-%m-%d %H:%M:%S')
        data['line_ids'] = []
        
        open('/opt/odoo16/logs/dump.log','a+').write('\n' + str(data))
        
        for line in record.line_ids:
            obj = {}
            obj['si_no'] = "-"
            obj['item'] = line.product_id.name
            obj['desc'] = line.name
            obj['qty'] = line.qty_received
            obj['unit'] = line.product_uom.name
            # obj['free_qty'] = line.qty_received
            # obj['unit2'] = line.product_uom.name
            obj['remark'] = "-"
            data['line_ids'] += [obj]
        
        data = datas.convert(data)
        data = datas.json(data, cdata=False)

        open('/opt/odoo16/logs/dump.log','a+').write('\n' + str(data))
        
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper

        import requests
        uname = request.env.company.uname_jasper
        password = request.env.company.pass_jasper
        execution = requests.post('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions',
            auth=(uname, password),
            json={
                'reportUnitUri': '/Mayapada/Purchase/Print_Receiving_Bay',
                'outputFormat': 'pdf',
                'parameters': {
                    'reportParameter': [{
                        'name': 'data',
                        'value': [data]
                    }]
                }
            })
    
        from lxml import etree
        xml = etree.XML(execution.content)
        request_id = xml.find('.//requestId').text
        export_id = xml.find('.//export//id').text
        result = requests.get('http://10.2.1.120:8080/jasperserver/rest_v2/reportExecutions/' +request_id + '/exports/' + export_id + '/outputResource',cookies=execution.cookies)
        
        filename = 'Receiving Bay.pdf'
        return request.make_response(result.content,[('Content-Type', result.headers['content-type']),('Content-Disposition', content_disposition(filename))])

        # url = request.env.company.url_host_jasper + "/services/repository?wsdl"
        # uname = request.env.company.uname_jasper
        # password = request.env.company.pass_jasper
        
        # jasper = JasperClient()
        # jasper.login(url, uname, password)
        # report = jasper.run('/Mayapada/Purchase/Print_Receiving_Bay','PDF', {'data': data})
        # filename = "Receiving Bay.pdf"

        # return request.make_response(report[1]["data"],[('Content-Type', report[1]["content-type"]),('Content-Disposition', content_disposition(filename))])
    
