    # Created By Dudi R
    @http.route('/accounting/asset_category_report', type='http', auth="user")
    @route()
    def asset_category_report(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['asset.report.wizard'].browse(id)
        data = record.read()[0]
        company_id = record.company_id.id
        start_date = record.start_date
        end_date = record.end_date
        report_name = "Asset Category"

        data['report_name'] = report_name
        data['start_date'] = record.start_date
        data['end_date'] = record.end_date
        data['company'] = record.company_id.name
        
        query = """
            select DISTINCT ac.name categ, 
                ac1.name parent_categ, 
                aj.name->>'en_US' journal,
                aa.name->>'en_US' asset_account,
                aa1.name->>'en_US' depreciation_account,
                aa2.name->>'en_US' depreciation_account_expanse,
                cc.name cost_center,
                an.name->>'en_US' analytic_account,
                an1.name->>'en_US' analytic_expanse
            from account_asset_category ac
                left join account_asset_category ac1 on ac.parent_id=ac1.id
                left join account_journal aj on ac.journal_id=aj.id
                left join account_account aa on ac.account_asset_id=aa.id
                left join account_account aa1 on ac.account_depreciation_id=aa1.id
                left join account_account aa2 on ac.account_depreciation_expense_id=aa2.id
                left join cost_center_master cc on ac.cost_master_id=cc.id
                left join account_analytic_account an on ac.account_analytic_id=an.id
                left join account_analytic_account an1 on ac.expense_analytic_id=an1.id
            where ac.company_id = {company_id}
            """.format(company_id=company_id, start_date=start_date, end_date=end_date)
        
        sudo.env.cr.execute(query)
        results = sudo.env.cr.dictfetchall()
        
        # open('/opt/odoo16/logs/dump.log','a+').write('\n' + str(results))
        
        import io
        import xlsxwriter

        output = io.BytesIO()
        response = request.make_response(None, headers=[
            ('Content-Type', 'application/vnd.ms-excel'),
            ('Content-Disposition', content_disposition(report_name + '.xlsx'))
        ])
        
        workbook = xlsxwriter.Workbook(output, {
            'constant_memory': True, 
            'in_memory': True, 
            'strings_to_numbers':False, 
            'strings_to_formulas':True, 
            'strings_to_urls':True, 
            'default_date_format':'yyyy-mm-dd'})

        workbook.set_properties({
            'title':    report_name,
            'comments': 'Created with Odoo and XlsxWriter'
        })
        worksheet = workbook.add_worksheet()

        format_title = workbook.add_format()
        format_title.set_font_size(20)
        # format_title.set_font_color('blue')
        format_title.set_bold()

        format_header = workbook.add_format()
        format_header.set_bold()
        format_header.set_bg_color('yellow')
        format_header.set_border(1)
        format_header.set_align('center')
    
        format_header_1 = workbook.add_format()
        format_header_1.set_bold()
        format_header_1.set_bg_color('#FFC000')
        format_header_1.set_border(1)
        format_header_1.set_align('center')
        format_header_1.set_align('vcenter')
        format_header_1.set_text_wrap()
    
        format_header_4 = workbook.add_format()
        format_header_4.set_bold()
        format_header_4.set_bg_color('#95B3D7')
        format_header_4.set_border(1)
        format_header_4.set_align('center')
        format_header_4.set_align('vcenter')
        format_header_4.set_text_wrap()

        format_content = workbook.add_format()
        format_content.set_bottom(1)
    
        format_content_1 = workbook.add_format()
        format_content_1.set_align('center')
        format_content_1.set_bottom(1)

        format_currency = workbook.add_format()
        format_currency.set_num_format('#,##0.00')
        format_currency.set_align('right')
        format_currency.set_bottom(1)

        format_date = workbook.add_format()
        format_date.set_num_format('yyyy-mm-dd')
        format_date.set_align('left')
        format_date.set_bottom(1)

        format_datetime = workbook.add_format()
        format_datetime.set_num_format('yyyy-mm-dd hh:mm')
        format_datetime.set_align('left')
        format_datetime.set_bottom(1)

        format_footer = workbook.add_format()
        format_footer.set_bold()
        format_footer.set_bg_color('gray')
        format_footer.set_bottom(1)
        format_footer.set_align('right')
        format_footer.set_num_format('#,##0.00')
        
        # setup column
        worksheet.set_column(0, 40, 20)

        # create header
        worksheet.write(0, 0, data['report_name'] + ' Report', format_title)
        worksheet.write(1, 0, 'Company: ' + data['company'])
        # worksheet.write(2, 0, 'Period: ' + data['start_date'] + ' s/d ' + data['end_date'])

        # create header
        worksheet.write('A6', 'No.', format_header)
        worksheet.write('B6', 'Asset Category', format_header)
        worksheet.write('C6', 'Parent Category', format_header)
        worksheet.write('D6', 'Journal', format_header)
        worksheet.write('E6', 'Asset Account', format_header)
        worksheet.write('F6', 'Depresiasi Account', format_header)
        worksheet.write('G6', 'Depresiasi Expense Account', format_header)
        worksheet.write('H6', 'Cost Center', format_header)
        worksheet.write('I6', 'Analytic Account', format_header)
        worksheet.write('J6', 'Analytic Expense', format_header)
        
        row = 6
        sno = 0
    
        # looping data 
        if results:
            for line in results:
                sno += 1
                worksheet.write(row, 0, sno, format_content_1)
                worksheet.write(row, 1, line['categ'], format_content)
                worksheet.write(row, 2, line['parent_categ'], format_content)
                worksheet.write(row, 3, line['journal'], format_content)
                worksheet.write(row, 4, line['asset_account'], format_content)
                worksheet.write(row, 5, line['depreciation_account'], format_content)
                worksheet.write(row, 6, line['depreciation_account_expanse'], format_currency)
                worksheet.write(row, 7, line['cost_center'], format_currency)
                worksheet.write(row, 8, line['analytic_account'], format_currency)
                worksheet.write(row, 9, line['analytic_expanse'], format_currency)
        
                row += 1

                
        # worksheet.write(row, 0, 'TOTAL', format_footer)
        # worksheet.write(row, 1, '', format_footer)
