    @http.route('/accounting/bank_receipt_settlement_detail', type='http', auth="user")
    @route()
    def bank_receipt_settlement_detail(self, id, **kw):
        id = int(id)
        sudo = request.env.user.sudo()
        record = sudo.env['account.receivable.report.compiled.wizard'].browse(id)
        data = {}
        ext = record.format_print_id
        partner_id = record.partner_id.id
        company_id = record.company_id.id

        # Validate To One Payer Select
        partner_ids = record.partner_ids.ids
        if partner_ids:
            partner_ids.append(0)
        bank_ids = record.bank_ids.ids
        if bank_ids:
            bank_ids.append(0)

        from datetime import datetime
        date_start = (record.date_start).strftime('%Y-%m-%d')
        date_end = (record.date_end).strftime('%Y-%m-%d')
        date_start_aging = (record.date_start - timedelta(days=1)).strftime('%Y-%m-%d')

        report_name = "Bank Receipt Settlement"
        
        data['company_id'] = record.company_id.name
        data['report_name'] = report_name 
        data['start_date'] = date_start
        data['end_date'] = date_end
        data['unreconciled'] = 0
        data['advance_no'] = 0 
        data['creditnote_no'] = 0
        data['receipt_no'] = 0
        data['covering_no_not_overdue'] = 0
        data['covering_no_30_days'] = 0
