        format_date.set_bottom(1)

        format_datetime = workbook.add_format()
        format_datetime.set_num_format('yyyy-mm-dd hh:mm')
        format_datetime.set_align('left')
        format_datetime.set_bottom(1)

        format_footer = workbook.add_format()
        format_footer.set_bold()
        format_footer.set_bg_color('orange')
        format_footer.set_bottom(1)
        format_footer.set_align('right')
        format_footer.set_num_format('#,##0.00')

        # create header
        worksheet.write(0, 0, report_type, format_title)
        worksheet.write(1, 0, 'Company: ' + record.company_id.name)
        worksheet.write(2, 0, 'Period: ' + date_start + ' until ' + date_end)

        # create header
        worksheet.write(4, 0, 'No', format_header)
        worksheet.write(4, 1, 'Store/Facility', format_header)
        worksheet.write(4, 2, 'Category', format_header)
        worksheet.write(4, 3, 'Full Category', format_header)
        worksheet.write(4, 4, 'Item Code', format_header)
        worksheet.write(4, 5, 'Item Name', format_header)
        worksheet.write(4, 6, 'Medical Type', format_header)
        worksheet.write(4, 7, 'BPJS', format_header)
        worksheet.write(4, 8, 'Consignment', format_header)
        worksheet.write(4, 9, 'UoM', format_header)
        worksheet.write(4, 10, 'Qty Initial', format_header)
        worksheet.write(4, 11, 'Qty In', format_header)
        worksheet.write(4, 12, 'Qty Out', format_header)
        worksheet.write(4, 13, 'Qty Ending', format_header)
        worksheet.write(4, 14, 'Cost Valuation', format_header)
        worksheet.write(4, 15, 'Cost Average', format_header)
        

        query = """
            select 
                a.department_name, 
                a.category_name,
                (case
                    when pc4."name" is not null then concat(pc4."name",'/',pc3."name",'/',pc2."name",'/',pc1."name")
                    when pc3."name" is not null then concat(pc3."name",'/',pc2."name",'/',pc1."name")
                    when pc2."name" is not null then concat(pc2."name",'/',pc1."name")
                    else pc1."name"
                end) category_full, 
                a.product_code, 
                a.product_name,
                (case when a.medical_type = '1' then 'Non Medic' else 'Medic' end) medical_type,
                (case when a.bpjs = '1' then 'BPJS' else 'Non BPJS' end) bpjs,
                (case when a.consignment = '1' then 'Consignment' else 'Non Consignment' end) consignment,
                a.uom_name,
                sum(case when a.trans_direction = '0' then a.product_qty else '0' end) qty_init,
                sum(case when a.trans_direction = '1' then a.product_qty else '0' end) qty_in,
                sum(case when a.trans_direction = '-1' then a.product_qty else '0' end) qty_out,
                sum(a.product_qty) qty_ending,
                sum(a.cost_total) cost_total, 
                a.cost_unit 
            from stock_ledger a 
            left join product_category pc1 on pc1."id" = a.odoo_category_id 
            left join product_category pc2 on pc2."id" = pc1.parent_id 
            left join product_category pc3 on pc3."id" = pc2.parent_id 
            left join product_category pc4 on pc4."id" = pc3.parent_id
            where a.tglproses >= '{date_start}'
                and a.tglproses <= '{date_end}'
                and a.company_id = {company_id}
                and a.consignment = coalesce('{consignment}', a.consignment)
                and a.medical_type = coalesce('{medical_type}', a.medical_type)
                and a.bpjs = coalesce('{bpjs}', a.bpjs)
            group by 
                a.department_name, 
                a.category_name,
                a.product_code, 
                a.product_name,
                a.uom_name,
                a.cost_unit,
                pc4."name", pc3."name", pc2."name", pc1."name",
                a.medical_type, a.bpjs, a.consignment    
        """.format(
            company_id = record.company_id.id,
            date_start = date_start,
            date_end = date_end,
            consignment = ("null" if record.consignment == '2' else record.consignment),
            medical_type = ("null" if record.medical_type == '2' else record.medical_type),
            bpjs = ("null" if record.bpjs == '2' else record.bpjs)
        )
        open('/opt/odoo16/logs/log_stock_ledger_report.log','a+').write('\n' + str(query))
        sudo.env.cr.execute(query)
        results = sudo.env.cr.dictfetchall()

        # looping data 
        row = 5
        sno = 1
        if results:
            for line in results:
                worksheet.write(row, 0, sno, format_content)
                worksheet.write(row, 1, line['department_name'], format_content)
                worksheet.write(row, 2, line['category_name'], format_content)
                worksheet.write(row, 3, line['category_full'], format_content)
                worksheet.write(row, 4, line['product_code'], format_content)
                worksheet.write(row, 5, line['product_name'], format_content)
                worksheet.write(row, 6, line['medical_type'], format_content)
                worksheet.write(row, 7, line['bpjs'], format_content)
                worksheet.write(row, 8, line['consignment'], format_content)
                worksheet.write(row, 9, line['uom_name'], format_content)
                worksheet.write(row, 10, line['qty_init'], format_currency)
                worksheet.write(row, 11, line['qty_in'], format_currency)
                worksheet.write(row, 12, line['qty_out'], format_currency)
                worksheet.write(row, 13, line['qty_ending'], format_currency)
                worksheet.write(row, 14, line['cost_total'], format_currency)
                worksheet.write(row, 15, line['cost_unit'], format_currency)
                   
                row += 1
                sno += 1


            worksheet.write(row, 0, 'TOTAL', format_footer)
            worksheet.write(row, 1, '', format_footer)
            worksheet.write(row, 2, '', format_footer)
            worksheet.write(row, 3, '', format_footer)
            worksheet.write(row, 4, '', format_footer)
            worksheet.write(row, 5, '', format_footer)
            worksheet.write(row, 6, '', format_footer)
            worksheet.write(row, 7, '', format_footer)
            worksheet.write(row, 8, '', format_footer)
            worksheet.write(row, 9, '', format_footer)
            worksheet.write(row, 10, '=SUM(K6:K'+str(row)+')', format_footer)
            worksheet.write(row, 11, '=SUM(L6:L'+str(row)+')', format_footer)
            worksheet.write(row, 12, '=SUM(M6:M'+str(row)+')', format_footer)
            worksheet.write(row, 13, '=SUM(N6:N'+str(row)+')', format_footer)
            worksheet.write(row, 14, '=SUM(O6:O'+str(row)+')', format_footer)
            worksheet.write(row, 15, '', format_footer)


            # setup column
            worksheet.set_column(0, 0, 5) # sno
            worksheet.set_column(1, 2, 20) # group_name
            worksheet.set_column(3, 3, 40) # group_name
            worksheet.set_column(4, 4, 20) # group_name
            worksheet.set_column(5, 5, 40) # group_name
            worksheet.set_column(6, 9, 15) # group_name
            worksheet.set_column(10, 15, 15) # group_name

        worksheet.set_zoom(80)
        workbook.close()
        output.seek(0)
        response.stream.write(output.read())
        output.close()
        del output # clear 
        return response

