        sno = 1
        if results:
            for line in results:
                worksheet.write(row, 0, sno, format_content)
                worksheet.write(row, 1, line['trans_date'], format_content)
                worksheet.write(row, 2, line['trans_no'], format_content)
                worksheet.write(row, 3, line['patient_mrid'], format_content)
                worksheet.write(row, 4, line['patient_name'], format_content)
                worksheet.write(row, 5, line['patient_type'], format_content)
                worksheet.write(row, 6, line['payment_type'], format_content)
                worksheet.write(row, 7, line['edc_machine'], format_content)
                worksheet.write(row, 8, line['bank_name'], format_content)
                worksheet.write(row, 9, line['bank_date'], format_content)
                worksheet.write(row, 10, line['deposit_collect'], format_currency)
                worksheet.write(row, 11, line['deposit_availed'], format_currency)
                worksheet.write(row, 12, line['deposit_refund'], format_currency)
                worksheet.write(row, 13, line['deposit_balance'], format_currency)
                worksheet.write(row, 14, line['user_name'], format_content)

                row += 1
                sno += 1

            # Menulis baris TOTAL
            worksheet.write(row, 0, 'TOTAL', format_footer)
            for col in range(1, 10):
                worksheet.write(row, col, '', format_footer)
            worksheet.write(row, 10, '=SUM(K6:K'+str(row)+')', format_footer)  # deposit_collect
            worksheet.write(row, 11, '=SUM(L6:L'+str(row)+')', format_footer)  # deposit_availed
            worksheet.write(row, 12, '=SUM(M6:M'+str(row)+')', format_footer)  # deposit_refund
            worksheet.write(row, 13, '=SUM(N6:N'+str(row)+')', format_footer)  # deposit_balance
            worksheet.write(row, 14, '', format_footer)

            # setup column
            worksheet.set_column(0, 0, 5)    # S.No.
            worksheet.set_column(1, 2, 18)   # trans_date, trans_no
            worksheet.set_column(3, 4, 20)   # patient_mrid, patient_name
            worksheet.set_column(5, 6, 15)   # patient_type, payment_type
            worksheet.set_column(7, 7, 18)   # edc_machine
            worksheet.set_column(8, 8, 20)   # bank_name
            worksheet.set_column(9, 9, 15)   # bank_date
            worksheet.set_column(10, 13, 18) # deposit_collect to deposit_balance
            worksheet.set_column(14, 14, 20) # user_name



        worksheet.set_zoom(80)
        workbook.close()
        output.seek(0)
        response.stream.write(output.read())
        output.close()
        del output # clear 
        return response



