        data = record.read()[0]

        company_id = record.company_id.id
        date_start = record.date_start
        date_end = record.date_end
        ext = record.format_print_id
        # Filter Category
        partner_ids = record.partner_ids.ids
        if partner_ids:
            partner_ids.append(0)
            
        data = {}
        data['data_ids'] = []
        data['company_name'] = record.company_id.name
        # month_period = str(record.month)
        # year_period = str(record.year)
        
        id = int(id)
        sudo = request.env.user.sudo()
       
        report_type = 'DATA AR - AGING PER PAYOR'
        report_name = 'Aging Per Payor'

        import io
        import xlsxwriter

        output = io.BytesIO()
        response = request.make_response(None, headers=[
            ('Content-Type', 'application/vnd.ms-excel'),
            ('Content-Disposition', content_disposition(report_name + '.xlsx'))
        ])
            
        workbook = xlsxwriter.Workbook(output, {
            'constant_memory': True, 
            'in_memory': True, 
            'strings_to_numbers':False, 
            'strings_to_formulas':True, 
            'strings_to_urls':True, 
            'default_date_format':'yyyy-mm-dd'})

        workbook.set_properties({
            'title': report_name,
            'comments': 'Created with Odoo and XlsxWriter'
        })
        worksheet = workbook.add_worksheet()

        format_title = workbook.add_format()
        format_title.set_font_size(20)
        # format_title.set_font_color('blue')
        format_title.set_bold()

        format_header = workbook.add_format()
        format_header.set_bold()
        format_header.set_bg_color('yellow')
        format_header.set_border(1)
        format_header.set_align('center')

        format_content = workbook.add_format()
        format_content.set_bottom(1)

        format_currency = workbook.add_format()
        format_currency.set_num_format('#,##0.00')
        format_currency.set_align('right')
        format_currency.set_bottom(1)

        format_date = workbook.add_format()
        format_date.set_num_format('yyyy-mm-dd')
        format_date.set_align('left')
        format_date.set_bottom(1)

        format_datetime = workbook.add_format()
        format_datetime.set_num_format('yyyy-mm-dd hh:mm')
        format_datetime.set_align('left')
        format_datetime.set_bottom(1)

        format_footer = workbook.add_format()
        format_footer.set_bold()
        format_footer.set_bg_color('orange')
        format_footer.set_bottom(1)
        format_footer.set_align('right')
        format_footer.set_num_format('#,##0.00')

        # create header
        worksheet.write(0, 0, report_type, format_title)
        worksheet.write(1, 0, 'Company: ' + record.company_id.name)
        # worksheet.write(2, 0, 'Period: ' + date_start.strftime + '  ' + date_end.strftime)

        # create header
        worksheet.write(4, 0, 'No.', format_header)
        worksheet.write(4, 1, 'Payor Code', format_header)
        worksheet.write(4, 2, 'Payor Name', format_header)
        worksheet.write(4, 3, 'Payor Type', format_header)
        worksheet.write(4, 4, 'TPA Code', format_header)
        worksheet.write(4, 5, 'TPA Name', format_header)
        worksheet.write(4, 6, 'Invoice Amount', format_header)
        worksheet.write(4, 7, 'Write-Off Amount', format_header)
        worksheet.write(4, 8, 'Receipt Amount', format_header)
        worksheet.write(4, 9, 'Balance Amount', format_header)
        worksheet.write(4, 10, 'Aging 0 Day', format_header)
        worksheet.write(4, 11, 'Aging 1_30 Days', format_header)
        worksheet.write(4, 12, 'Aging 31_60 Days', format_header)
        worksheet.write(4, 13, 'Aging 61_90 Days', format_header)
        worksheet.write(4, 14, 'Aging >90 Days', format_header)

        
        query = """select 
            a.payor_code,
            a.payor_name,
            a.payor_type,
            a.tpa_code,
            a.tpa_name,
            sum(coalesce(a.invoice_amount,0)) as invoice_amount,
            sum(coalesce(a.writeoff_amount,0)) as writeoff_amount,
            sum(coalesce(a.receipt_amount,0)) as receipt_amount, 
            sum(coalesce(a.balance_amount,0)) as balance_amount,
            sum(coalesce(a.aging_0,0)) as aging_0,
            sum(coalesce(a.aging_1_30,0)) as aging_1_30,
            sum(coalesce(a.aging_31_60,0)) as aging_31_60,
            sum(coalesce(a.aging_61_90,0)) as aging_61_90,
            sum(coalesce(a.aging_90,0)) as aging_90
        from (
            select 
                a.payor_code,
                a.payor_name,
                a.payor_type,
                a.tpa_code,
                a.tpa_name,
                a.invoice_no,
                a.invoice_date,
                a.invoice_sent,
                a.invoice_crediterm,
                a.invoice_maturity,
                a.admission_no,
                a.admission_date,
                a.aggreement_name, 
                a.patient_type,
                a.bill_type,
                a.bill_no,
                a.bill_date,
                a.patient_mrid,
                a.patient_name,
                a.payor_invoice as invoice_amount,
                coalesce(wo.writeoff_amount,0) as writeoff_amount,
                coalesce(rp.receipt_amount,0) as receipt_amount, 
                (a.payor_invoice - coalesce(wo.writeoff_amount,0) - coalesce(rp.receipt_amount,0)) balance_amount,
                (case when a.invoice_dueday < 0 then 0 else a.invoice_dueday end) as aging_dueday,
                (case when a.invoice_dueday <= 0 then (a.payor_invoice - coalesce(wo.writeoff_amount,0) - coalesce(rp.receipt_amount,0)) else 0 end) aging_0,
                (case when a.invoice_dueday >= 1 and a.invoice_dueday <= 30 then (a.payor_invoice - coalesce(wo.writeoff_amount,0) - coalesce(rp.receipt_amount,0)) else 0 end) aging_1_30,
                (case when a.invoice_dueday >= 31 and a.invoice_dueday <= 60 then (a.payor_invoice - coalesce(wo.writeoff_amount,0) - coalesce(rp.receipt_amount,0)) else 0 end) aging_31_60,
                (case when a.invoice_dueday >= 61 and a.invoice_dueday <= 90 then (a.payor_invoice - coalesce(wo.writeoff_amount,0) - coalesce(rp.receipt_amount,0)) else 0 end) aging_61_90,
                (case when a.invoice_dueday >= 91 then (a.payor_invoice - coalesce(wo.writeoff_amount,0) - coalesce(rp.receipt_amount,0)) else 0 end) aging_90
            from (
                select 
                    a.company_id,
                    a.payor_code,
                    a.payor_name,
                    a.payor_type,
                    a.tpa_code,
                    a.tpa_name,
                    a.invoice_no,
                    a.invoice_date,
                    a.invoice_sent,
                    a.invoice_crediterm,
                    a.invoice_maturity,
                    --extract(day from (current_date - a.invoice_maturity))::int as invoice_dueday,
                    (current_date - a.invoice_maturity)::int AS invoice_dueday, 
                    a.admission_no,
                    a.admission_date,
                    a.aggreement_name, 
                    (case sob.patient_type 
                        when '1' then 'OP' 
                        when '2' then 'IP'
                        when '3' then 'Emergency' 
                        when '4' then 'DayCare' 
                        else 'OP'
                    end) patient_type,
                    a.bill_type,
                    a.bill_id,
                    a.bill_no,
                    a.bill_date,
                    a.patient_mrid,
                    a.patient_name,
                    sum(a.payor_invoice) payor_invoice
                from receivable_invoice_letter a 
                left join sale_order_bill sob on sob.id = a.odoo_bill_id 
                where a.company_id = {company_id} 
                    and date(a.cutoff_date) <= '{date_end}' -- filter cutoff date 
                    {partner_ids} --and a.tpa_id = coalesce(null, a.tpa_id) -- filter specific for tpa_id
                group by 
                    a.company_id, 
                    a.payor_code,
                    a.payor_name,
                    a.payor_type,
                    a.tpa_code,
                    a.tpa_name,
                    a.invoice_no,
                    a.invoice_date,
                    a.invoice_sent,
                    a.invoice_crediterm,
                    a.invoice_maturity,
                    --extract(day from (current_date - a.invoice_maturity))::int,
                    (current_date - a.invoice_maturity)::int,
                    a.admission_no,
                    a.admission_date,
                    a.aggreement_name, 
                    (case sob.patient_type 
                        when '1' then 'OP' 
                        when '2' then 'IP'
                        when '3' then 'Emergency' 
                        when '4' then 'DayCare' 
                        else 'OP'
                    end),
                    a.bill_type,
                    a.bill_id,
                    a.bill_no,
                    a.bill_date,
                    a.patient_mrid,
                    a.patient_name
            ) a 
            left join lateral (
                select sum(coalesce(wo.amount,0)) as writeoff_amount
                from receivable_writeoff wo 
                where wo.company_id = a.company_id 
                    and wo.invoice_no = a.invoice_no
                    and wo.bill_id = a.bill_id
                    and date(wo.cutoff_date) <= '{date_end}' -- filter cutoff date 
            ) wo on 1=1 
            left join lateral (
                select sum(coalesce(rp.amount,0)) receipt_amount
                from receivable_settlement_source rp 
                where rp.company_id = a.company_id 
                    and rp.bill_id = a.bill_id 
                    and date(rp.cutoff_date) <= '{date_end}' -- filter cutoff date 
            ) rp on 1=1 

            where (
                (a.payor_invoice - coalesce(wo.writeoff_amount,0) - coalesce(rp.receipt_amount,0)) <> 0 or 
                (date(a.invoice_date) > (current_date - interval '31 days'))
            )
        ) a 
        group by 
            a.payor_code,
            a.payor_name,
            a.payor_type,
            a.tpa_code,
            a.tpa_name
        order by a.payor_code desc
        """.format(company_id=company_id, 
            date_start=date_start, 
            date_end=date_end,
            partner_ids=("and a.odoo_tpa_id in " + str(tuple(partner_ids)) if partner_ids else "" ))

        query = sudo.env.cr.execute(query)
        results = sudo.env.cr.dictfetchall()

        # looping data 
        row = 5
        sno = 1
        if results:
            for line in results:
                worksheet.write(row, 0, sno, format_content)
                worksheet.write(row, 1, line['payor_code'], format_content)
                worksheet.write(row, 2, line['payor_name'], format_content)
                worksheet.write(row, 3, line['payor_type'], format_content)
                worksheet.write(row, 4, line['tpa_code'], format_content)
                worksheet.write(row, 5, line['tpa_name'], format_content)
                worksheet.write(row, 6, line['invoice_amount'], format_currency)
                worksheet.write(row, 7, line['writeoff_amount'], format_currency)
                worksheet.write(row, 8, line['receipt_amount'], format_currency)
                worksheet.write(row, 9, line['balance_amount'], format_currency)
                worksheet.write(row, 10, line['aging_0'], format_currency)
                worksheet.write(row, 11, line['aging_1_30'], format_currency)
                worksheet.write(row, 12, line['aging_31_60'], format_currency)
                worksheet.write(row, 13, line['aging_61_90'], format_currency)
                worksheet.write(row, 14, line['aging_90'], format_currency)

                row += 1
                sno += 1

            # Baris TOTAL
            worksheet.write(row, 0, 'TOTAL', format_footer)
            for col in range(1, 6):
                worksheet.write(row, col, '', format_footer)
            worksheet.write(row, 6, '=SUM(G6:G' + str(row) + ')', format_footer)   # invoice_amount
            worksheet.write(row, 7, '=SUM(H6:H' + str(row) + ')', format_footer)   # writeoff_amount
            worksheet.write(row, 8, '=SUM(I6:I' + str(row) + ')', format_footer)   # receipt_amount
            worksheet.write(row, 9, '=SUM(J6:J' + str(row) + ')', format_footer)   # balance_amount
            worksheet.write(row, 10, '=SUM(K6:K' + str(row) + ')', format_footer)  # aging_0
            worksheet.write(row, 11, '=SUM(L6:L' + str(row) + ')', format_footer)  # aging_1_30
            worksheet.write(row, 12, '=SUM(M6:M' + str(row) + ')', format_footer)  # aging_31_60
            worksheet.write(row, 13, '=SUM(N6:N' + str(row) + ')', format_footer)  # aging_61_90
            worksheet.write(row, 14, '=SUM(O6:O' + str(row) + ')', format_footer)  # aging_90

            # setup column
            worksheet.set_column(0, 0, 5)       # No.
            worksheet.set_column(1, 3, 18)      # payor_code, payor_name, payor_type
            worksheet.set_column(4, 5, 20)      # tpa_code, tpa_name
            worksheet.set_column(6, 9, 18)      # invoice_amount to balance_amount
            worksheet.set_column(10, 14, 15)    # aging_0 to aging_90



        worksheet.set_zoom(80)
        workbook.close()
        output.seek(0)
        response.stream.write(output.read())
        output.close()
        del output # clear 
        return response


